		Map<?, ?> body = new Gson().fromJson(req.getBody().readUtf8(), Map.class);
		Map<?, ?> snapshot = (Map<?, ?>) body.get("snapshot");
		Map<?, ?> source = (Map<?, ?>) snapshot.get("source");
