/**
 * WAVE 5 — live-state snapshot fields: spellbook, attack_style, prayer_active[], location, world,
 * kourend_favour, minigame_points. Drives syncTask (which force-sends on the first/login tick) and asserts
 * the fields on the wire. Every varbit / varp id used here is javap-verified against runelite-api 1.12.32.
 */
public class Wave5LiveStateTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private MockWebServer server;
	private AccountConnectPlugin plugin;
	private Client client;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	private void inject(String fieldName, Object value) throws Exception
	{
		Field field = AccountConnectPlugin.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	@Test
	public void snapshotCarriesLiveStateFields() throws Exception
	{
		plugin = new AccountConnectPlugin();
		client = mock(Client.class);
		Player player = mock(Player.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(player.getName()).thenReturn("TestPlayer");
		when(player.getCombatLevel()).thenReturn(100);

		// Live-state stubs (verified ids). Unstubbed varbits/varps default to 0; unstubbed prayers to false.
		when(client.getVarbitValue(Varbits.SPELLBOOK)).thenReturn(2);          // lunar (raw)
		when(client.getVarpValue(VarPlayer.ATTACK_STYLE)).thenReturn(3);
		when(client.isPrayerActive(Prayer.THICK_SKIN)).thenReturn(true);
		when(client.getWorld()).thenReturn(330);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(2000, 3000, 1));
		when(client.getVarbitValue(Varbits.KOUREND_FAVOR_HOSIDIUS)).thenReturn(1500);
		when(client.getVarbitValue(Varbits.NMZ_POINTS)).thenReturn(5000);
		when(client.getVarbitValue(Varbits.TITHE_FARM_POINTS)).thenReturn(42);

		ItemManager itemManager = mock(ItemManager.class);
		String baseUrl = server.url("/").toString();
		AccountConnectConfig config = new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

			@Override
			public String apiBaseUrl()
			{
				return baseUrl;
			}
		};
		inject("client", client);
		inject("config", config);
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
		inject("itemManager", itemManager);

		server.enqueue(new MockResponse().setResponseCode(200));
		plugin.syncTask();	// first tick = new login -> force-sends the snapshot

		RecordedRequest req = server.takeRequest(5, TimeUnit.SECONDS);
		assertNotNull("login tick must send a snapshot", req);
		Map<?, ?> body = new Gson().fromJson(req.getBody().readUtf8(), Map.class);
		Map<?, ?> snap = (Map<?, ?>) body.get("snapshot");

		assertEquals(2.0, ((Number) snap.get("spellbook")).doubleValue(), 0.0);
		assertEquals(3.0, ((Number) snap.get("attack_style")).doubleValue(), 0.0);
		assertEquals(330.0, ((Number) snap.get("world")).doubleValue(), 0.0);

		List<?> prayers = (List<?>) snap.get("prayer_active");
		assertTrue("active prayer must be listed by name", prayers.contains("THICK_SKIN"));

		Map<?, ?> loc = (Map<?, ?>) snap.get("location");
		assertEquals(new WorldPoint(2000, 3000, 1).getRegionID() * 1.0,
			((Number) loc.get("region_id")).doubleValue(), 0.0);
		assertEquals(1.0, ((Number) loc.get("plane")).doubleValue(), 0.0);

		Map<?, ?> favour = (Map<?, ?>) snap.get("kourend_favour");
		assertEquals(1500.0, ((Number) favour.get("hosidius")).doubleValue(), 0.0);

		Map<?, ?> minigames = (Map<?, ?>) snap.get("minigame_points");
		assertEquals(5000.0, ((Number) minigames.get("nmz")).doubleValue(), 0.0);
		assertEquals(42.0, ((Number) minigames.get("tithe")).doubleValue(), 0.0);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * RAPID MULTI-ITEM DROP TRADE — the defect this suite exists to prove and then prevent.
 *
 * A "drop trade" delivery is N items dropped in quick succession: the staff member right-clicks Drop on one
 * inventory slot after another, often within the same or adjacent game ticks, and the customer picks them up.
 *
 * The pre-fix implementation held ONE pending slot (`invDeltaPending`). Arming a second Drop before the first
 * had been confirmed by its ground spawn OVERWROTE the first pending, and the first drop then emitted
 * NOTHING — silently, with no error and no trace anywhere in the pipeline. The account's inventory still
 * showed the item gone, so a periodic snapshot looks perfectly consistent while the event is simply absent.
 * That is why snapshots cannot certify event completeness: they confirm final state, not telemetry.
 *
 * These tests drive the real callback order the client produces (arm on MenuOptionClicked, confirm on
 * ItemSpawned / inventory change) and assert on the emitted event buffer.
 */
public class RapidDropTest
{
	private static final int DEATH_RUNE = 560;
	private static final int TBOW = 20997;
	private static final int SCYTHE = 22486;
	private static final int FANG = 26219;

	// ---------------------------------------------------------------- the defect

	/**
	 * FOUR items dropped in rapid succession — the exact shape of a real multi-item drop trade.
	 * Every one is a genuine, completed drop: each has its own menu click, its own ground spawn and its own
	 * inventory loss. All four MUST be emitted.
	 */
	@Test
	public void fourRapidDropsAllEmit() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		int[] items = {TBOW, SCYTHE, FANG, DEATH_RUNE};

		// The player clicks Drop on four slots across two ticks, then each item lands.
		for (int i = 0; i < items.length; i++)
		{
			tick(plugin, 100 + (i / 2));           // two drops per tick
			plugin.onMenuOptionClicked(menu("Drop", "", items[i]));
		}
		for (int i = 0; i < items.length; i++)
		{
			plugin.resolveDropPendingOnGroundSpawn(items[i], 0, 0L, 101);
		}

		List<Integer> emitted = droppedItemIds(plugin);
		assertEquals("every real drop must emit exactly one event; lost drops = silent data loss",
			4, emitted.size());
		assertTrue("tbow drop lost", emitted.contains(TBOW));
		assertTrue("scythe drop lost", emitted.contains(SCYTHE));
		assertTrue("fang drop lost", emitted.contains(FANG));
		assertTrue("rune drop lost", emitted.contains(DEATH_RUNE));
	}

	/** Two drops on the SAME tick — the tightest real case, and the one a single slot always loses. */
	@Test
	public void twoDropsOnTheSameTickBothEmit() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(menu("Drop", "", TBOW));
		plugin.onMenuOptionClicked(menu("Drop", "", SCYTHE));
		plugin.resolveDropPendingOnGroundSpawn(TBOW, 0, 0L, 200);
		plugin.resolveDropPendingOnGroundSpawn(SCYTHE, 0, 0L, 200);

		List<Integer> emitted = droppedItemIds(plugin);
		assertEquals("both same-tick drops must emit", 2, emitted.size());
		assertTrue(emitted.contains(TBOW));
		assertTrue(emitted.contains(SCYTHE));
	}

	/** Ground spawns arriving in a DIFFERENT order than the clicks — the server decides packet order. */
	@Test
	public void outOfOrderGroundSpawnsStillMatchTheirOwnDrop() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 300);
		plugin.onMenuOptionClicked(menu("Drop", "", TBOW));
		plugin.onMenuOptionClicked(menu("Drop", "", SCYTHE));
		plugin.onMenuOptionClicked(menu("Drop", "", FANG));
		// spawns land reversed
		plugin.resolveDropPendingOnGroundSpawn(FANG, 0, 0L, 300);
		plugin.resolveDropPendingOnGroundSpawn(SCYTHE, 0, 0L, 300);
		plugin.resolveDropPendingOnGroundSpawn(TBOW, 0, 0L, 300);

		List<Integer> emitted = droppedItemIds(plugin);
		assertEquals(3, emitted.size());
		assertTrue(emitted.contains(TBOW));
		assertTrue(emitted.contains(SCYTHE));
		assertTrue(emitted.contains(FANG));
	}

	// ---------------------------------------------------------------- no regressions

	/** A single ordinary drop must behave EXACTLY as before. */
	@Test
	public void singleDropUnchanged() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 400);
		plugin.onMenuOptionClicked(menu("Drop", "", DEATH_RUNE));
		assertNotNull("a single drop still arms", firstPending(plugin));
		plugin.resolveDropPendingOnGroundSpawn(DEATH_RUNE, 0, 0L, 400);

		List<Integer> emitted = droppedItemIds(plugin);
		assertEquals(1, emitted.size());
		assertEquals(Integer.valueOf(DEATH_RUNE), emitted.get(0));
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals(5L, e.get("qty"));
		assertEquals(true, e.get("wilderness"));
		assertNotNull("location preserved", e.get("location"));
	}

	/** No duplicates: one ground spawn cannot emit the same drop twice. */
	@Test
	public void aSecondSpawnForAnAlreadyEmittedDropDoesNotDuplicate() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 500);
		plugin.onMenuOptionClicked(menu("Drop", "", TBOW));
		plugin.resolveDropPendingOnGroundSpawn(TBOW, 0, 0L, 500);
		plugin.resolveDropPendingOnGroundSpawn(TBOW, 0, 0L, 500);   // another player's tbow appearing
		assertEquals("a drop must never emit twice", 1, droppedItemIds(plugin).size());
	}

	/**
	 * An inventory removal with NO ground spawn must still never fabricate a drop, even with several
	 * pendings armed — the M3 guarantee must survive the queue.
	 */
	@Test
	public void inventoryRemovalAloneStillNeverFabricatesADrop() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 600);
		plugin.onMenuOptionClicked(menu("Drop", "", TBOW));
		plugin.onMenuOptionClicked(menu("Drop", "", SCYTHE));
		plugin.resolveInvDeltaPending(0L, 0L, 601);       // items left the inventory: bank / equip / destroy
		assertTrue("no ground spawn = no drop, ever", plugin.pendingEvents.isEmpty());
	}

	/** A direct trade must never become a drop event. */
	@Test
	public void aTradeDoesNotArmOrEmitADrop() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 700);
		plugin.onMenuOptionClicked(menu("Trade with", "Leegsonly", TBOW));
		assertNull("a trade click must not arm a drop pending", firstPending(plugin));
		plugin.resolveDropPendingOnGroundSpawn(TBOW, 0, 0L, 700);
		assertTrue("a trade must never emit a drop", plugin.pendingEvents.isEmpty());
	}

	/** Stale pendings expire without emitting and must not block later drops. */
	@Test
	public void anExpiredDropDoesNotBlockALaterDrop() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 800);
		plugin.onMenuOptionClicked(menu("Drop", "", TBOW));     // never lands
		tick(plugin, 900);
		plugin.onMenuOptionClicked(menu("Drop", "", SCYTHE));
		plugin.resolveDropPendingOnGroundSpawn(SCYTHE, 0, 0L, 900);

		List<Integer> emitted = droppedItemIds(plugin);
		assertEquals("the later real drop must still emit", 1, emitted.size());
		assertEquals(Integer.valueOf(SCYTHE), emitted.get(0));
	}

	// ---------------------------------------------------------------- helpers

	private static AccountConnectPlugin newPlugin() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv = container(TBOW, 1, SCYTHE, 1, FANG, 1, DEATH_RUNE, 5);
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv);
		when(client.getVarbitValue(Varbits.IN_WILDERNESS)).thenReturn(1);
		when(client.getTickCount()).thenReturn(100);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3100, 3900, 0));
		inject(plugin, "client", client);
		return plugin;
	}

	private static void tick(AccountConnectPlugin plugin, int t) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		Client c = (Client) f.get(plugin);
		when(c.getTickCount()).thenReturn(t);
	}

	private static List<Integer> droppedItemIds(AccountConnectPlugin plugin)
	{
		List<Integer> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if ("drop".equals(e.get("type")))
			{
				out.add((Integer) e.get("item"));
			}
		}
		return out;
	}

	private static AccountConnectPlugin.InvDeltaPending firstPending(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("invDeltaPendings");
		f.setAccessible(true);
		java.util.Deque<?> d = (java.util.Deque<?>) f.get(plugin);
		return d.isEmpty() ? null : (AccountConnectPlugin.InvDeltaPending) d.peekFirst();
	}

	private static MenuOptionClicked menu(String option, String target, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn(option);
		when(m.getMenuTarget()).thenReturn(target);
		when(m.getItemId()).thenReturn(itemId);
		return m;
	}

	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static AccountConnectConfig onConfig()
	{
		return (AccountConnectConfig) java.lang.reflect.Proxy.newProxyInstance(
			AccountConnectConfig.class.getClassLoader(),
			new Class<?>[]{AccountConnectConfig.class},
			(proxy, method, args) -> {
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class || rt == Boolean.class)
				{
					return Boolean.TRUE;
				}
				if (rt == String.class)
				{
					return "0123456789abcdef0123456789abcdef";
				}
				if (rt == int.class || rt == Integer.class)
				{
					return 0;
				}
				return null;
			});
	}
}

package com.osrsbestinslot.export;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClipRingBufferTest
{
	/** One encoded frame, tagged by its first byte so order is checkable. */
	private static byte[] frame(int tag, int size)
	{
		byte[] b = new byte[size];
		b[0] = (byte) tag;
		return b;
	}

	private static byte[] frame(int tag)
	{
		return frame(tag, 4);
	}

	@Test
	public void evictsOldestAtCapacity()
	{
		ClipRingBuffer ring = new ClipRingBuffer(3);
		for (int i = 1; i <= 5; i++) { ring.add(frame(i)); }
		List<byte[]> snap = ring.snapshot();
		assertEquals(3, snap.size());
		assertEquals(3, snap.get(0)[0]);	// oldest surviving = #3
		assertEquals(5, snap.get(2)[0]);	// newest = #5
	}

	@Test
	public void ignoresNullEmptyAndClears()
	{
		ClipRingBuffer ring = new ClipRingBuffer(2);
		ring.add(null);
		ring.add(new byte[0]);		// a failed encode returns empty — must not occupy a slot
		assertEquals(0, ring.size());
		ring.add(frame(1));
		ring.clear();
		assertEquals(0, ring.size());
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsZeroCapacity()
	{
		new ClipRingBuffer(0);
	}

	/**
	 * THE REGRESSION THIS CLASS EXISTS FOR (2026-09-02). The ring used to hold decoded BufferedImages:
	 * at 30fps x 12s x 704px that is ~1.1MB per frame and ~400MB retained for a whole shop visit, past
	 * RuneLite's 512MB default heap — the client froze in continuous GC and no burst ever uploaded.
	 * Holding ENCODED bytes, a full ring is ~30KB per frame.
	 *
	 * Falsified 2026-09-02: re-run with jpegBytes = 1_115_136 (one decoded 704x396 RGB frame) and this
	 * arm FAILS, which is the state that shipped in 0.7.5.
	 */
	@Test
	public void retainedBytesAreBoundedByCapacityNotVisitLength()
	{
		final int fps = 30, seconds = 12, jpegBytes = 30_000;
		ClipRingBuffer ring = new ClipRingBuffer(fps * seconds);
		// Ten times more frames than fit — a long shop visit.
		for (int i = 0; i < fps * seconds * 10; i++) { ring.add(frame(i & 0x7F, jpegBytes)); }
		assertEquals(fps * seconds, ring.size());
		assertEquals((long) fps * seconds * jpegBytes, ring.byteSize());
		// ~11MB, an order of magnitude under the ~400MB decoded footprint that froze the client.
		assertTrue("retained " + ring.byteSize() + " bytes", ring.byteSize() < 20_000_000L);
	}

	/** An empty ring must report zero bytes, not throw — the degenerate arm. */
	@Test
	public void emptyRingReportsZeroBytes()
	{
		assertEquals(0L, new ClipRingBuffer(8).byteSize());
	}
}

package com.osrsbestinslot.export;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The shop-stock diagnostic. It is about to be quoted as evidence for what a reset actually is, so
 * it gets one known-bad run first: a trace that silently writes nothing, or writes the wrong delta,
 * would send the next fix in the wrong direction.
 */
public class ShopTraceTest
{
	/**
	 * A NORMAL BUILD WRITES NOTHING.
	 *
	 * The arm is written as an A/B on ONE file rather than as "some temp path stays absent", which
	 * proves nothing: the plugin was never pointed at that path, so the assertion held whatever the
	 * code did. Here the property is set, a change is traced, the file's size is recorded, then the
	 * property is cleared and the same changes are replayed. The file must not grow by one byte.
	 *
	 * KNOWN LIMIT, stated because it is real: this kills a stale-or-removed guard, which is the
	 * regression that can actually happen. It cannot kill a trace rewritten to a hard-coded constant
	 * path, because a black-box test cannot enumerate every path the process might write.
	 */
	@Test
	public void writesNothingUnlessExplicitlyEnabled() throws Exception
	{
		Path out = Files.createTempFile("shoptrace-ab", ".log");
		Files.delete(out);
		try
		{
			System.setProperty("osrsbis.shoptrace", out.toString());
			AccountConnectPlugin on = configured();
			on.handleShopStockChanged(container(new int[][]{{561, 1}}));
			on.handleShopStockChanged(container(new int[][]{{561, 0}}));
			assertTrue("the control arm must prove the trace CAN write", Files.exists(out));
			long enabledSize = Files.size(out);
			assertTrue("the enabled trace must have content", enabledSize > 0);

			System.clearProperty("osrsbis.shoptrace");
			AccountConnectPlugin off = configured();
			off.handleShopStockChanged(container(new int[][]{{561, 1}}));
			off.handleShopStockChanged(container(new int[][]{{561, 0}}));

			assertEquals("a normal build must write no trace at all",
				enabledSize, Files.size(out));
		}
		finally
		{
			System.clearProperty("osrsbis.shoptrace");
			Files.deleteIfExists(out);
		}
	}

	@Test
	public void recordsTheItemsThatActuallyChanged() throws Exception
	{
		Path out = Files.createTempFile("shoptrace", ".log");
		Files.delete(out);
		System.setProperty("osrsbis.shoptrace", out.toString());
		try
		{
			AccountConnectPlugin p = configured();
			p.handleShopStockChanged(container(new int[][]{{561, 1}, {995, 10}}));	// baseline
			p.handleShopStockChanged(container(new int[][]{{561, 0}, {995, 11}}));	// a reset shape

			String text = new String(Files.readAllBytes(out), "UTF-8");
			String[] lines = text.split("\n");
			// The fixture is deliberately a real tick shape (one fall + one rise), so the plugin
			// also writes its ANCHOR line. Assert on CONTENT rather than a line count, which would
			// break every time a new diagnostic line is added.
			String delta = null;
			for (String l : lines)
			{
				if (l.contains("delta=") && l.contains("561:1->0"))
				{
					delta = l;
				}
			}
			assertTrue("the fall must be recorded", delta != null);
			assertTrue("the restock must be recorded too", delta.contains("995:10->11"));
			// KNOWN-BAD CONTROL: an unchanged container must NOT look like a change.
			p.handleShopStockChanged(container(new int[][]{{561, 0}, {995, 11}}));
			String all = new String(Files.readAllBytes(out), "UTF-8");
			assertTrue("an unchanged read must say so", all.contains("(none)"));
		}
		finally
		{
			System.clearProperty("osrsbis.shoptrace");
			Files.deleteIfExists(out);
		}
	}

	private static AccountConnectPlugin configured() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	private static net.runelite.api.ItemContainer container(int[][] items)
	{
		net.runelite.api.ItemContainer c = org.mockito.Mockito.mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] arr = new net.runelite.api.Item[items.length];
		for (int i = 0; i < items.length; i++)
		{
			arr[i] = new net.runelite.api.Item(items[i][0], items[i][1]);
		}
		org.mockito.Mockito.when(c.getItems()).thenReturn(arr);
		return c;
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Wave 3 firehose: high-frequency rows buffered and emitted as ONE fh_batch event.
 *
 * THE GRANT IS SERVER-SIDE AND THERE IS NO CONFIG ITEM. The original commit gated this on a
 * `maximumCapture` toggle in the plugin's own settings. The operator default (2026-09-19) is that this
 * plugin carries no user-facing settings, so the gate moved onto the X-Max-Capture response header,
 * exactly like the existing X-Store-Tools grant. These tests pin that an ungranted client captures
 * nothing at all, which is the property that keeps other players' names off every ordinary client.
 */
public class Wave3FirehoseTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	// 0.7.14 removed the enableUpload switch: uploadAllowed() is the link token alone, so the config
	// here only carries a token.
	private static AccountConnectConfig config(final String token)
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return token;
			}
		};
	}

	/** A plugin with a linked token. The firehose grant is still OFF until the server sets it. */
	private static AccountConnectPlugin plug() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", config(TOKEN));
		return p;
	}

	private static Map<String, Object> row(String k, Object v)
	{
		Map<String, Object> d = new LinkedHashMap<>();
		d.put(k, v);
		return d;
	}

	@Test
	public void ungrantedClientBuffersNothing() throws Exception
	{
		AccountConnectPlugin p = plug();
		assertTrue("no grant = not capturing", !p.maxCapture());
		p.firehose("pos", row("x", 3200));
		p.firehose("nearby", row("rsn", "Someone Else"));
		p.flushFirehose();
		assertTrue("an ungranted client emits nothing at all", p.pendingEvents.isEmpty());
	}

	@Test
	public void grantedClientBatchesRowsIntoOneEvent() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.serverMaxCaptureEnabled = true;
		p.firehose("pos", row("x", 3200));
		p.firehose("pos", row("x", 3201));
		p.firehose("anim", row("id", 829));
		assertTrue("buffered, not emitted per row", p.pendingEvents.isEmpty());
		p.flushFirehose();
		assertEquals("one batch event", 1, p.pendingEvents.size());
		Map<String, Object> ev = p.pendingEvents.get(0);
		assertEquals("fh_batch", ev.get("type"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> rows = (List<Map<String, Object>>) ev.get("events");
		assertEquals(3, rows.size());
		assertEquals("pos", rows.get(0).get("k"));
		assertEquals("anim", rows.get(2).get("k"));
	}

	@Test
	public void bufferIsCappedAndDropsOverflow() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.serverMaxCaptureEnabled = true;
		for (int i = 0; i < 600; i++)
		{
			p.firehose("pos", row("x", i));
		}
		p.flushFirehose();
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> rows = (List<Map<String, Object>>) p.pendingEvents.get(0).get("events");
		assertEquals("hard cap holds at 500", 500, rows.size());
	}

	@Test
	public void flushOnAnEmptyBufferEmitsNothing() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.serverMaxCaptureEnabled = true;
		p.flushFirehose();
		assertTrue("an empty flush is not an empty batch event", p.pendingEvents.isEmpty());
	}

	@Test
	public void grantAloneIsNotEnoughWithAMalformedToken() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", config("not-a-token"));	// uploadAllowed() is false
		p.serverMaxCaptureEnabled = true;		// server granted anyway
		assertTrue("a malformed token beats a server grant", !p.maxCapture());
		p.firehose("pos", row("x", 3200));
		p.flushFirehose();
		assertTrue(p.pendingEvents.isEmpty());
	}

	@Test
	public void grantAloneIsNotEnoughWithoutALinkedToken() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", config(""));
		p.serverMaxCaptureEnabled = true;
		assertTrue("no token beats a server grant", !p.maxCapture());
		p.firehose("pos", row("x", 3200));
		p.flushFirehose();
		assertTrue(p.pendingEvents.isEmpty());
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the store delivery-proof burst capture path (Task B2) — no live client needed.
 * Covers: the opt-in default (off), the server force-disable gate, wall-clock 1-in-time decimation,
 * and the RGB (no-alpha) frame conversion the JDK JPEG writer requires. The listener wiring, real
 * shop-widget event delivery, and the multipart upload (B3) need a live client / are covered elsewhere.
 */
public class StoreClipCaptureTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	/** Config with a linked token — the ONLY local condition for capture since the toggle was removed. */
	private static AccountConnectConfig linked()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		};
	}

	// (a) no link token -> no capture. The separate opt-in toggle was removed 2026-09-02; capture is now
	// part of core sync, so the token IS the gate. An unlinked client must still capture nothing.
	@Test
	public void storeClipsDisabledWithoutLinkToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
});
		assertFalse("store-clip capture must be off with no link token",
			plugin.storeClipsEnabled());
	}

	// (a2) a malformed token is not a link — same refusal as none at all.
	@Test
	public void storeClipsDisabledOnMalformedToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "not-a-token";
			}
		});
		assertFalse("a malformed token must not enable capture", plugin.storeClipsEnabled());
	}

	// (b) server force-disable wins even when the client IS linked.
	@Test
	public void serverForceDisableOverridesLinkedToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", linked());
		// linked, server not disabling -> enabled.
		assertTrue("a linked token with no server disable must enable capture",
			plugin.storeClipsEnabled());
		// server flips it off -> gate closes despite the link.
		plugin.serverClipsDisabled = true;
		assertFalse("server X-Clips=off must force capture off",
			plugin.storeClipsEnabled());
	}

	// (c) wall-clock decimation: 50 render frames across one simulated second -> exactly CLIP_FPS samples.
	//
	// The expectation is DERIVED from CLIP_FPS, not hardcoded. It used to assert a literal 1, so raising
	// the sample rate to 2 on 2026-09-02 turned this red for the rate change rather than for a defect —
	// a test that fails when the thing it measures is deliberately changed is testing the constant, not
	// the decimation. What must hold at ANY rate is: exactly CLIP_FPS samples per second, and the same
	// again in the following second (a rate, never a one-shot).
	@Test
	public void wallClockDecimationYieldsOneSamplePerSecond()
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		// nextClipSampleAt defaults to 0; walk 50 evenly-spaced nanoTime ticks over exactly one second
		// (~50fps render). Only every (1/CLIP_FPS)s boundary should cross the gate.
		long oneSecond = 1_000_000_000L;
		int trues = 0;
		for (int i = 0; i < 50; i++)
		{
			long now = i * (oneSecond / 50);	// 0ms, 20ms, ... 980ms
			if (plugin.shouldSampleClipFrame(now))
			{
				trues++;
			}
		}
		// Exact equality is the WRONG assertion above 1fps and asserting it hid a real property. The gate
		// advances by exactly 1/CLIP_FPS seconds, but render ticks land on a 20ms grid, so each sample
		// fires at the first tick AT OR AFTER its boundary and the remainder carries into the next
		// second: at 8fps a 50-tick second yields 8 then 7, alternating, averaging 8. That is correct
		// decimation, not drift — the gate never loses time, it only rounds each sample forward. So the
		// per-second count is asserted within +/-1 and the TWO-second total is asserted exactly, which
		// is what actually proves the rate.
		assertTrue("expected ~CLIP_FPS samples across one simulated second, got " + trues,
			Math.abs(trues - AccountConnectPlugin.CLIP_FPS) <= 1);
		// MOUSE VISIBILITY is the floor, not "enough to catch the transaction". A cursor crossing a shop
		// interface reads as movement only when consecutive frames are ~125ms apart; 3fps (333ms) was
		// rejected on review as too laggy to see the mouse at all. Asserted independently of whatever
		// CLIP_FPS currently is, so lowering the rate for a byte saving turns this RED.
		assertTrue("a delivery clip must sample at the client's own render rate (30fps) to read as motion",
			AccountConnectPlugin.CLIP_FPS >= 30);
		// The burst must fit the SERVER's frame-count cap. This is 240 only because the ingest cap was
		// raised to 360 in the same change (osrsbis-web-integrator backend.js FRAMES_COUNT_MAX); with the
		// old 120 the server 400s the whole burst — it does not trim it — so this number and the server's
		// must move together, and this assertion is what catches them drifting apart.
		// The visit's frames no longer have to fit ONE request: the upload is chunked. What must hold is
		// that a CHUNK fits the smallest server frame cap ever deployed (120), with margin. This is the
		// assertion that lets clip length grow without a server deploy — and that turns red if someone
		// raises the chunk size back up to the current cap and re-couples the two.
		assertTrue("a chunk must fit the smallest deployed server frame cap (120) with margin",
			AccountConnectPlugin.CLIP_CHUNK_FRAMES <= 100);
		assertTrue("chunking must actually chunk a full visit",
			AccountConnectPlugin.MAX_CLIP_FRAMES > AccountConnectPlugin.CLIP_CHUNK_FRAMES);
		// And it must fit the BYTE cap at the measured mean frame size (56KB over 68 real frames), or the
		// newest-suffix trim silently discards the opening of the visit.
		// 30KB is the MEASURED mean at the current MAX_FRAME_WIDTH/quality (704px, q0.55). If either is
		// raised, this arm goes red — which is the point: the frame size and the frame count are one
		// budget, and changing one without the other silently truncates the start of every visit.
		// This is the VISIT budget (memory + total upload), not a per-request limit.
		assertTrue("fps x seconds at ~30KB/frame (704px q0.55) must fit the 16 MiB visit budget",
			(long) AccountConnectPlugin.MAX_CLIP_FRAMES * 30 * 1024
				<= AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertEquals("frame width must stay at the legibility floor that the byte budget assumes",
			704, AccountConnectPlugin.MAX_FRAME_WIDTH);

		// A second simulated second must yield the next sample — proves it is a rate, not a one-shot.
		int trues2 = 0;
		for (int i = 50; i < 100; i++)
		{
			long now = i * (oneSecond / 50);	// 1000ms .. 1980ms
			if (plugin.shouldSampleClipFrame(now))
			{
				trues2++;
			}
		}
		assertTrue("expected ~CLIP_FPS more samples across the next simulated second, got " + trues2,
			Math.abs(trues2 - AccountConnectPlugin.CLIP_FPS) <= 1);
		// The two-second total is exact: rounding each sample forward must not COST a sample.
		assertEquals("two simulated seconds must yield exactly 2x CLIP_FPS samples",
			2 * AccountConnectPlugin.CLIP_FPS, trues + trues2);

		// Over a LONG span the rate must not drift. This is the arm that caught the real defect: the
		// gate used to advance from the observed tick, so each sample's rounding error compounded and
		// 8fps delivered ~7.5. Ten simulated seconds at a 50fps render must yield 10x CLIP_FPS.
		AccountConnectPlugin p2 = new AccountConnectPlugin();
		int over10s = 0;
		for (int i = 0; i < 500; i++)
		{
			if (p2.shouldSampleClipFrame(i * (oneSecond / 50)))
			{
				over10s++;
			}
		}
		assertEquals("ten simulated seconds must yield exactly 10x CLIP_FPS samples — no cumulative drift",
			10 * AccountConnectPlugin.CLIP_FPS, over10s);

		// A long stall must NOT produce a catch-up burst on consecutive frames: duplicating one instant
		// is not evidence. After a 5-second gap the next tick samples once, and the tick right after it
		// (20ms later, well inside the 125ms period) must not.
		AccountConnectPlugin p3 = new AccountConnectPlugin();
		assertTrue("first call always samples", p3.shouldSampleClipFrame(0L));
		assertTrue("the tick after a long stall samples once", p3.shouldSampleClipFrame(5 * oneSecond));
		assertFalse("...and does not fire again 20ms later",
			p3.shouldSampleClipFrame(5 * oneSecond + oneSecond / 50));
	}

	// (d) RGB conversion: an ARGB frame becomes TYPE_INT_RGB (the JDK JPEG writer corrupts ARGB rasters).
	@Test
	public void toRgbFrameProducesNonAlphaRgb()
	{
		BufferedImage argb = new BufferedImage(32, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = argb.createGraphics();
		g.setColor(Color.ORANGE);
		g.fillRect(0, 0, 32, 24);
		g.dispose();

		BufferedImage rgb = AccountConnectPlugin.toRgbFrame(argb);
		assertNotNull("toRgbFrame returned null for a valid image", rgb);
		assertEquals("frame must be TYPE_INT_RGB (no alpha) for the JPEG writer",
			BufferedImage.TYPE_INT_RGB, rgb.getType());
		assertEquals("width must be preserved", 32, rgb.getWidth());
		assertEquals("height must be preserved", 24, rgb.getHeight());
	}

	/**
	 * WEDGE ARM (added 2026-09-02 after mutation testing): clipFramePending is a one-in-flight latch, so
	 * ANY path out of the frame callback must clear it. A DrawManager that hands back a null image — the
	 * documented shape when the GPU plugin owns the surface — must not leave the latch set, or capture
	 * silently stops for the rest of the visit after one bad frame and the clip is short or empty.
	 *
	 * Falsified: removing the `clipFramePending = false` from the null branch of onClipFrameTick makes
	 * this arm fail. Without it that mutation survived the whole suite.
	 */
	@Test
	public void nullFrameDoesNotWedgeCapture() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", linked());
		// A DrawManager whose listener is invoked immediately with a null image.
		inject(plugin, "drawManager", new net.runelite.client.ui.DrawManager()
		{
			@Override
			public void requestNextFrameListener(java.util.function.Consumer<java.awt.Image> consumer)
			{
				consumer.accept(null);
			}
		});
		inject(plugin, "clipCapturing", true);
		inject(plugin, "clipVisit", new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES));

		plugin.onClipFrameTick();		// first sample: null frame comes back
		assertFalse("a null frame must release the in-flight latch", pending(plugin));

		plugin.onClipFrameTick();		// a wedged latch would make this a no-op forever
		assertFalse("capture must still be able to request further frames", pending(plugin));
	}

	private static boolean pending(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("clipFramePending");
		f.setAccessible(true);
		return f.getBoolean(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Pile-centred candidates and the one rule that turns them into a name.
 *
 * Every arm here is about REFUSING to name somebody. The Take happens in the other player's client
 * and nothing in our stream proves who made it, so the only case worth naming is the one a human
 * would accept on sight: exactly one player standing on the pile's own tile.
 */
public class DropCandidatesTest
{
	private static final int PX = 3200;
	private static final int PY = 3400;

	private static DropCandidates.Observed at(String rsn, int x, int y)
	{
		return new DropCandidates.Observed(rsn, x, y, 0, 100);
	}

	private static DropCandidates.Observed atPlane(String rsn, int x, int y, int plane)
	{
		return new DropCandidates.Observed(rsn, x, y, plane, 100);
	}

	private static List<Map<String, Object>> candidates(DropCandidates.Observed... players)
	{
		return DropCandidates.candidatesAt(Arrays.asList(players), PX, PY, 0);
	}

	// ---- the resolve rule ----

	@Test
	public void exactlyOnePlayerOnTheTileResolves()
	{
		List<Map<String, Object>> c = candidates(at("Customer", PX, PY));
		assertEquals("Customer", DropCandidates.resolveCounterparty(c));
		assertEquals(DropCandidates.STATUS_RESOLVED,
			DropCandidates.statusFor(c, DropCandidates.resolveCounterparty(c)));
	}

	/** Two on the tile is AMBIGUOUS. Somebody took it and we cannot say which, so we name nobody. */
	@Test
	public void twoPlayersOnTheTileResolveToNobody()
	{
		List<Map<String, Object>> c = candidates(at("Customer", PX, PY), at("Bystander", PX, PY));
		assertNull("never a coin toss between two people", DropCandidates.resolveCounterparty(c));
		assertEquals(DropCandidates.STATUS_AMBIGUOUS, DropCandidates.statusFor(c, null));
	}

	/**
	 * A player ONE STEP AWAY is recorded as evidence but never resolves. This is the difference
	 * between an answer and a coincidence: standing next to a pile is not taking it.
	 */
	@Test
	public void aPlayerOneTileAwayIsEvidenceButNotAnAnswer()
	{
		List<Map<String, Object>> c = candidates(at("Nearby", PX + 1, PY));
		assertEquals("recorded as a candidate", 1, c.size());
		assertEquals(1, c.get(0).get("dist"));
		assertNull(DropCandidates.resolveCounterparty(c));
		assertEquals("an empty TILE is unknown, not ambiguous",
			DropCandidates.STATUS_UNKNOWN, DropCandidates.statusFor(c, null));
	}

	@Test
	public void anEmptyTileWithNobodyAroundIsUnknown()
	{
		List<Map<String, Object>> c = candidates();
		assertTrue(c.isEmpty());
		assertNull(DropCandidates.resolveCounterparty(c));
		assertEquals(DropCandidates.STATUS_UNKNOWN, DropCandidates.statusFor(c, null));
	}

	@Test
	public void nullInputsAreHandledAsUnknown()
	{
		assertTrue(DropCandidates.candidatesAt(null, PX, PY, 0).isEmpty());
		assertNull(DropCandidates.resolveCounterparty(null));
		assertEquals(DropCandidates.STATUS_UNKNOWN, DropCandidates.statusFor(null, null));
	}

	/**
	 * One on the tile plus others nearby still resolves. The rule is about the TILE, not about being
	 * alone in the area — a busy bank would otherwise never resolve anything.
	 */
	@Test
	public void oneOnTheTileResolvesEvenInACrowd()
	{
		List<Map<String, Object>> c = candidates(
			at("Customer", PX, PY),
			at("Passer1", PX + 1, PY + 1),
			at("Passer2", PX - 2, PY),
			at("Passer3", PX, PY + 3));
		assertEquals("Customer", DropCandidates.resolveCounterparty(c));
		assertEquals(4, c.size());
	}

	// ---- geometry ----

	@Test
	public void distanceIsChebyshevTheWayTheGameMeasuresIt()
	{
		// A diagonal step is distance 1 in OSRS, not 1.41. A Euclidean measure would make a diagonal
		// neighbour look further away than an orthogonal one when the game treats them the same.
		assertEquals(1, DropCandidates.tileDistance(0, 0, 1, 1));
		assertEquals(2, DropCandidates.tileDistance(0, 0, 2, 1));
		assertEquals(0, DropCandidates.tileDistance(7, 7, 7, 7));
	}

	@Test
	public void offsetsAreRelativeToThePileNotToUs()
	{
		List<Map<String, Object>> c = candidates(at("Customer", PX + 2, PY - 1));
		assertEquals(2, c.get(0).get("dx"));
		assertEquals(-1, c.get(0).get("dy"));
	}

	@Test
	public void candidatesAreSortedNearestFirst()
	{
		List<Map<String, Object>> c = candidates(
			at("Far", PX + 3, PY), at("OnTile", PX, PY), at("Near", PX + 1, PY));
		assertEquals("OnTile", c.get(0).get("rsn"));
		assertEquals("Near", c.get(1).get("rsn"));
		assertEquals("Far", c.get(2).get("rsn"));
	}

	@Test
	public void playersBeyondTheCandidateRangeAreNotRecorded()
	{
		List<Map<String, Object>> c = candidates(at("TooFar", PX + 4, PY));
		assertTrue("4 tiles is past the 3-tile candidate range", c.isEmpty());
	}

	/** A player on another floor cannot have taken the pile, whatever its x and y. */
	@Test
	public void anotherPlaneIsNeverACandidate()
	{
		List<Map<String, Object>> c = DropCandidates.candidatesAt(
			Arrays.asList(atPlane("Upstairs", PX, PY, 1)), PX, PY, 0);
		assertTrue("directly above the pile is still not on it", c.isEmpty());
		assertEquals(DropCandidates.STATUS_UNKNOWN, DropCandidates.statusFor(c, null));
	}

	@Test
	public void unnamedPlayersAreSkipped()
	{
		List<Map<String, Object>> c = candidates(at(null, PX, PY), at("", PX, PY));
		assertTrue(c.isEmpty());
	}

	@Test
	public void theCandidateListIsCapped()
	{
		DropCandidates.Observed[] crowd = new DropCandidates.Observed[40];
		for (int i = 0; i < crowd.length; i++)
		{
			crowd[i] = at("P" + i, PX, PY);
		}
		List<Map<String, Object>> c = candidates(crowd);
		assertEquals("a crowded tile cannot make the row unbounded",
			DropCandidates.CANDIDATE_CAP, c.size());
		assertNull("and forty people on a tile is still ambiguous", DropCandidates.resolveCounterparty(c));
	}

	@Test
	public void aMalformedCandidateRowNeverResolves()
	{
		// Defensive: a row whose rsn is not a string, or whose dist is missing, must not name anyone.
		java.util.Map<String, Object> bad = new java.util.LinkedHashMap<>();
		bad.put("rsn", 12345);
		bad.put("dist", 0);
		assertNull(DropCandidates.resolveCounterparty(Arrays.asList(bad)));

		java.util.Map<String, Object> noDist = new java.util.LinkedHashMap<>();
		noDist.put("rsn", "Someone");
		assertNull(DropCandidates.resolveCounterparty(Arrays.asList(noDist)));
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.ArrayList;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetClosed;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for the own-account activity log (syncActivityLog). No live client needed: exercises the
 * buffer/emit/session-end logic directly. NOT covered here (needs a live client / manual test plan):
 * trackSessionStart reading a real logged-in player, the @Schedule flush timing, and the /event-ingest
 * endpoint round-trip.
 */
public class EventLogTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";

	/** A linked config: valid token → activity log active (core sync, no toggle). */
	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	@Test
	public void noTokenEmitIsNoOp() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
}); // linkToken() == "" → activity log inactive
		plugin.emitEvent("login", null);
		assertTrue("no token must buffer nothing", plugin.pendingEvents.isEmpty());
	}

	@Test
	public void emitBuffersOwnAccountEvent() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "activeRsn", "OSRS BOI");
		inject(plugin, "activeHash", "12345");
		plugin.emitEvent("login", null);

		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("login", ev.get("type"));
		assertEquals("OSRS BOI", ev.get("rsn"));
		assertEquals("12345", ev.get("account_hash"));
		assertTrue("ts must be stamped", ((Long) ev.get("ts")) > 0L);
	}

	@Test
	public void emitMergesExtraFields() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("session_ms", 4200L);
		plugin.emitEvent("logout", fields);
		assertEquals(4200L, plugin.pendingEvents.get(0).get("session_ms"));
	}

	@Test
	public void trackLogoutEmitsDurationAndEndsSession() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "activeRsn", "regardo");
		inject(plugin, "activeHash", "999");
		inject(plugin, "sessionActive", true);
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 1500L);

		plugin.trackLogout();
		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("logout", ev.get("type"));
		assertEquals("regardo", ev.get("rsn"));
		assertTrue("session_ms should be >= elapsed", ((Long) ev.get("session_ms")) >= 1500L);

		// session ended → a second logout is a no-op (no duplicate)
		plugin.trackLogout();
		assertEquals("logout must fire once per session", 1, plugin.pendingEvents.size());
	}

	@Test
	public void bufferIsBounded() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		for (int i = 0; i < 600; i++)
		{
			plugin.emitEvent("tick", null);
		}
		assertEquals("buffer must be capped at MAX_PENDING_EVENTS", 500, plugin.pendingEvents.size());
	}

	// ---- The broad chat sweep is REMOVED (0.7.3). These four tests replace the four that asserted it. ----
	// They are written as the INVERSE of the originals, deliberately: the sweep's old inputs are replayed
	// and each must now produce NOTHING. A removal with no test is indistinguishable from an untested one,
	// and the failure mode being guarded against is silent reintroduction under a different event name.

	@Test
	public void gameMessageEmitsNothing() throws Exception
