	@Test
	public void mainScreenCaptureNotOverwrittenByConfirmTextSummary() throws Exception
	{
		// Simulate: the 335 poll already captured the itemised other-offer + name. Then the confirm screen
		// (334) loads with only a "Lots!" text column. The confirm branch must NOT clobber the good capture.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "tradeMainOpen", true);
		inject(plugin, "pendingTradeReceived", itemList(20997, 3));
		inject(plugin, "pendingCounterparty", "Snaauz");
		Client client = mock(Client.class);
		Widget textOnly = mock(Widget.class);
		when(textOnly.getItemId()).thenReturn(-1);
		when(textOnly.getText()).thenReturn("Lots!");
		when(client.getWidget(CONFIRM_RECEIVE)).thenReturn(textOnly);	// confirm value-text column
		when(client.getItemContainer(90)).thenReturn(null);				// own offer empty in this test
		inject(plugin, "client", client);

		plugin.handleActivityWidgetLoaded(TRADE_CONFIRM_GROUP);

		assertFalse("polling stopped at confirm", (boolean) field(plugin, "tradeMainOpen"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> recv = (List<Map<String, Object>>) field(plugin, "pendingTradeReceived");
		assertEquals("main-screen items preserved", 1, recv.size());
		assertEquals(20997, recv.get(0).get("id"));
		assertEquals("Snaauz", field(plugin, "pendingCounterparty"));
		assertNull("no text fallback when items already captured", field(plugin, "pendingReceivedText"));
	}

	@Test
	public void lastNonEmptyPollWins() throws Exception
	{
		// Offer starts empty (just opened), then the other player adds items, then (defensively) an empty
		// read must not wipe the captured offer.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "tradeMainOpen", true);
		Client client = mock(Client.class);
		Widget title = titleOf("Trading With: Bob");
		Widget empty1 = gridOf();
		Widget full = gridOf(new int[]{11832, 1});
		Widget empty2 = gridOf();
		when(client.getWidget(TRADE_TITLE)).thenReturn(title);
		when(client.getWidget(MAIN_OTHER_OFFER))
			.thenReturn(empty1)   // 1st poll: empty offer
			.thenReturn(full)     // 2nd poll: bandos chestplate added
			.thenReturn(empty2);  // 3rd poll: transient empty read
		inject(plugin, "client", client);

		plugin.captureOtherOfferWhileMainOpen();
		assertNull("empty offer leaves buffer null", field(plugin, "pendingTradeReceived"));
		plugin.captureOtherOfferWhileMainOpen();
		plugin.captureOtherOfferWhileMainOpen();
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> recv = (List<Map<String, Object>>) field(plugin, "pendingTradeReceived");
		assertEquals("last NON-EMPTY read retained", 1, recv.size());
		assertEquals(11832, recv.get(0).get("id"));
	}

	@Test
	public void resetClearsTradeMainOpen() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "tradeMainOpen", true);
		java.lang.reflect.Method m = AccountConnectPlugin.class.getDeclaredMethod("resetTradeState");
		m.setAccessible(true);
		m.invoke(plugin);
		assertFalse((boolean) field(plugin, "tradeMainOpen"));
	}

	private static List<Map<String, Object>> itemList(int id, int qty)
	{
		List<Map<String, Object>> l = new ArrayList<>();
		Map<String, Object> mm = new java.util.LinkedHashMap<>();
		mm.put("id", id);
		mm.put("qty", qty);
		l.add(mm);
		return l;
	}

	private static Object field(AccountConnectPlugin plugin, String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The drop-trade session state machine: when recording starts, when it may stop, and which drops
 * belong to one session.
 *
 * The clock is a parameter everywhere, so the races that only show at real timing — a second drop
 * landing inside the 5-second tail, a pile spawning after the action — are driven exactly rather
 * than slept for.
 */
public class DropSessionRecorderTest
{
	private static final long T0 = 1_000_000L;

	private static String key(int item, int seq)
	{
		return DropSessionRecorder.pileKey(item, 3200, 3200, 0, seq);
	}

	// ---- start ----

	@Test
	public void theFirstDropStartsASessionAndNumbersFromOne()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		assertFalse("idle before any drop", r.active());
		assertEquals(1, r.onDropAction("sess-a", T0));
		assertTrue(r.active());
		assertEquals("sess-a", r.sessionId());
		assertEquals(T0, r.startedAtMillis());
	}

	@Test
	public void aSecondDropJoinsTheSameSessionAndNeverStartsANewOne()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("sess-a", T0);
		int seq = r.onDropAction("sess-b-MUST-BE-IGNORED", T0 + 400);
		assertEquals("sequence continues within the session", 2, seq);
		assertEquals("the id of a running session is never replaced", "sess-a", r.sessionId());
		assertEquals(2, r.dropCount());
	}

	/** Rapid multi-drop: eight drops in one tick are ONE session with eight sequence numbers. */
	@Test
	public void rapidMultiDropProducesOneSessionAndUniqueSequences()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		java.util.Set<Integer> seqs = new java.util.LinkedHashSet<>();
		for (int i = 0; i < 8; i++)
		{
			seqs.add(r.onDropAction("sess-" + i, T0));
		}
		assertEquals("eight distinct sequence numbers", 8, seqs.size());
		assertEquals("one session", "sess-0", r.sessionId());
		assertEquals(8, r.dropCount());
	}

	// ---- the tail ----

	@Test
	public void theTailArmsOnlyWhenTheLastPileGoes()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(995, 1), 1);
		r.onDropAction("s", T0);
		r.pileActive(key(995, 2), 2);

		r.pileRemoved(key(995, 1), T0 + 1_000);
		assertFalse("one pile still on the ground — no stop yet", r.stopPending());
		assertFalse(r.shouldStop(T0 + 100_000));

		r.pileRemoved(key(995, 2), T0 + 2_000);
		assertTrue("last pile gone — tail armed", r.stopPending());
		assertFalse("not yet elapsed", r.shouldStop(T0 + 2_000 + 4_999));
		assertTrue("exactly 5s later", r.shouldStop(T0 + 2_000 + 5_000));
	}

	@Test
	public void theTailIsExactlyFiveSeconds()
	{
		assertEquals(5_000L, DropSessionRecorder.TAIL_MILLIS);
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(1, 1), 1);
		r.pileRemoved(key(1, 1), T0);
		assertEquals(5_000L, r.tailRemainingMillis(T0));
		assertEquals(1L, r.tailRemainingMillis(T0 + 4_999));
		assertEquals(0L, r.tailRemainingMillis(T0 + 5_000));
		assertEquals("an overdue tail reads as due now, never negative", 0L, r.tailRemainingMillis(T0 + 9_999));
	}

	/**
	 * THE REQUIREMENT THAT IS EASIEST TO GET WRONG: a drop inside the tail cancels the stop and
	 * continues the SAME session. A naive implementation starts a second recording here, and the two
	 * then overlap.
	 */
	@Test
	public void aDropInsideTheTailCancelsTheStopAndKeepsTheSession()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(995, 1), 1);
		r.pileRemoved(key(995, 1), T0 + 1_000);
		assertTrue(r.stopPending());

		// 3 seconds into the 5-second tail.
		int seq = r.onDropAction("SHOULD-NOT-BE-USED", T0 + 4_000);
		assertFalse("the stop is cancelled", r.stopPending());
		assertEquals("same session", "s", r.sessionId());
		assertEquals("sequence continues", 2, seq);
		assertFalse("and the old deadline must not fire", r.shouldStop(T0 + 6_000));
	}

	@Test
	public void aPileSpawningAfterTheActionAlsoCancelsAnArmedStop()
	{
		// A pile can spawn a tick or two after the click, so a fast session could arm its stop
		// between the action and the spawn. pileActive must clear it.
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(1, 1), 1);
		r.pileRemoved(key(1, 1), T0 + 100);
		assertTrue(r.stopPending());
		r.pileActive(key(1, 2), 2);
		assertFalse(r.stopPending());
	}

	// ---- overlapping piles and repeated items ----

	/**
	 * Two piles of the SAME item on the SAME tile must stay distinguishable. This is the ordinary
	 * shape of a drop trade, not an edge case: a key built from item and tile alone collapses them,
	 * the second removal then finds nothing, and the session stops while a pile is still live.
	 */
	@Test
	public void twoPilesOfTheSameItemOnTheSameTileAreDistinct()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		int a = r.onDropAction("s", T0);
		r.pileActive(key(995, a), a);
		int b = r.onDropAction("s", T0);
		r.pileActive(key(995, b), b);
		assertEquals("two live piles", 2, r.activePileCount());

		r.pileRemoved(key(995, a), T0 + 500);
		assertEquals(1, r.activePileCount());
		assertFalse("the other pile is still live", r.stopPending());
		r.pileRemoved(key(995, b), T0 + 600);
		assertTrue(r.stopPending());
	}

	@Test
	public void anUnknownPileNeverArmsAStop()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(995, 1), 1);
		r.pileRemoved(key(4151, 9), T0 + 100);	// never ours
		assertFalse("an unknown pile must not arm the tail", r.stopPending());
		assertEquals(1, r.activePileCount());
	}

	@Test
	public void removingTheSamePileTwiceDoesNotDoubleCount()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(995, 1), 1);
		r.pileActive(key(995, 2), 2);
		r.pileRemoved(key(995, 1), T0 + 100);
		r.pileRemoved(key(995, 1), T0 + 200);	// duplicate
		assertFalse("a duplicate removal must not empty the set", r.stopPending());
		assertEquals(1, r.activePileCount());
	}

	// ---- finishing ----

	@Test
	public void aCleanSessionFinishesComplete()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(1, 1), 1);
		r.pileRemoved(key(1, 1), T0 + 100);
		assertTrue(r.shouldStop(T0 + 5_100));
		assertEquals(DropSessionRecorder.Outcome.COMPLETE, r.finish());
		assertFalse("finish clears the session", r.active());
		assertNull(r.sessionId());
	}

	@Test
	public void anInterruptFinishesInterrupted()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(1, 1), 1);
		r.interrupt();
		assertTrue("an interrupt is due immediately", r.shouldStop(T0));
		assertEquals(DropSessionRecorder.Outcome.INTERRUPTED, r.finish());
	}

	/**
	 * A session still holding live piles is INTERRUPTED even with no explicit interrupt. The only
	 * way to reach finish() with piles outstanding is an abnormal end, and calling that COMPLETE
	 * would label a partial clip as whole.
	 */
	@Test
	public void finishingWithLivePilesIsInterrupted()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(1, 1), 1);
		assertEquals(DropSessionRecorder.Outcome.INTERRUPTED, r.finish());
	}

	@Test
	public void finishIsIdempotentAndASecondSessionStartsClean()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.finish();
		assertEquals("a second finish on an idle recorder changes nothing",
			DropSessionRecorder.Outcome.COMPLETE, r.finish());

		assertEquals("a new session numbers from 1 again", 1, r.onDropAction("s2", T0 + 60_000));
		assertEquals("s2", r.sessionId());
		assertEquals(1, r.dropCount());
	}

	@Test
	public void callsOnAnIdleRecorderAreSafeNoOps()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.pileActive(key(1, 1), 1);
		r.pileRemoved(key(1, 1), T0);
		r.interrupt();
		assertFalse("none of those may start a session", r.active());
		assertFalse(r.stopPending());
		assertFalse(r.shouldStop(T0 + 1_000_000));
	}

	// ---- long sessions ----

	/**
	 * A drop trade where the customer arrives four minutes later is ONE session, and the recorder
	 * never stops in the middle of it. This is the case the 12-second ring could not serve.
	 */
	@Test
	public void aFourMinuteSessionNeverStopsWhileAPileIsLive()
	{
		DropSessionRecorder r = new DropSessionRecorder();
		r.onDropAction("s", T0);
		r.pileActive(key(995, 1), 1);
		for (long t = T0; t <= T0 + 240_000; t += 5_000)
		{
			assertFalse("must not stop while the pile is on the ground at t=" + (t - T0), r.shouldStop(t));
		}
		r.pileRemoved(key(995, 1), T0 + 240_000);
		assertTrue(r.shouldStop(T0 + 245_000));
	}

	@Test
	public void pileKeyIncludesEveryDiscriminator()
	{
		String a = DropSessionRecorder.pileKey(995, 3200, 3200, 0, 1);
		assertEquals("995:3200:3200:0:1", a);
		assertNotNull(a);
		// Each field alone must change the key.
		assertFalse(a.equals(DropSessionRecorder.pileKey(996, 3200, 3200, 0, 1)));
		assertFalse(a.equals(DropSessionRecorder.pileKey(995, 3201, 3200, 0, 1)));
		assertFalse(a.equals(DropSessionRecorder.pileKey(995, 3200, 3201, 0, 1)));
		assertFalse(a.equals(DropSessionRecorder.pileKey(995, 3200, 3200, 1, 1)));
		assertFalse(a.equals(DropSessionRecorder.pileKey(995, 3200, 3200, 0, 2)));
	}
}

package com.osrsbestinslot.export;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * The visibility gate, exercised through the REAL RuneLite OverlayPanel render path against a real
 * Graphics2D. A unit test of the row builder cannot catch an overlay that draws in the wrong state,
 * and drawing over the game outside a shop is this feature's worst failure.
 */
public class StoreNearbyOverlayRenderTest
{
	/**
	 * A plugin with a linked token. storeToolsEnabled() requires BOTH the server grant and a linked
	 * token, so a config-less plugin cannot represent either state honestly.
	 */
	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	private static Graphics2D graphics()
	{
		BufferedImage img = new BufferedImage(400, 300, BufferedImage.TYPE_INT_ARGB);
		return img.createGraphics();
	}

	@Test
	public void drawsNothingWhileNoShopIsOpen() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(false);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		assertNull("overlay must not render outside a shop", overlay.render(graphics()));
	}

	@Test
	public void drawsWhileAShopIsOpen() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		// No client is injected, so nearbyPlayersSnapshot returns empty — the panel must still draw
		// its title and the explicit "nobody nearby" line rather than vanishing.
		Dimension d = overlay.render(graphics());
		assertNotNull("overlay must render while a shop is open", d);
		// OverlayPanel clears its children at the END of render, so inspect what it BUILT. A panel
		// with only a title is indistinguishable from one whose data source silently broke — the
		// explicit empty-state line is what tells those apart, so assert it is actually produced.
		java.util.List<String[]> rows = StoreNearbyOverlay.visibleRows(plugin.nearbyPlayersSnapshot(6));
		org.junit.Assert.assertTrue("no client injected, so the row list must be empty", rows.isEmpty());
		// One line: the "Nobody nearby" heading. The reset countdown is its own overlay now.
		org.junit.Assert.assertEquals("empty-state heading only",
			1, overlay.builtRowCountForTest());
	}



	/**
	 * THE GATE. These overlays render other players' names, and they are granted only by the
	 * backend to an allowlisted token. A regular player must see nothing even inside a shop.
	 */
	@Test
	public void drawsNothingWhenTheServerHasNotGrantedStoreTools() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		// store tools deliberately NOT granted — this is every ordinary player's state
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		assertNull("ungranted tokens must see no overlay", overlay.render(graphics()));
	}

	/**
	 * THE DEV OVERRIDE IS OFF UNLESS A JVM FLAG SETS IT, and only the exact grant words count.
	 * A Hub build launched normally has no such property, so this can never leak to a player.
	 */
	@Test
	public void theDevOverrideIsOffWithoutTheFlagAndRefusesJunkValues() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		org.junit.Assert.assertFalse("no flag = no override",
			AccountConnectPlugin.storeToolsDevOverride());
		try
		{
			for (String bad : new String[]{"", " ", "off", "false", "0", "yes", "ON"})
			{
				System.setProperty("osrsbis.storetools", bad);
				org.junit.Assert.assertFalse("'" + bad + "' must not grant",
					AccountConnectPlugin.storeToolsDevOverride());
			}
			for (String good : new String[]{"on", "true", "1"})
			{
				System.setProperty("osrsbis.storetools", good);
				org.junit.Assert.assertTrue("'" + good + "' must grant",
					AccountConnectPlugin.storeToolsDevOverride());
			}
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
	}

	/** The override still requires a linked token — it bypasses the server, not the account. */
	@Test
	public void theDevOverrideStillRequiresALinkedToken() throws Exception
	{
		System.setProperty("osrsbis.storetools", "on");
		try
		{
			AccountConnectPlugin unlinked = new AccountConnectPlugin();
			java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
			f.setAccessible(true);
			f.set(unlinked, new AccountConnectConfig()
			{
				@Override
				public String linkToken()
				{
					return "";
				}
			});
			org.junit.Assert.assertFalse("no token = no overlays even with the flag",
				unlinked.storeToolsEnabled());
			org.junit.Assert.assertTrue("linked token + flag = granted", plugin().storeToolsEnabled());
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
	}

	@Test
	public void theGateDefaultsToOff() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		org.junit.Assert.assertFalse("store tools must default OFF", plugin.storeToolsEnabled());
	}

	@Test
	public void repeatedRendersDoNotAccumulateRows() throws Exception
	{
		// OverlayPanel clears its children between frames only when clearChildren is on. If it is
		// not, the panel grows one row per frame and covers the screen within seconds.
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		overlay.render(graphics());
		int afterFirst = overlay.getPanelComponent().getChildren().size();
		for (int i = 0; i < 20; i++)
		{
			overlay.render(graphics());
		}
		int afterMany = overlay.getPanelComponent().getChildren().size();
		org.junit.Assert.assertEquals("panel children grew across frames", afterFirst, afterMany);
	}
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The nearby panel's row selection. Covers what a wrong overlay would actually get wrong:
 * showing a player across the map, drawing a row with no name, or growing without bound.
 */
public class StoreNearbyOverlayTest
{
	private static Map<String, Object> player(String rsn, int dist, Integer cb)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("rsn", rsn);
		m.put("dist", dist);
		if (cb != null)
		{
			m.put("cb", cb);
		}
		return m;
	}

	@Test
	public void formatsNameDistanceAndCombat()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("Light Work G", 1, 114));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals(1, rows.size());
		assertEquals("Light Work G", rows.get(0)[0]);
		assertEquals("beside you  lvl 114", rows.get(0)[1]);
		assertEquals("1", rows.get(0)[2]);		// adjacent => highlighted gold
	}

	@Test
	public void pluralisesBeyondOneTile()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("Zezima", 4, 126));
		assertEquals("4 tiles  lvl 126", StoreNearbyOverlay.visibleRows(in).get(0)[1]);
		assertEquals("4", StoreNearbyOverlay.visibleRows(in).get(0)[2]);
	}

	@Test
	public void dropsPlayersBeyondDisplayRange()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("Close", StoreNearbyOverlay.DISPLAY_RANGE_TILES, 3));
		in.add(player("Far", StoreNearbyOverlay.DISPLAY_RANGE_TILES + 1, 3));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals(1, rows.size());
		assertEquals("Close", rows.get(0)[0]);
	}

	@Test
	public void skipsEntriesMissingNameOrDistance()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		Map<String, Object> noName = new LinkedHashMap<>();
		noName.put("dist", 2);
		in.add(noName);
		Map<String, Object> noDist = new LinkedHashMap<>();
		noDist.put("rsn", "Ghost");
		in.add(noDist);
		in.add(player("Real", 2, 50));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals(1, rows.size());
		assertEquals("Real", rows.get(0)[0]);
	}

	@Test
	public void omitsCombatLevelWhenAbsent()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("NoCb", 3, null));
		assertEquals("3 tiles", StoreNearbyOverlay.visibleRows(in).get(0)[1]);
	}

	@Test
	public void neverDrawsMoreRowsThanTheDisplayCap()
	{
		List<Map<String, Object>> in = new ArrayList<>();
		for (int i = 0; i < StoreNearbyOverlay.DISPLAY_CAP + 10; i++)
		{
			in.add(player("P" + i, 2, 3));
		}
		assertEquals(StoreNearbyOverlay.DISPLAY_CAP, StoreNearbyOverlay.visibleRows(in).size());
	}



	@Test
	public void theAdjacentPlayerIsColouredDifferentlyFromTheRest()
	{
		java.awt.Color adjacent = StoreNearbyOverlay.distanceColor(1);
		java.awt.Color near = StoreNearbyOverlay.distanceColor(3);
		java.awt.Color far = StoreNearbyOverlay.distanceColor(12);
		org.junit.Assert.assertNotEquals("the adjacent player must stand out", adjacent, near);
		org.junit.Assert.assertNotEquals("far players must be dimmer", near, far);
	}

	/**
	 * A LONG RSN MUST NOT WRAP. Seen on the rig: `96pure2382` wrapped and its "9 tiles lvl 22" landed
	 * on the next line, so every row below it read against the wrong player. A truncated name is
	 * recoverable; a misaligned list is actively misleading about who is standing next to you.
	 */
	@Test
	public void longNamesAreTruncatedRatherThanAllowedToWrap()
	{
		String longest = "AAAAAAAAAAAAA";		// 13 chars — longer than any real RSN
		assertTrue(longest.length() > StoreNearbyOverlay.RSN_MAX_CHARS);
		String out = StoreNearbyOverlay.shortenRsn(longest);
		assertEquals(StoreNearbyOverlay.RSN_MAX_CHARS, out.length());
		assertTrue("truncation must be visible", out.endsWith("\u2026"));
	}

	/** Every REAL RSN fits: OSRS caps display names at 12 characters. */
	@Test
	public void everyRealRsnLengthSurvivesUntouched()
	{
		assertTrue("the cap must cover a full-length OSRS name",
			StoreNearbyOverlay.RSN_MAX_CHARS >= 12);
		assertEquals("Light Work G", StoreNearbyOverlay.shortenRsn("Light Work G"));
		assertEquals("96pure2382", StoreNearbyOverlay.shortenRsn("96pure2382"));
	}

	@Test
	public void namesThatFitAreLeftExactlyAsTheyAre()
	{
		// An RSN is an identity. Trimming one that fits would name the wrong player.
		String exact = "AAAAAAAAAAAA";		// exactly RSN_MAX_CHARS, and a real 12-char RSN
		assertEquals(StoreNearbyOverlay.RSN_MAX_CHARS, exact.length());
		assertEquals(exact, StoreNearbyOverlay.shortenRsn(exact));
		assertEquals("Zezima", StoreNearbyOverlay.shortenRsn("Zezima"));
		assertEquals("", StoreNearbyOverlay.shortenRsn(null));
	}

	@Test
	public void theRowBuilderAppliesTheTruncation()
	{
		java.util.List<java.util.Map<String, Object>> in = new ArrayList<>();
		in.add(player("ThisNameIsWayTooLong", 3, 50));
		String shown = StoreNearbyOverlay.visibleRows(in).get(0)[0];
		assertTrue("rows must carry the shortened name", shown.length() <= StoreNearbyOverlay.RSN_MAX_CHARS);
	}

	@Test
	public void emptyAndNullInputProduceNoRows()
	{
		assertTrue(StoreNearbyOverlay.visibleRows(new ArrayList<>()).isEmpty());
		assertTrue(StoreNearbyOverlay.visibleRows(null).isEmpty());
	}

	@Test
	public void preservesTheOrderItIsGiven()
	{
		// nearbyPlayersSnapshot sorts nearest-first; the panel must not reshuffle that.
		List<Map<String, Object>> in = new ArrayList<>();
		in.add(player("A", 1, 3));
		in.add(player("B", 5, 3));
		in.add(player("C", 9, 3));
		List<String[]> rows = StoreNearbyOverlay.visibleRows(in);
		assertEquals("A", rows.get(0)[0]);
		assertEquals("B", rows.get(1)[0]);
		assertEquals("C", rows.get(2)[0]);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import org.junit.Test;

/**
 * WAVE 3 — event enrichment: logout reason (idle / manual / six_hour_cap / connection_lost), login+logout
 * wealth, level_up xp, and death location. store_* price is intentionally NOT added (no clean transacted-price
 * API off the shop widget — see the note in onMenuOptionClicked); items-lost on death is deferred likewise.
 */
public class Wave3EnrichmentTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		};
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static AccountConnectPlugin linkedPlugin() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "activeRsn", "TestPlayer");
		inject(plugin, "activeHash", "42");
		inject(plugin, "sessionActive", true);
		return plugin;
	}

	private static Map<String, Object> snapshotWithNetWorth(long net)
	{
		Map<String, Object> wealth = new LinkedHashMap<>();
		wealth.put("net_worth_gp", net);
		Map<String, Object> snap = new LinkedHashMap<>();
		snap.put("wealth", wealth);
		return snap;
	}

	@Test
	public void logoutReasonManualWhenNotIdle() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		inject(plugin, "lastKeyboardIdleTicks", 3);
		inject(plugin, "lastMouseIdleTicks", 1);	// just clicked -> manual
		plugin.trackLogout();
		assertEquals("manual", plugin.pendingEvents.get(0).get("reason"));
	}

	@Test
	public void logoutReasonIdleWhenIdleTicksHigh() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		inject(plugin, "lastKeyboardIdleTicks", 900);
		inject(plugin, "lastMouseIdleTicks", 900);	// no input for minutes -> idle
		plugin.trackLogout();
		assertEquals("idle", plugin.pendingEvents.get(0).get("reason"));
	}

	@Test
	public void logoutReasonSixHourCapWhenSessionNearSixHours() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - (6L * 60L * 60L * 1000L));
		inject(plugin, "lastKeyboardIdleTicks", 0);
		inject(plugin, "lastMouseIdleTicks", 0);
		plugin.trackLogout();
		assertEquals("six_hour_cap", plugin.pendingEvents.get(0).get("reason"));
	}

	@Test
	public void connectionLostEmitsLogoutWithReason() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		GameStateChanged ev = new GameStateChanged();
		ev.setGameState(GameState.CONNECTION_LOST);
		plugin.onGameStateChanged(ev);

		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("logout", e.get("type"));
		assertEquals("connection_lost", e.get("reason"));
		assertFalse("connection loss ends the session", getBool(plugin, "sessionActive"));
	}

	@Test
	public void logoutCarriesWealthFromLastSnapshot() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		inject(plugin, "lastBuiltSnapshot", snapshotWithNetWorth(1_234_567L));
		plugin.trackLogout();
		assertEquals(1_234_567L, plugin.pendingEvents.get(0).get("wealth"));
	}

	@Test
	public void loginCarriesWealthFromLastSnapshot() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getName()).thenReturn("TestPlayer");
		when(client.getAccountHash()).thenReturn(42L);
		inject(plugin, "client", client);
		inject(plugin, "lastBuiltSnapshot", snapshotWithNetWorth(555L));

		boolean newLogin = plugin.trackSessionStart();
		assertTrue(newLogin);
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("login", e.get("type"));
		assertEquals(555L, e.get("wealth"));
	}

	@Test
	public void netWorthFallsBackToInventoryPlusEquipmentWhenBankNull() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		Map<String, Object> wealth = new LinkedHashMap<>();
		wealth.put("net_worth_gp", null);	// bank not opened yet
		wealth.put("inventory_gp", 300L);
		wealth.put("equipment_gp", 200L);
		Map<String, Object> snap = new LinkedHashMap<>();
		snap.put("wealth", wealth);
		inject(plugin, "lastBuiltSnapshot", snap);
		assertEquals(Long.valueOf(500L), plugin.lastKnownNetWorth());
	}

	@Test
	public void levelUpCarriesXp() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		when(client.getSkillExperience(Skill.ATTACK)).thenReturn(13_363);
		inject(plugin, "client", client);

		// StatChanged is a final class -> construct directly (Skill, xp, level, boostedLevel).
		plugin.onStatChanged(new StatChanged(Skill.ATTACK, 12_000, 24, 24));	// primes previous level, no emit
		plugin.onStatChanged(new StatChanged(Skill.ATTACK, 13_363, 25, 25));	// real level increase -> emit

		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("level_up", e.get("type"));
		assertEquals(25, e.get("level"));
		assertEquals(13_363, e.get("xp"));
	}

	@Test
	public void deathDefersThenCarriesLocationAndKind() throws Exception
	{
		// Deferred model: ActorDeath arms a pending (reads pre-death inv+equip live) and emits NOTHING; the
		// death event with location + death_kind is emitted once the containers settle (syncTask) or on logout.
		// This mock is a SAFE death (no wilderness varbit / pvp world), so it carries NO items_lost — a safe death
		// is a gp-sink reclaim, not an inter-account transfer, and its diff would be polluted by post-death eating.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		WorldPoint wp = new WorldPoint(3200, 3200, 0);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(wp);
		inject(plugin, "client", client);

		// ActorDeath is a final class -> construct directly with the (mockable) player as the dead actor.
		plugin.onActorDeath(new ActorDeath((Actor) player));
		assertTrue("death emit is deferred to the settle/logout resolve", plugin.pendingEvents.isEmpty());

		plugin.resolveDeathPending(new LinkedHashMap<>(), true); // settle-window path
		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("death", e.get("type"));
		assertEquals("safe", e.get("death_kind")); // no wilderness varbit / pvp world in the mock
		assertFalse("safe death carries no items_lost (not a transfer)", e.containsKey("items_lost"));
		@SuppressWarnings("unchecked")
		Map<String, Object> loc = (Map<String, Object>) e.get("location");
		assertEquals(wp.getRegionID(), loc.get("region_id"));
		assertEquals(0, loc.get("plane"));
	}

	private static boolean getBool(AccountConnectPlugin plugin, String fieldName) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		return f.getBoolean(plugin);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The W4 adversarial probes, re-aimed at the NARROW attribution rule.
 *
 * Every probe below found a real defect in the wide 54d5a0a candidate. The narrow rule answers each
 * of them the same way: `unknown`, and no fabricated pickup row. The expectations are rewritten to
 * that answer, so this class is the standing proof that the narrow rule closes the class rather than
 * a record of what the wide one did.
 *
 * F1 / F1b  a single Take plus a larger unrelated gain must never claim a customer collection.
 * F2 / F2b  a slow or interrupted walk must never publish our own recovery as somebody else's.
 * F3 / F3b  a stale Take must never claim a pile and must never fabricate a pickup row.
 * F5        a stale merged-stack record must never label a later customer collection.
 * F6        two piles on one tile must never get swapped labels.
 */
public class NarrowRuleProbeTest
{
	private static final int COINS = 995;
	private static final int POT = 1931;
	private static final int TILE_X = 3210;
	private static final int TILE_Y = 3420;

	/** F1: ONE Take, customer collects the 1,200 pile, an unrelated 1,500 gain lands 2 ticks later. */
	@Test
	public void f1_singleTakeLargerUnrelatedGainReportsUnknown() throws Exception
	{
		assertEquals("F1: a 1,500-coin sale is not a 1,200-coin pile (single click)",
			"unknown", singleTakeThenGain(1500));
	}

	/** F1b: an exact double of the pile with a single click. */
	@Test
	public void f1b_singleTakeExactDoubleGainReportsUnknown() throws Exception
	{
		assertEquals("F1b: 2,400 is not one 1,200-coin pile", "unknown", singleTakeThenGain(2400));
	}

	/** F1 control: a SMALLER unrelated gain is refused too. */
	@Test
	public void f1_control_smallerUnrelatedGainReportsUnknown() throws Exception
	{
		assertEquals("control: 700 is refused", "unknown", singleTakeThenGain(700));
	}

	/** And the EXACT pile size still attributes, so the rule is not simply refusing everything. */
	@Test
	public void f1_control_theExactPileSizeStillAttributes() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1200);
		dropItemAt(plugin, COINS, 1200, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));
		tick(plugin, 151);
		plugin.onItemDespawned(despawn(COINS, 1200, TILE_X, TILE_Y, 0));
		tick(plugin, 153);
		setInventory(plugin, COINS, 1200);		// exactly the pile
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 165);
		plugin.onGameTick(null);
		assertEquals("an exact-size recovery on a lone Take is still ours",
			"self_pickup", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	private static String singleTakeThenGain(int gain) throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1200);
		dropItemAt(plugin, COINS, 1200, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));
		tick(plugin, 151);
		plugin.onItemDespawned(despawn(COINS, 1200, TILE_X, TILE_Y, 0));	// CUSTOMER collects
		tick(plugin, 153);
		setInventory(plugin, COINS, gain);					// unrelated gain
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 165);
		plugin.onGameTick(null);
		return String.valueOf(onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/**
	 * F2: a lone Take served after a 6-tick walk loses its label and reports `unknown`.
	 *
	 * The pickup pending lives 5 ticks, so a longer walk expires it. The narrow rule does not try to
	 * revive a stale Take, because every attempt at that in the wide candidate (defects 22 and 23)
	 * produced its own regression. The pile is never mislabelled, only unlabelled.
	 */
	@Test
	public void f2_sixTickWalkReportsUnknown() throws Exception
	{
		assertEquals("walk 6", "unknown", walkAndRecover(6));
	}

	/** F2 control: a 5-tick walk is inside the window and still attributes. */
	@Test
	public void f2_control_fiveTickWalkIsSelfPickup() throws Exception
	{
		assertEquals("walk 5", "self_pickup", walkAndRecover(5));
	}

	private static String walkAndRecover(int walk) throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(plugin, 150 + walk);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 150 + walk + 10);
		plugin.onGameTick(null);
		return String.valueOf(onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F2b: an unrelated container change 6 ticks into the walk prunes the Take; our recovery then reads removed_early. */
	@Test
	public void f2b_containerChangeDuringWalkMustNotPublishOwnRecoveryAsRemovedEarly() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(plugin, 156);
		setInventory(plugin, COINS, 5);						// unrelated change, no pot
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 158);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));	// we pick it up
		setInventory(plugin, COINS, 5, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 170);
		plugin.onGameTick(null);

		// The unrelated container change at 156 prunes the Take, so at 158 no Take is armed and the
		// pile is not deferred. It is NOT mislabelled either: `takeArmed` was set when the Take was
		// clicked and never clears, so the pile reports `unknown` and names nobody.
		assertEquals("F2b: our own recovery is never `somebody else took it`",
			"unknown", onlyEvent(plugin, "ground_removed").get("cause"));
		assertEquals("F2b: no pickup row may be fabricated from an expired Take",
			0, eventsOfType(plugin, "pickup").size());
	}

	/** F3: a stale unserved Take on the SAME tile sits ahead of the fresh one and eats its evidence. */
	@Test
	public void f3_staleSameTileTakeReportsUnknown() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));	// never served
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));	// served
		tick(plugin, 203);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 215);
		plugin.onGameTick(null);

		// Two armed Takes of one item: the client cannot say which click the server ran, so nothing
		// is claimed. The stale one at the queue head no longer STEALS the evidence either - it is
		// discarded on sight for being past its own window - but two Takes is still two Takes.
		assertEquals("F3: two armed Takes cannot prove which one landed",
			"unknown", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F3 control: without the stale Take the same recovery is self_pickup. */
	@Test
	public void f3_control_freshTakeAloneIsSelfPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 1);
		dropItemAt(plugin, POT, 1, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTakeAt("Pot", POT, TILE_X, TILE_Y));
		tick(plugin, 203);
		plugin.onItemDespawned(despawn(POT, 1, TILE_X, TILE_Y, 0));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 215);
		plugin.onGameTick(null);

		assertEquals("control", "self_pickup", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F3b: stale Take at the head, then a stale-Take resolution fabricates a pickup row off an unrelated gain much later. */
	@Test
	public void f3b_staleTakeFabricatesNoPickupRowFromALaterUnrelatedGain() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1000);
		dropItemAt(plugin, COINS, 1000, 100, 400, TILE_X, TILE_Y);
		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));	// never served
		tick(plugin, 405);
		plugin.onItemDespawned(despawn(COINS, 1000, TILE_X, TILE_Y, 0));	// timer expiry
		tick(plugin, 420);
		plugin.onGameTick(null);
		tick(plugin, 900);
		setInventory(plugin, COINS, 250);					// unrelated store sale, 750 ticks later
		plugin.onItemContainerChanged(invChanged(plugin));

		assertEquals("F3b: no pickup happened, so no pickup row may exist",
			0, eventsOfType(plugin, "pickup").size());
		assertEquals("F3b: a Take of ours named this pile, so its timer expiry is not assertable",
			"unknown", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** F5: merged-stack double record. After a clean self_pickup the stale second record survives and labels a later customer collection on the same tile. */
	@Test
	public void f5_staleMergedRecordNeverLabelsALaterCustomerCollection() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 1200);
		standAt(plugin, TILE_X, TILE_Y);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		setInventory(plugin, COINS, 200);
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(
			tile(TILE_X, TILE_Y, 0), tileItem(COINS, 1000, 400)));
		tick(plugin, 101);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		setInventory(plugin);
		plugin.onItemQuantityChanged(new net.runelite.api.events.ItemQuantityChanged(
			tileItem(COINS, 1200, 401), tile(TILE_X, TILE_Y, 0), 1000, 1200));
		assertEquals("one real stack is tracked twice", 2, plugin.groundDropCount());

		tick(plugin, 150);
		plugin.onMenuOptionClicked(groundTakeAt("Coins", COINS, TILE_X, TILE_Y));
		tick(plugin, 152);
		plugin.onItemDespawned(despawn(COINS, 1200, TILE_X, TILE_Y, 0));	// we recover it
		setInventory(plugin, COINS, 1200);
		plugin.onItemContainerChanged(invChanged(plugin));
		tick(plugin, 160);
		plugin.onGameTick(null);
		// Two tracked records describe one real 1,200-coin stack, so the Take has two candidates and
		// claims neither. `unknown`, never a fabricated attribution.
		assertEquals("first removal is unattributable", "unknown",
			onlyEvent(plugin, "ground_removed").get("cause"));

		// Next delivery on the same tile 400 ticks later: drop 800, the customer collects at once.
		tick(plugin, 550);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		setInventory(plugin, COINS, 400);
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(
			tile(TILE_X, TILE_Y, 0), tileItem(COINS, 800, 850)));
		tick(plugin, 560);
		plugin.onItemDespawned(despawn(COINS, 800, TILE_X, TILE_Y, 0));	// CUSTOMER collects
		tick(plugin, 570);
		plugin.onGameTick(null);

		List<Map<String, Object>> all = eventsOfType(plugin, "ground_removed");
		Map<String, Object> second = all.get(all.size() - 1);
		assertNotEquals("F5: a customer collection 10 ticks after the drop is not a timer expiry",
			"despawn_timer", second.get("cause"));
		assertEquals("F5: nor is it ours", "unknown", second.get("cause"));
	}

	/** F6: two own unstackable piles on ONE tile. Customer takes first, we take second. */
	@Test
	public void f6_sameTileCustomerFirstThenOurs_bothUnknown() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(POT, 2);
