	// ---- helpers (copied from GroundRemovalTest; they are private there) ----

	/** A widget op labelled Take that carries an item id but no ground tile. */
	private static MenuOptionClicked widgetTake(String name, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getMenuTarget()).thenReturn("<col=ff9040>" + name);
		when(m.getItemId()).thenReturn(itemId);
		when(m.getId()).thenReturn(3);
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.CC_OP);
		return m;
	}

	private static void standAt(AccountConnectPlugin plugin, int x, int y) throws Exception
	{
		when(client(plugin).getLocalPlayer().getWorldLocation()).thenReturn(new WorldPoint(x, y, 0));
	}

	private static void dropItemAt(AccountConnectPlugin plugin, int item, int qty, int atTick,
		int despawnTick, int x, int y, int... remaining) throws Exception
	{
		standAt(plugin, x, y);
		tick(plugin, atTick);
		plugin.onMenuOptionClicked(menu("Drop", "", item));
		setInventory(plugin, remaining);
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(
			tile(x, y, 0), tileItem(item, qty, despawnTick)));
	}

	private static net.runelite.api.events.ItemDespawned despawn(int item, int qty, int x, int y, int plane)
	{
		return new net.runelite.api.events.ItemDespawned(tile(x, y, plane), tileItem(item, qty, 0));
	}

	private static net.runelite.api.Tile tile(int x, int y, int plane)
	{
		net.runelite.api.Tile t = mock(net.runelite.api.Tile.class);
		when(t.getWorldLocation()).thenReturn(new WorldPoint(x, y, plane));
		return t;
	}

	private static net.runelite.api.TileItem tileItem(int id, int qty, int despawnTick)
	{
		net.runelite.api.TileItem it = mock(net.runelite.api.TileItem.class);
		when(it.getId()).thenReturn(id);
		when(it.getQuantity()).thenReturn(qty);
		when(it.getDespawnTime()).thenReturn(despawnTick);
		when(it.getOwnership()).thenReturn(net.runelite.api.TileItem.OWNERSHIP_SELF);
		return it;
	}

	private static AccountConnectPlugin newPlugin(int... idQtyPairs) throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv0 = container(idQtyPairs);
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv0);
		when(client.getVarbitValue(Varbits.IN_WILDERNESS)).thenReturn(0);
		when(client.getTickCount()).thenReturn(100);
		net.runelite.api.WorldView wv = mock(net.runelite.api.WorldView.class);
		when(wv.getBaseX()).thenReturn(0);
		when(wv.getBaseY()).thenReturn(0);
		when(client.getTopLevelWorldView()).thenReturn(wv);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(TILE_X, TILE_Y, 0));
		inject(plugin, "client", client);
		return plugin;
	}

	private static void setInventory(AccountConnectPlugin plugin, int... idQtyPairs) throws Exception
	{
		ItemContainer next = container(idQtyPairs);
		when(client(plugin).getItemContainer(InventoryID.INVENTORY)).thenReturn(next);
	}

	private static net.runelite.api.events.ItemContainerChanged invChanged(AccountConnectPlugin plugin)
		throws Exception
	{
		ItemContainer inv = client(plugin).getItemContainer(InventoryID.INVENTORY);
		return new net.runelite.api.events.ItemContainerChanged(InventoryID.INVENTORY.getId(), inv);
	}

	private static Client client(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		return (Client) f.get(plugin);
	}

	private static void tick(AccountConnectPlugin plugin, int t) throws Exception
	{
		when(client(plugin).getTickCount()).thenReturn(t);
	}

	private static List<Map<String, Object>> eventsOfType(AccountConnectPlugin plugin, String type)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if (type.equals(e.get("type")))
			{
				out.add(e);
			}
		}
		return out;
	}

	private static Map<String, Object> onlyEvent(AccountConnectPlugin plugin, String type)
	{
		List<Map<String, Object>> all = eventsOfType(plugin, type);
		assertEquals("expected exactly one " + type + " event, got " + all, 1, all.size());
		return all.get(0);
	}

	private static MenuOptionClicked groundTakeAt(String name, int itemId, int x, int y)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getMenuTarget()).thenReturn("<col=ff9040>" + name);
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(itemId);
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION);
		when(m.getParam0()).thenReturn(x);
		when(m.getParam1()).thenReturn(y);
		return m;
	}

	private static MenuOptionClicked menu(String option, String target, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn(option);
		when(m.getMenuTarget()).thenReturn(target);
		when(m.getItemId()).thenReturn(itemId);
		return m;
	}

	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static AccountConnectConfig onConfig()
	{
		return (AccountConnectConfig) java.lang.reflect.Proxy.newProxyInstance(
			AccountConnectConfig.class.getClassLoader(),
			new Class<?>[]{AccountConnectConfig.class},
			(proxy, method, args) -> {
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class || rt == Boolean.class) { return Boolean.TRUE; }
				if (rt == String.class) { return "0123456789abcdef0123456789abcdef"; }
				if (rt == int.class || rt == Integer.class) { return 0; }
				return null;
			});
	}
}

package com.osrsbestinslot.export;

import com.sun.net.httpserver.HttpServer;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.ui.DrawManager;
import okhttp3.OkHttpClient;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the trade-screenshot path — no live client needed. Covered here: PNG encoding
 * (valid magic bytes from a synthetic frame), the toggle-off early-return (no capture, no state),
 * and the state machine's arm / commit / discard transitions including a real multipart POST to a
 * local JDK HttpServer stub. NOT coverable without a live client (manual test plan in the report):
 * real WidgetLoaded/ChatMessage event delivery order on a live trade, actual game-frame contents,
 * Guice injection wiring, and the production ingest endpoint.
 */
public class TradeScreenshotTest
{
	private static final byte[] PNG_MAGIC = {(byte) 0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A};
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";

	// ---- PNG encode path ----

	@Test
	public void encodePngProducesValidNonEmptyPng()
	{
		byte[] bytes = AccountConnectPlugin.encodePng(syntheticFrame(320, 240));
		assertNotNull("encode returned null", bytes);
		assertTrue("PNG is empty", bytes.length > 0);
		for (int i = 0; i < PNG_MAGIC.length; i++)
		{
			assertEquals("PNG magic byte " + i + " wrong", PNG_MAGIC[i], bytes[i]);
		}
	}

	@Test
	public void toBufferedImagePassesThroughAndEncodesEndToEnd()
	{
		BufferedImage converted = AccountConnectPlugin.toBufferedImage(syntheticFrame(64, 48));
		byte[] bytes = AccountConnectPlugin.encodePng(converted);
		assertNotNull(bytes);
		assertTrue(startsWith(bytes, PNG_MAGIC));
	}

	// ---- NOT LINKED: handlers return early, nothing captured ----

	@Test
	public void unlinkedPerformsNoCaptureAndHoldsNoState() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		// Defaults only: linkToken() == "" so screenshotsEnabled() is false (the separate opt-in toggle
		// was removed 2026-09-02 — the token is the gate). drawManager / executor / okHttpClient are
		// left null on purpose — if any handler got past the gate and tried to capture or upload, it
		// would NPE and fail this test.
		inject(plugin, "config", new AccountConnectConfig() {
});

		plugin.handleTradeContainerChanged(90);
		assertFalse("toggle off must not arm tradeActive", plugin.tradeActive);

		plugin.handleTradeWidgetLoaded(334);
		assertNull("toggle off must not buffer a frame", plugin.pendingTradeFrame.get());

		plugin.handleTradeChat("Accepted trade.");
		assertFalse(plugin.tradeActive);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void togglingOffMidTradeDropsTheBufferedFrame() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
});
		// Simulate a frame buffered while the toggle was on, then the toggle switched off:
		plugin.tradeActive = true;
		plugin.pendingTradeFrame.set(syntheticFrame(8, 8));

		plugin.handleTradeChat("Accepted trade.");	// guard runs first — must clear, never upload
		assertFalse(plugin.tradeActive);
		assertNull("disabled guard must drop the stale frame", plugin.pendingTradeFrame.get());
	}

	// ---- toggle ON: arm -> frame -> commit uploads one multipart PNG ----

	@Test
	public void armCommitUploadsBothConfirmAndCompletedScreenshots() throws Exception
	{
		// Delivery proof = TWO shots per completed trade: the confirm window (items + partner) and the
		// post-accept frame (the "Accepted trade." chat line, window closed). Both must reach the ingest
		// route, each tagged with its phase.
		java.util.concurrent.BlockingQueue<Capture> received = new java.util.concurrent.LinkedBlockingQueue<>();
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", exchange ->
		{
			byte[] reqBody = readAll(exchange.getRequestBody());
			byte[] resp = "{\"ok\":true,\"id\":1}".getBytes(StandardCharsets.UTF_8);
			exchange.sendResponseHeaders(200, resp.length);
			exchange.getResponseBody().write(resp);
			exchange.close();
			received.add(new Capture(exchange.getRequestURI().getPath(),
				exchange.getRequestHeaders().getFirst("Content-Type"), reqBody));
		});
		server.start();
		try
		{
			String base = "http://127.0.0.1:" + server.getAddress().getPort() + "/wp-json/osrsbis/v1";
			AccountConnectPlugin plugin = new AccountConnectPlugin();
			inject(plugin, "config", enabledConfig(base));
			DrawManager drawManager = new DrawManager();
			inject(plugin, "drawManager", drawManager);
			inject(plugin, "executor", Executors.newSingleThreadScheduledExecutor());
			inject(plugin, "okHttpClient", new OkHttpClient());

			plugin.handleTradeContainerChanged(90);	// trade genuinely in progress
			assertTrue(plugin.tradeActive);

			plugin.handleTradeWidgetLoaded(334);	// confirm screen -> one-shot frame request
			drawManager.processDrawComplete(() -> syntheticFrame(320, 240));	// deliver the confirm frame
			assertNotNull("frame must be buffered after 334-load + draw", plugin.pendingTradeFrame.get());

			plugin.handleTradeChat("Accepted trade.");	// commit: uploads confirm + arms the completed grab
			assertFalse(plugin.tradeActive);
			assertNull("commit must consume the buffered frame", plugin.pendingTradeFrame.get());
			drawManager.processDrawComplete(() -> syntheticFrame(320, 240));	// deliver the completed frame

			Capture a = received.poll(15, TimeUnit.SECONDS);
			Capture b = received.poll(15, TimeUnit.SECONDS);
			assertNotNull("first screenshot upload missing", a);
			assertNotNull("second (completed) screenshot upload missing", b);
			String phases = "";
			for (Capture c : new Capture[] {a, b})
			{
				assertEquals("/wp-json/osrsbis/v1/screenshot-ingest", c.path);
				assertTrue("not multipart: " + c.contentType, c.contentType.startsWith("multipart/form-data"));
				String body = new String(c.body, StandardCharsets.ISO_8859_1);
				assertTrue("token field missing", body.contains("name=\"token\"") && body.contains(TEST_TOKEN));
				assertTrue("kind field missing", body.contains("name=\"kind\"") && body.contains("trade"));
				assertTrue("phase field missing", body.contains("name=\"phase\""));
				assertTrue("captured_at field missing", body.contains("name=\"captured_at\""));
				assertTrue("file part missing", body.contains("name=\"file\""));
				assertTrue("file part not image/png", body.contains("image/png"));
				assertTrue("body carries no PNG payload", indexOf(c.body, PNG_MAGIC) >= 0);
				phases += body;
			}
			assertTrue("confirm-phase screenshot not uploaded", phases.contains("confirm"));
			assertTrue("completed-phase screenshot not uploaded", phases.contains("completed"));
		}
		finally
		{
			server.stop(0);
		}
	}

	// ---- discard paths: decline / window closed / disconnect — never upload ----

	@Test
	public void declineDiscardsFrameWithoutUpload() throws Exception
	{
		AccountConnectPlugin plugin = armedPluginWithoutNetwork();
		plugin.handleTradeChat("Other player declined trade.");
		assertFalse(plugin.tradeActive);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void widgetClosedDiscardsFrameWithoutUpload() throws Exception
	{
		AccountConnectPlugin plugin = armedPluginWithoutNetwork();
		plugin.handleTradeWidgetClosed(334);
		assertFalse(plugin.tradeActive);
		assertFalse(plugin.tradeArmed);
		assertNull(plugin.pendingTradeFrame.get());

		plugin = armedPluginWithoutNetwork();
		plugin.handleTradeWidgetClosed(335);	// first trade screen closing while ARMED also discards
		assertFalse(plugin.tradeActive);
		assertFalse(plugin.tradeArmed);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void firstScreenCloseBeforeConfirmDoesNotKillTheTrade() throws Exception
	{
		// Normal 335 -> 334 transition: the first trade screen closes while we are tradeActive but
		// not yet ARMED. That close must NOT reset state, or the confirm screen could never arm.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", enabledConfig(null));
		plugin.tradeActive = true;

		plugin.handleTradeWidgetClosed(335);
		assertTrue("335 closing pre-ARMED must not clear tradeActive", plugin.tradeActive);
	}

	@Test
	public void disconnectClearsPendingFrameWithoutUpload() throws Exception
	{
		AccountConnectPlugin plugin = armedPluginWithoutNetwork();
		GameStateChanged event = new GameStateChanged();
		event.setGameState(GameState.CONNECTION_LOST);
		plugin.onGameStateChanged(event);
		assertFalse(plugin.tradeActive);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void malformedTokenNeverUploads() throws Exception
	{
		// A token that is present but MALFORMED must be treated as unlinked: the commit path stops at
		// the token guard, before touching the (null) executor/okHttpClient — an upload attempt would
		// NPE and fail the test. This is the arm that matters now that the token is the only gate: a
		// gate keyed on "is the string non-empty" rather than on the ^[a-f0-9]{32}$ shape would pass
		// every other test in this file and fail here.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "not-a-valid-token";	// fails ^[a-f0-9]{32}$
			}
		});
		plugin.tradeActive = true;
		plugin.pendingTradeFrame.set(syntheticFrame(8, 8));

		plugin.handleTradeChat("Accepted trade.");
		assertNull(plugin.pendingTradeFrame.get());
		assertFalse(plugin.tradeActive);
	}

	// ---- helpers ----

	/** LINKED, ARMED (frame buffered), but no executor/okHttpClient: any upload attempt would NPE. */
	private static AccountConnectPlugin armedPluginWithoutNetwork() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", enabledConfig(null));
		plugin.tradeActive = true;
		plugin.tradeArmed = true;
		plugin.pendingTradeFrame.set(syntheticFrame(8, 8));
		return plugin;
	}

	private static AccountConnectConfig enabledConfig(String baseUrl)
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;	// the token IS the gate now (the opt-in toggle was removed 2026-09-02)
			}

			@Override
			public String apiBaseUrl()
			{
				return baseUrl != null ? baseUrl : AccountConnectConfig.super.apiBaseUrl();
			}
		};
	}

	private static BufferedImage syntheticFrame(int w, int h)
	{
		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(Color.RED);
		g.fillRect(0, 0, w, h);
		g.setColor(Color.GREEN);
		g.fillRect(0, 0, w / 2, h / 2);
		g.dispose();
		return img;
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static byte[] readAll(InputStream in) throws java.io.IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] chunk = new byte[8192];
		int n;
		while ((n = in.read(chunk)) != -1)
		{
			out.write(chunk, 0, n);
		}
		return out.toByteArray();
	}

	private static boolean startsWith(byte[] data, byte[] prefix)
	{
		if (data.length < prefix.length)
		{
			return false;
		}
		for (int i = 0; i < prefix.length; i++)
		{
			if (data[i] != prefix[i])
			{
				return false;
			}
		}
		return true;
	}

	private static int indexOf(byte[] haystack, byte[] needle)
	{
		outer:
		for (int i = 0; i <= haystack.length - needle.length; i++)
		{
			for (int j = 0; j < needle.length; j++)
			{
				if (haystack[i + j] != needle[j])
				{
					continue outer;
				}
			}
			return i;
		}
		return -1;
	}

	private static final class Capture
	{
		final String path;
		final String contentType;
		final byte[] body;

		Capture(String path, String contentType, byte[] body)
		{
			this.path = path;
			this.contentType = contentType;
			this.body = body;
		}
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * GROUND-ITEM LIFECYCLE. A dropped item leaving the ground is observable; WHY it left mostly is not.
 *
 * These tests pin the honest boundary. "removed_early" means the pile went before its own despawn
 * deadline while we were watching normally — it never names a taker and never means delivered.
 * Anything we cannot separate stays "unknown" rather than being resolved by a guess.
 */
public class GroundRemovalTest
{
	private static final int CHAPS = 2495;
	private static final int DIAMOND = 1617;
	private static final int COINS = 995;
	private static final int POT = 1931;
	private static final int TILE_X = 3210;
	private static final int TILE_Y = 3420;

	/** The chaps case: dropped, left alone, removed before the timer. Ambiguous by nature. */
	@Test
	public void droppedItemRemovedBeforeItsDeadlineIsEarlyAndNamesNobody() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		dropItem(plugin, CHAPS, 1, 100, 300);
		assertEquals("the pile must be tracked", 1, plugin.groundDropCount());

		tick(plugin, 140);
		plugin.onItemDespawned(despawn(CHAPS, 1, TILE_X, TILE_Y, 0));

		Map<String, Object> ev = onlyEvent(plugin, "ground_removed");
		assertEquals("removed_early", ev.get("cause"));
		assertEquals("UNKNOWN", ev.get("recipient"));
		assertEquals(CHAPS, ev.get("item"));
		assertEquals(40, ev.get("ticks_on_ground"));
		assertTrue("a removal must never claim a recipient",
			!String.valueOf(ev).toLowerCase().contains("customer"));
		assertEquals("the pile is no longer tracked", 0, plugin.groundDropCount());
	}

	/** Left to time out: removal at/after the client's own deadline is the timer, not a taker. */
	/**
	 * Who was standing on the pile when it left the ground. The taker is still never NAMED here:
	 * `recipient` stays UNKNOWN and the players go out as `taken_by_candidates`, the same inference
	 * field the store handoff emits, for the server-side resolver to judge (one candidate at dist 0).
	 */
	@Test
	public void earlyRemovalRecordsWhoStoodOnThePile() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(COINS, 25_000_000);
		dropItem(plugin, COINS, 25_000_000, 100, 300);
		Player onPile = mockPlayer("Buyer", TILE_X, TILE_Y, 92);
		Player bystander = mockPlayer("Passer", TILE_X + 2, TILE_Y, 3);
		List<Player> players = new ArrayList<>();
		players.add(onPile);
		players.add(bystander);
		when(client(plugin).getPlayers()).thenReturn(players);

		tick(plugin, 103);
		plugin.onItemDespawned(despawn(COINS, 25_000_000, TILE_X, TILE_Y, 0));

		Map<String, Object> ev = onlyEvent(plugin, "ground_removed");
		assertEquals("removed_early", ev.get("cause"));
		assertEquals("the plugin still never names the taker", "UNKNOWN", ev.get("recipient"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> cands = (List<Map<String, Object>>) ev.get("taken_by_candidates");
		assertEquals(2, cands.size());
		assertEquals("nearest first", "Buyer", cands.get(0).get("rsn"));
		assertEquals(0, cands.get(0).get("dist"));
		assertEquals(92, cands.get(0).get("cb"));
		assertEquals(2, cands.get(1).get("dist"));
	}

	/** Nobody around: the key is ABSENT, exactly as the store path does it, so readers keep one rule. */
	@Test
	public void earlyRemovalWithNobodyAroundCarriesNoCandidates() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		dropItem(plugin, CHAPS, 1, 100, 300);
		tick(plugin, 140);
		plugin.onItemDespawned(despawn(CHAPS, 1, TILE_X, TILE_Y, 0));
		Map<String, Object> ev = onlyEvent(plugin, "ground_removed");
		assertEquals("removed_early", ev.get("cause"));
		assertNull(ev.get("taken_by_candidates"));
	}

	/** A pile that ran its own timer names nobody: presence at a despawn is not a pickup. */
	@Test
	public void timerRemovalNeverCarriesCandidates() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		dropItem(plugin, CHAPS, 1, 100, 300);
		List<Player> players = new ArrayList<>();
		players.add(mockPlayer("Idler", TILE_X, TILE_Y, 50));
		when(client(plugin).getPlayers()).thenReturn(players);
		tick(plugin, 300);
		plugin.onItemDespawned(despawn(CHAPS, 1, TILE_X, TILE_Y, 0));
		Map<String, Object> ev = onlyEvent(plugin, "ground_removed");
		assertEquals("despawn_timer", ev.get("cause"));
		assertNull(ev.get("taken_by_candidates"));
	}

	private static Player mockPlayer(String name, int x, int y, int cb)
	{
		Player p = mock(Player.class);
		when(p.getName()).thenReturn(name);
		when(p.getWorldLocation()).thenReturn(new WorldPoint(x, y, 0));
		when(p.getCombatLevel()).thenReturn(cb);
		return p;
	}

	@Test
	public void removalAtTheDespawnDeadlineIsTheTimer() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		dropItem(plugin, CHAPS, 1, 100, 300);
		tick(plugin, 300);
		plugin.onItemDespawned(despawn(CHAPS, 1, TILE_X, TILE_Y, 0));
		assertEquals("despawn_timer", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** We took it back ourselves. That is certain, so it must not read as an ambiguous removal. */
	@Test
	public void selfPickupExplainsItsOwnRemoval() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(DIAMOND, 1);
		dropItem(plugin, DIAMOND, 1, 100, 300);

		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(invChanged(plugin));
		assertEquals("the self-pickup must emit", 1, eventsOfType(plugin, "pickup").size());

		plugin.onItemDespawned(despawn(DIAMOND, 1, TILE_X, TILE_Y, 0));
		assertEquals("self_pickup", onlyEvent(plugin, "ground_removed").get("cause"));
	}

	/** A scene reload despawns every pile for unrelated reasons. It must not read as early removal. */
	@Test
	public void sceneReloadNeverReportsEarlyRemoval() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		dropItem(plugin, CHAPS, 1, 100, 300);

		plugin.onGameStateChanged(gameState(GameState.LOADING));
		tick(plugin, 140);
		plugin.onItemDespawned(despawn(CHAPS, 1, TILE_X, TILE_Y, 0));

		assertNull("a scene-reload despawn must emit nothing about our pile",
			firstEvent(plugin, "ground_removed"));
		assertEquals(0, plugin.groundDropCount());
	}

	/** Another player's pile despawning on our tile is not ours and must emit nothing. */
	@Test
	public void aForeignPileDespawningEmitsNothing() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		dropItem(plugin, CHAPS, 1, 100, 300);
		tick(plugin, 140);
		plugin.onItemDespawned(despawn(DIAMOND, 1, TILE_X, TILE_Y, 0));	// different item
		assertNull(firstEvent(plugin, "ground_removed"));
		plugin.onItemDespawned(despawn(CHAPS, 1, TILE_X + 6, TILE_Y, 0));	// different tile
		assertNull(firstEvent(plugin, "ground_removed"));
		assertEquals("our pile is still tracked", 1, plugin.groundDropCount());
	}

	/** No reported deadline means we cannot tell early from timer. Preserve the ambiguity. */
	@Test
	public void noDespawnDeadlineStaysUnknown() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
