package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Store-transfer counterparty capture — nearby[] (players seen over a shop visit), world, loc attached to
 * store events. Unmasks the untracked receiver of the general-store method: a seller lists an item cheap into
 * the shared store, an untracked player standing there buys it out (no trade event). The receiver is in the
 * nearby set — presence + persistence + proximity finger them. Logic proven against mocked players; real
 * WorldView timing is field-verified on a live shop visit.
 */
public class StoreNearbyCaptureTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	private static Player player(String name, int x, int y, int cb)
	{
		Player p = mock(Player.class);
		when(p.getName()).thenReturn(name);
		when(p.getWorldLocation()).thenReturn(new WorldPoint(x, y, 0));
		when(p.getCombatLevel()).thenReturn(cb);
		return p;
	}

	/** plugin wired to a client at self-loc, given nearby players list + world + tick. */
	private static AccountConnectPlugin plugin(Player self, List<Player> players, int world, int tick) throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		when(client.getLocalPlayer()).thenReturn(self);
		when(client.getPlayers()).thenReturn(players);
		when(client.getWorld()).thenReturn(world);
		when(client.getTickCount()).thenReturn(tick);
		inject(plugin, "client", client);
		return plugin;
	}

	@Test
	public void accumulateTracksClosestApproachAndPersistence() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player b = mock(Player.class);
		when(b.getName()).thenReturn("Receiver");
		when(b.getCombatLevel()).thenReturn(126);
		Client client = mock(Client.class);
		when(client.getLocalPlayer()).thenReturn(self);
		List<Player> players = new ArrayList<>();
		players.add(self);
		players.add(b);
		when(client.getPlayers()).thenReturn(players);

		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "client", client);

		// tick 10: Receiver 3 tiles east
		when(b.getWorldLocation()).thenReturn(new WorldPoint(3167, 3486, 0));
		when(client.getTickCount()).thenReturn(10);
		plugin.accumulateShopNearby();
		// tick 13: Receiver steps adjacent (1 tile)
		when(b.getWorldLocation()).thenReturn(new WorldPoint(3165, 3486, 0));
		when(client.getTickCount()).thenReturn(13);
		plugin.accumulateShopNearby();

		@SuppressWarnings("unchecked")
		Map<String, int[]> seen = (Map<String, int[]>) field(plugin, "shopVisitNearby");
		int[] rec = seen.get("Receiver");
		assertEquals("closest approach kept", 1, rec[0]);
		assertEquals("first tick", 10, rec[1]);
		assertEquals("last tick", 13, rec[2]);
		assertEquals("combat level", 126, rec[3]);
	}

	@Test
	public void storeContextAttachesNearbyWorldLocNearestFirst() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player near = player("Adjacent", 3165, 3486, 100);	// dist 1
		Player far = player("Bystander", 3170, 3486, 50);	// dist 6
		List<Player> players = new ArrayList<>();
		players.add(self);
		players.add(far);
		players.add(near);
		AccountConnectPlugin plugin = plugin(self, players, 302, 20);

		plugin.accumulateShopNearby();		// build the visit set
		Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);

		assertEquals(302, fields.get("world"));
		assertEquals(java.util.Arrays.asList(3164, 3486, 0), fields.get("loc"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> nearby = (List<Map<String, Object>>) fields.get("nearby");
		assertEquals(2, nearby.size());
		assertEquals("nearest first", "Adjacent", nearby.get(0).get("rsn"));
		assertEquals(1, nearby.get(0).get("dist"));
		assertEquals("Bystander", nearby.get(1).get("rsn"));
		assertEquals(6, nearby.get(1).get("dist"));
	}

	@Test
	public void selfAndNamelessExcluded() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player nameless = mock(Player.class);
		when(nameless.getName()).thenReturn(null);
		when(nameless.getWorldLocation()).thenReturn(new WorldPoint(3165, 3486, 0));
		List<Player> players = new ArrayList<>();
		players.add(self);		// self must be excluded
		players.add(nameless);	// unnamed (rendering) player excluded
		AccountConnectPlugin plugin = plugin(self, players, 302, 5);

		plugin.accumulateShopNearby();
		@SuppressWarnings("unchecked")
		Map<String, int[]> seen = (Map<String, int[]>) field(plugin, "shopVisitNearby");
		assertTrue("no self, no nameless", seen.isEmpty());
	}

	@Test
	public void liveSnapshotBackfillsWhenAccumulatorEmpty() throws Exception
	{
		// store event fires before any tick accumulated -> nearby[] falls back to a live snapshot.
		Player self = player("Seller", 3164, 3486, 90);
		Player near = player("Walker", 3166, 3486, 70);	// dist 2
		List<Player> players = new ArrayList<>();
		players.add(self);
		players.add(near);
		AccountConnectPlugin plugin = plugin(self, players, 308, 1);

		Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);	// no accumulate() first

		@SuppressWarnings("unchecked")
		List<Map<String, Object>> nearby = (List<Map<String, Object>>) fields.get("nearby");
		assertEquals(1, nearby.size());
		assertEquals("Walker", nearby.get(0).get("rsn"));
		assertEquals(2, nearby.get(0).get("dist"));
		assertEquals("live snapshot carries offsets", 2, nearby.get(0).get("dx"));
	}

	@Test
	public void noPlayersNoNearbyStillCarriesWorldLoc() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		List<Player> players = new ArrayList<>();
		players.add(self);
		AccountConnectPlugin plugin = plugin(self, players, 302, 5);

		Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);

		assertNull("no nearby field when nobody around", fields.get("nearby"));
		assertEquals(302, fields.get("world"));
		assertFalse("world/loc still present", fields.isEmpty());
	}

	// ---- nearby_at_tx: the TRANSACTION-MOMENT snapshot (was completely untested until 2026-09-03) ----

	/**
	 * nearby_at_tx is the whole point of the field: nearby[] is everyone seen across the WHOLE visit,
	 * which over a long visit accumulates passers-by. nearby_at_tx is who was standing there at the
	 * instant the item moved. On production the two differ on roughly 1 event in 10, and the narrower
	 * list is the one that names a receiver — so a bug that made them identical would destroy the
	 * feature's value while every existing assertion still passed.
	 */
	@Test
	public void nearbyAtTxIsTheTransactionMomentNotTheWholeVisit() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player receiver = player("Receiver", 3164, 3486, 126);
		Player passerby = player("PasserBy", 3170, 3490, 60);

		// Visit accumulator saw BOTH — receiver and a passer-by who has since walked off.
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, receiver), 311, 100);
		java.util.Map<String, int[]> visit = new java.util.LinkedHashMap<>();
		visit.put("Receiver", new int[]{0, 90, 100, 126});
		visit.put("PasserBy", new int[]{6, 90, 92, 60});
		inject(plugin, "shopVisitNearby", visit);

		// At the transaction moment only the receiver is present.
		inject(plugin, "nearbyAtTx", plugin.nearbyPlayersSnapshot(24));

		java.util.Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);

		@SuppressWarnings("unchecked")
		List<Map<String, Object>> visitWide = (List<Map<String, Object>>) fields.get("nearby");
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> atTx = (List<Map<String, Object>>) fields.get("nearby_at_tx");

		assertNotNull("nearby_at_tx must be attached when a snapshot was taken", atTx);
		assertEquals("the visit-wide list keeps everyone seen", 2, visitWide.size());
		assertEquals("the transaction-moment list holds only who was there then", 1, atTx.size());
		assertEquals("Receiver", atTx.get(0).get("rsn"));
	}

	/**
	 * The field must be CONSUMED, not left set. It is a per-transaction snapshot, so a stale value
	 * leaking into the next store event would attach the previous transaction's bystanders to it —
	 * the exact shape of a false accusation.
	 */
	@Test
	public void nearbyAtTxIsClearedAfterItIsAttached() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player other = player("Other", 3164, 3486, 100);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, other), 311, 100);
		inject(plugin, "nearbyAtTx", plugin.nearbyPlayersSnapshot(24));

		java.util.Map<String, Object> first = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(first);
		assertNotNull("first event carries the snapshot", first.get("nearby_at_tx"));

		java.util.Map<String, Object> second = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(second);
		assertNull("a second event must NOT inherit the previous transaction's snapshot",
			second.get("nearby_at_tx"));
	}

	// ---- store_taken: the shop-stock counterparty inference (was completely untested) ----

	/**
	 * store_taken fires when the stock of an item THIS VISIT SOLD falls — someone bought it out of the
	 * dead drop. Only sold items are watched, because our own BUY also lowers stock and must never be
	 * reported as a taker.
	 */
	@Test
	public void storeTakenFiresOnlyForItemsThisVisitSold() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player taker = player("Taker", 3164, 3486, 126);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, taker), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);						// we sold this
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);					// our item, stock 1
		baseline.put(29415, 43);				// an unrelated shop item
		inject(plugin, "shopStock", baseline);

		// Both fall: ours to 0 (a taker), the unrelated one to 42 (nothing to do with us).
		plugin.handleShopStockChanged(shopWith(new int[][]{{29415, 42}}));

		List<Map<String, Object>> events = plugin.pendingEvents;
		long taken = events.stream().filter(e -> "store_taken".equals(e.get("type"))).count();
		assertEquals("exactly one store_taken, for the SOLD item only", 1, taken);
		Map<String, Object> ev = events.stream()
			.filter(e -> "store_taken".equals(e.get("type"))).findFirst().orElseThrow(AssertionError::new);
		assertEquals(20997, ev.get("item"));
		assertEquals("stock fell by one", 1, ev.get("qty"));
	}

	/**
	 * A store_taken during a capturing visit marks a moment on the visit clip, so the clip keeps the
	 * seconds around the customer buying our item out. Without the call the moment is lost to the
	 * 1fps baseline.
	 */
	@Test
	public void storeTakenMarksAMomentOnTheVisitClip() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self), 412, 200);
		StoreVisitClip clip = new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES);
		inject(plugin, "clipVisit", clip);
		inject(plugin, "clipCapturing", true);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);
		inject(plugin, "shopStock", baseline);

		plugin.handleShopStockChanged(shopWith(new int[][]{}));

		assertEquals("store_taken must mark one moment on the visit clip", 1, clip.momentCount());
	}

	/**
	 * The candidate list is EVIDENCE, not an accusation, and the code is careful to call it
	 * taken_by_candidates. An empty shop must therefore emit the event with NO candidate list at all
	 * rather than an empty one — "we do not know who" must not read as "nobody".
	 */
	@Test
	public void storeTakenOmitsCandidatesWhenNobodyIsPresent() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self), 602, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(29415);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(29415, 43);
		inject(plugin, "shopStock", baseline);

		plugin.handleShopStockChanged(shopWith(new int[][]{{29415, 42}}));

		Map<String, Object> ev = plugin.pendingEvents.stream()
			.filter(e -> "store_taken".equals(e.get("type"))).findFirst().orElseThrow(AssertionError::new);
		assertNull("an empty shop must omit the candidate list, never emit an empty one",
			ev.get("taken_by_candidates"));
		assertEquals("the stock movement is still recorded", 29415, ev.get("item"));
	}

	/**
	 * OUR OWN BUY-BACK IS NOT A CUSTOMER (fixed 2026-09-03, found in field testing).
	 *
	 * The seller's own procedure has an explicit emergency step: if the customer cannot buy the item in time,
	 * the seller buys it back. That purchase lowers the shop stock exactly like a customer's, so the
	 * inference named a bystander as the taker. Measured on live events 3914798/3914799: a buy-back
	 * and a store_taken landed in the same second, and the plugin still named a candidate.
	 *
	 * A false counterparty is the worst output this feature can produce — it is evidence that could
	 * reach a dispute.
	 */
	@Test
	public void ourOwnBuybackIsNotReportedAsATaker() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player bystander = player("Bystander", 3164, 3486, 126);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, bystander), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);
		inject(plugin, "shopStock", baseline);

		// We just bought it back ourselves.
		inject(plugin, "lastSelfBuyItem", 20997);
		inject(plugin, "lastSelfBuyAtMs", System.currentTimeMillis());

		plugin.handleShopStockChanged(shopWith(new int[][]{}));

		assertTrue("a self buy-back must emit NO store_taken at all",
			plugin.pendingEvents.stream().noneMatch(e -> "store_taken".equals(e.get("type"))));
	}

	/** The suppression is time-boxed: an OLD self-buy must not mask a later genuine customer. */
	@Test
	public void anOldSelfBuyDoesNotMaskALaterCustomer() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player taker = player("Taker", 3164, 3486, 126);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, taker), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);
		inject(plugin, "shopStock", baseline);

		inject(plugin, "lastSelfBuyItem", 20997);
		inject(plugin, "lastSelfBuyAtMs", System.currentTimeMillis() - 60_000L);	// a minute ago

		plugin.handleShopStockChanged(shopWith(new int[][]{}));

		assertTrue("a stale self-buy must not suppress a real taker",
			plugin.pendingEvents.stream().anyMatch(e -> "store_taken".equals(e.get("type"))));
	}

	/** A stock RISE (the shop's own restock timer) is not someone taking our item. */
	@Test
	public void storeTakenIgnoresRestock() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);
		inject(plugin, "shopStock", baseline);

		plugin.handleShopStockChanged(shopWith(new int[][]{{20997, 5}}));	// stock ROSE

		assertTrue("a stock rise must emit nothing",
			plugin.pendingEvents.stream().noneMatch(e -> "store_taken".equals(e.get("type"))));
	}

	/**
	 * F-A1 (rig 2026-09-27): selling a Pot into Varrock GS (default stock 5) raised it to 6 and the shop
	 * normalised it back to 5 within seconds. That emitted store_taken 6->5 with a bystander as candidate:
	 * a false customer. The shop's own normalisation of default stock is not a buy-out.
	 */
	@Test
	public void defaultStockNormalisationIsNotACustomer() throws Exception
	{
		AccountConnectPlugin plugin = shopVisit(new int[][]{{1931, 5}});
		plugin.onMenuOptionClicked(sellClick(1931));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 6}}));	// our sale lands
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 5}}));	// the shop normalises
		assertEquals("no store_taken for default-stock normalisation", 0, storeTaken(plugin).size());
	}

	/** A real buy-out of a default-stock item (a fall of more than one) is still reported. */
	@Test
	public void aMultiItemBuyOutOfDefaultStockIsStillReported() throws Exception
	{
		AccountConnectPlugin plugin = shopVisit(new int[][]{{1931, 5}});
		plugin.onMenuOptionClicked(sellClick(1931));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 6}}));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 4}}));
		assertEquals(1, storeTaken(plugin).size());
		assertEquals(2, storeTaken(plugin).get(0).get("qty"));
	}

	/** Default stock bought out to ZERO is a buy-out, never normalisation. */
	@Test
	public void defaultStockTakenToZeroIsStillReported() throws Exception
	{
		AccountConnectPlugin plugin = shopVisit(new int[][]{{1931, 1}});
		plugin.onMenuOptionClicked(sellClick(1931));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 2}}));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 1}}));	// normalisation, suppressed
		plugin.handleShopStockChanged(shopWith(new int[][]{}));			// 1 -> 0: a buy-out
		assertEquals(1, storeTaken(plugin).size());
		assertEquals(0, storeTaken(plugin).get(0).get("stock_after"));
	}

	/** An item the shop does NOT stock (the delivery case) keeps its store_taken for a fall of one. */
	@Test
	public void aNonStockItemFallingByOneIsStillReported() throws Exception
	{
		AccountConnectPlugin plugin = shopVisit(new int[][]{{1931, 5}});
		plugin.onMenuOptionClicked(sellClick(20997));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 5}, {20997, 2}}));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 5}, {20997, 1}}));
		assertEquals(1, storeTaken(plugin).size());
		assertEquals(20997, storeTaken(plugin).get(0).get("item"));
	}

	/**
	 * Review H1: a multi-unit delivery of an item the shop does not stock. Our SECOND sell sees stock 1 (our
	 * own first unit); that must not make the item look like default stock and hide a customer's buy.
	 */
	@Test
	public void ourOwnEarlierSellNeverMakesADeliveryLookLikeDefaultStock() throws Exception
	{
		AccountConnectPlugin plugin = shopVisit(new int[][]{{1931, 5}});
		plugin.onMenuOptionClicked(sellClick(20997));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 5}, {20997, 1}}));
		plugin.onMenuOptionClicked(sellClick(20997));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 5}, {20997, 2}}));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 5}, {20997, 1}}));	// a customer buys one
		assertEquals(1, storeTaken(plugin).size());
		assertEquals(1, storeTaken(plugin).get(0).get("stock_after"));
	}

	/** Default stock bought to zero, then we sell more in: a fall of one of OUR units is reported. */
	@Test
	public void afterNativeStockIsGoneOurNewUnitsAreWatchedAgain() throws Exception
	{
		AccountConnectPlugin plugin = shopVisit(new int[][]{{1931, 1}});
		plugin.onMenuOptionClicked(sellClick(1931));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 2}}));
		plugin.handleShopStockChanged(shopWith(new int[][]{}));				// bought out to 0 (reported)
		plugin.onMenuOptionClicked(sellClick(1931));
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 2}}));	// we sell 2 in
		plugin.handleShopStockChanged(shopWith(new int[][]{{1931, 1}}));	// a customer takes one
		assertEquals(2, storeTaken(plugin).size());
	}

	/** An open shop whose first container read is the given stock, with a bystander present. */
	private AccountConnectPlugin shopVisit(int[][] stock) throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player bystander = player("Bystander", 3164, 3486, 126);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, bystander), 308, 200);
		inject(plugin, "shopOpen", true);
		plugin.handleShopStockChanged(shopWith(stock));		// baseline read at open
		return plugin;
	}

	private static List<Map<String, Object>> storeTaken(AccountConnectPlugin plugin)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if ("store_taken".equals(e.get("type")))
			{
				out.add(e);
			}
		}
		return out;
	}

	private static net.runelite.api.events.MenuOptionClicked sellClick(int itemId)
	{
		net.runelite.api.events.MenuOptionClicked e = mock(net.runelite.api.events.MenuOptionClicked.class);
		when(e.getMenuOption()).thenReturn("Sell 1");
		when(e.getItemId()).thenReturn(itemId);
		return e;
	}

	/**
	 * Build a shop container holding the given {itemId, qty} pairs.
	 *
	 * net.runelite.api.Item is FINAL, so Mockito cannot mock it — construct real ones. (The mock
	 * version of this helper failed with "Cannot mock/spy because - final class", 2026-09-03.)
	 */
	private static net.runelite.api.ItemContainer shopWith(int[][] pairs)
	{
		net.runelite.api.ItemContainer c = mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] items = new net.runelite.api.Item[pairs.length];
		for (int i = 0; i < pairs.length; i++)
		{
			items[i] = new net.runelite.api.Item(pairs[i][0], pairs[i][1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static Object field(AccountConnectPlugin plugin, String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * THE GATE, as one place. These overlays render other players' names on screen, so the
 * question "could an ordinary player ever see this?" must have exactly one answer: no.
 *
 * Three independent conditions, ALL required: a linked token, the backend grant, and an open shop.
 * The grant itself is server-derived from the RSN allowlist and cannot be self-issued —
 * tests/e3a/store-tools-gate.test.mjs holds that half.
 */
public class StoreToolsGateTest
{
	private static java.awt.Graphics2D g()
	{
		return new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	private static AccountConnectPlugin withToken(String token) throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return token;
			}
		});
		return p;
	}

	@Test
	public void aFreshPluginGrantsNothing() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		assertFalse("default must be closed", withToken("0123456789abcdef0123456789abcdef").storeToolsEnabled());
	}

	/** No token means no account is linked at all — the grant cannot apply to anybody. */
	@Test
	public void noLinkedTokenMeansNoOverlaysEvenWithTheGrant() throws Exception
	{
		for (String bad : new String[]{"", "   ", "not-a-token", "0123456789abcdef"})
		{
			AccountConnectPlugin p = withToken(bad);
			p.setStoreToolsForTest(true);
			assertFalse("token '" + bad + "' must not enable store tools", p.storeToolsEnabled());
		}
	}

	/** BOTH overlays must obey the gate. One of them leaking is the whole failure. */
	@Test
	public void neitherOverlayDrawsWithoutTheGrant() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setShopOpenForTest(true);		// shop open, grant withheld
		assertNull("reset overlay must stay hidden", new StoreResetOverlay(p).render(g()));
		assertNull("nearby overlay must stay hidden", new StoreNearbyOverlay(p).render(g()));
	}

	/** And with the grant, both draw — otherwise the gate is just "always off". */
	@Test
	public void bothOverlaysDrawWhenGrantedInsideAShop() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		org.junit.Assert.assertNotNull(new StoreResetOverlay(p).render(g()));
		org.junit.Assert.assertNotNull(new StoreNearbyOverlay(p).render(g()));
	}

	/** Outside a shop, a granted account still sees nothing. */
	@Test
	public void theGrantDoesNotFollowTheUserOutOfTheShop() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setStoreToolsForTest(true);		// granted, but no shop open
		assertNull(new StoreResetOverlay(p).render(g()));
		assertNull(new StoreNearbyOverlay(p).render(g()));
	}

	/**
	 * THE SHIPPED BUILD HAS NO LOCAL WAY IN. The dev override is a JVM system property, which the
	 * Plugin Hub launcher never sets — but a config item or an env read WOULD be reachable by a
	 * player, so assert the override's shape rather than trusting the comment above it.
	 */
	@Test
	public void theOverrideIsAJvmPropertyAndNothingElse() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		assertFalse(AccountConnectPlugin.storeToolsDevOverride());
		try
		{
			System.setProperty("osrsbis.storetools", "on");
			assertTrue(AccountConnectPlugin.storeToolsDevOverride());
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
		// A player-reachable surface would be a config key. There must be none.
		for (java.lang.reflect.Method m : AccountConnectConfig.class.getMethods())
		{
			assertFalse("config must expose no store-tools switch: " + m.getName(),
				m.getName().toLowerCase().contains("storetool"));
		}
	}

	/** A server revoke mid-session closes the gate immediately. */
	@Test
	public void aRevokeClosesTheGate() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setStoreToolsForTest(true);
		p.setShopOpenForTest(true);
		assertTrue(p.storeToolsEnabled());
		p.setStoreToolsForTest(false);
		assertFalse("revoke must take effect at once", p.storeToolsEnabled());
		assertNull(new StoreNearbyOverlay(p).render(g()));
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The store visit clip keeps every sale, not the last 12 seconds.
 *
 * Field defect, Arengees 2026-09-25: sells 16:37:59-16:39:51, uploaded frames 16:39:55-16:40:06, every
 * frame static. The old ring kept the NEWEST 360 frames (12s at 30fps), so any visit that ran more
 * than 12 seconds past its last sale uploaded no sale at all.
 *
 * Known-bad control: replacing StoreVisitClip's keep policy with "keep every frame, evict the oldest"
 * (the old ring) turns everySaleOfALongVisitIsInTheUpload RED.
 */
public class StoreVisitClipTest
{
	/** Measured mean frame size at 704px / q0.55 (StoreClipCaptureTest pins the width). */
	private static final int FRAME_BYTES = 30 * 1024;
	private static final long FRAME_MS = 1000L / AccountConnectPlugin.CLIP_FPS;

	private static StoreVisitClip visit()
	{
		return new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES);
	}

	/** Drive a visit: a frame every 1/30s from 0 to closeMs, a moment at each sale time. */
	private static StoreVisitClip.Snapshot run(StoreVisitClip v, long closeMs, long... sales)
	{
		int next = 0;
		for (long t = 0; t <= closeMs; t += FRAME_MS)
		{
			while (next < sales.length && sales[next] <= t)
			{
				v.onMoment(sales[next]);
				next++;
			}
			v.offer(new byte[FRAME_BYTES], t);
		}
		return v.snapshot();
	}

	private static int framesBetween(StoreVisitClip.Snapshot s, long from, long to)
	{
		int n = 0;
		for (long t : s.capturedAtMillis)
		{
			if (t >= from && t <= to)
			{
				n++;
			}
		}
		return n;
	}

	private static void assertWithinBudget(StoreVisitClip v, StoreVisitClip.Snapshot s)
	{
		assertTrue("frame budget exceeded: " + s.frames.size(),
			s.frames.size() <= AccountConnectPlugin.MAX_CLIP_FRAMES);
		long bytes = 0;
		for (byte[] f : s.frames)
		{
			bytes += f.length;
		}
		assertTrue("byte budget exceeded: " + bytes, bytes <= AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertEquals("byteSize must match the snapshot", bytes, v.byteSize());
		for (int i = 1; i < s.capturedAtMillis.size(); i++)
		{
			assertTrue("frames must be in capture order",
				s.capturedAtMillis.get(i - 1) <= s.capturedAtMillis.get(i));
		}
	}

	/** Every sale shows the click and the change after it: frames before and after the click. */
	private static void assertSaleVisible(StoreVisitClip.Snapshot s, long sale, int minAfter)
	{
		int after = framesBetween(s, sale, sale + StoreVisitClip.CORE_AFTER_MILLIS);
		assertTrue("sale at " + sale + "ms has only " + after + " frames in the 1.2s after the click",
			after >= minAfter);
		if (sale > 0)
		{
			assertTrue("sale at " + sale + "ms has no frame in the 0.5s before the click",
				framesBetween(s, sale - StoreVisitClip.CORE_BEFORE_MILLIS, sale - 1) >= 1);
		}
	}

	/** The brief's case: sales at 0s, 60s and 110s, shop closed at 125s. */
	@Test
	public void everySaleOfALongVisitIsInTheUpload()
	{
		StoreVisitClip v = visit();
		long[] sales = {0L, 60_000L, 110_000L};
		StoreVisitClip.Snapshot s = run(v, 125_000L, sales);

		assertWithinBudget(v, s);
		for (long sale : sales)
		{
			// 1.2s at 30fps is 36 frames; at least half must survive the budget.
			assertSaleVisible(s, sale, 18);
		}
		// The gaps between sales are not blank: the baseline shows the tile in between.
		assertTrue("the middle of the visit must have baseline frames",
			framesBetween(s, 20_000L, 50_000L) >= 10);
		// The visit start is in the clip.
		assertTrue("the visit start must be in the clip", s.capturedAtMillis.get(0) <= 1_000L);
		// And the old failure is gone: the clip does not start in the last 12 seconds.
		assertTrue("the clip must not be just the last 12 seconds",
			s.capturedAtMillis.get(0) < 125_000L - 12_000L);
	}

	/** A 2-minute visit with nothing sold: start plus 1fps baseline, well inside the budget. */
	@Test
	public void aTwoMinuteIdleVisitStaysWithinBudget()
	{
		StoreVisitClip v = visit();
		StoreVisitClip.Snapshot s = run(v, 120_000L);

		assertWithinBudget(v, s);
		assertEquals("no moments were marked", 0, v.momentCount());
		// 2s start at 30fps (60) + one baseline frame a second for the other ~118s.
		assertTrue("idle visit should be about 180 frames, got " + s.frames.size(),
			s.frames.size() >= 170 && s.frames.size() <= 185);
		assertTrue("the pre-roll held for lookbehind stays bounded to 2s at 30fps",
			v.preRollSize() <= 61);
	}

	/** Twenty sales spaced out over a long visit: the cap holds and every sale is still shown. */
	@Test
	public void twentySpacedSalesStayInsideTheCapAndAllAreShown()
	{
		StoreVisitClip v = visit();
		long[] sales = new long[20];
		for (int i = 0; i < 20; i++)
		{
			sales[i] = 5_000L + i * 7_000L;
		}
		StoreVisitClip.Snapshot s = run(v, 150_000L, sales);

		assertWithinBudget(v, s);
		assertEquals("the frame cap must be reached, not exceeded",
			AccountConnectPlugin.MAX_CLIP_FRAMES, s.frames.size());
		for (long sale : sales)
		{
			assertSaleVisible(s, sale, 3);
		}
	}

	/** Twenty rapid sells one second apart (a multi-item delivery): every click is still covered. */
	@Test
	public void twentyRapidSalesAreAllShown()
	{
		StoreVisitClip v = visit();
		long[] sales = new long[20];
		for (int i = 0; i < 20; i++)
		{
			sales[i] = 10_000L + i * 1_000L;
		}
		StoreVisitClip.Snapshot s = run(v, 90_000L, sales);

		assertWithinBudget(v, s);
		for (long sale : sales)
		{
			assertSaleVisible(s, sale, 3);
		}
		assertTrue("the visit start survives many sales", s.capturedAtMillis.get(0) <= 2_000L);
	}

	/** The byte cap binds too: frames larger than the measured mean still keep every sale. */
	/**
	 * PIO-014: the GS video budget is 16 MiB. A full 360-frame visit at 44 KB/frame (~15.8 MB, the
	 * current quality at a busy scene) keeps every frame, both in the visit selector and in the final
	 * upload selection. Under the old 12MB budget about a quarter of these frames were cut.
	 */
	@Test
	public void aFullVisitAt44KbPerFrameKeepsAll360Frames()
	{
		StoreVisitClip v = visit();
		long[] sales = {2_000L, 5_000L, 8_000L, 11_000L};	// windows cover the whole 12 s
		int next = 0;
		int offered = 0;
		for (long t = 0; offered < AccountConnectPlugin.MAX_CLIP_FRAMES; t += FRAME_MS)
		{
			while (next < sales.length && sales[next] <= t)
			{
				v.onMoment(sales[next++]);
			}
			v.offer(new byte[44_000], t);
			offered++;
		}
		StoreVisitClip.Snapshot s = v.snapshot();
		assertEquals("every frame of a 360-frame visit at 44 KB is kept", 360, s.frames.size());
		assertWithinBudget(v, s);
		assertEquals(360, AccountConnectPlugin.selectStoreClipFrames(s.frames, AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_FRAME_BYTES, AccountConnectPlugin.MAX_CLIP_BURST_BYTES).size());
		assertEquals("the retry budget is two visits (32 MiB)", 32L * 1024 * 1024, AccountConnectPlugin.CLIP_RETRY_BYTE_BUDGET);
	}

	@Test
	public void theByteCapIsRespectedWithLargeFrames()
	{
		StoreVisitClip v = new StoreVisitClip(AccountConnectPlugin.MAX_CLIP_FRAMES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES);
		long[] sales = {3_000L, 40_000L, 80_000L};
		int next = 0;
		for (long t = 0; t <= 100_000L; t += FRAME_MS)
		{
			while (next < sales.length && sales[next] <= t)
			{
				v.onMoment(sales[next++]);
			}
			v.offer(new byte[100_000], t);	// 100KB: the byte cap (16 MiB = 167 frames) binds first
		}
		StoreVisitClip.Snapshot s = v.snapshot();
		assertTrue("16 MiB cap", v.byteSize() <= AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertTrue("bytes cap bound the frame count", s.frames.size() <= 167);
		for (long sale : sales)
		{
			assertSaleVisible(s, sale, 3);
		}
	}

	/** Frames that fail to encode or exceed the per-frame cap are never kept. */
	@Test
	public void emptyAndOversizedFramesAreIgnored()
	{
		StoreVisitClip v = visit();
		v.offer(null, 0L);
		v.offer(new byte[0], 10L);
		v.offer(new byte[AccountConnectPlugin.MAX_CLIP_FRAME_BYTES + 1], 20L);
		assertEquals(0, v.size());
		v.offer(new byte[10], 30L);
		assertEquals(1, v.size());
	}

	/**
	 * WIRING: a real Sell click during a capturing visit marks a moment on the visit clip. Without
	 * this call the clip falls back to start + baseline and the sale is only seen by chance.
	 */
	@Test
	public void aSellClickMarksAMomentOnTheVisitClip() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() { });
		inject(plugin, "client", org.mockito.Mockito.mock(net.runelite.api.Client.class));
		StoreVisitClip v = visit();
		inject(plugin, "clipVisit", v);
		inject(plugin, "clipCapturing", true);
		inject(plugin, "shopOpen", true);

		net.runelite.api.events.MenuOptionClicked sell =
			org.mockito.Mockito.mock(net.runelite.api.events.MenuOptionClicked.class);
		org.mockito.Mockito.when(sell.getMenuOption()).thenReturn("Sell 1");
		org.mockito.Mockito.when(sell.getItemId()).thenReturn(1511);
		plugin.onMenuOptionClicked(sell);

		assertEquals("the sell click must mark one moment", 1, v.momentCount());
		assertTrue("and still flag the visit for upload", plugin.storeTxThisVisit);

		// Outside a capturing visit nothing is marked.
		inject(plugin, "clipCapturing", false);
		plugin.onMenuOptionClicked(sell);
		assertEquals(1, v.momentCount());
	}

	/** The uploader stamps each chunk with its OWN first frame's capture time, not a derived one. */
	@Test
	public void chunksAreStampedWithTheirFirstFramesRealCaptureTime()
	{
		StoreVisitClip v = visit();
		StoreVisitClip.Snapshot s = run(v, 125_000L, 0L, 60_000L, 110_000L);
		List<Integer> idx = AccountConnectPlugin.selectStoreClipFrameIndexes(s.frames,
			AccountConnectPlugin.MAX_CLIP_FRAMES, AccountConnectPlugin.MAX_CLIP_FRAME_BYTES,
			AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertEquals("the visit clip is already inside the budget, so nothing is trimmed",
			s.frames.size(), idx.size());
		int chunks = (idx.size() + AccountConnectPlugin.CLIP_CHUNK_FRAMES - 1) / AccountConnectPlugin.CLIP_CHUNK_FRAMES;
		assertTrue("a full visit is still at most 9 chunks of 40", chunks <= 9);
		long prev = -1;
		for (int off = 0; off < idx.size(); off += AccountConnectPlugin.CLIP_CHUNK_FRAMES)
		{
			// captured_at goes on the wire in whole SECONDS and the collector orders chunks on it, so
			// two chunks sharing a second would be ordered by a random burst id. 40 frames at 30fps
			// span at least 1.3s, so the seconds must strictly increase.
			long atSec = s.capturedAtMillis.get(idx.get(off)) / 1000L;
			assertTrue("chunk captured_at seconds must strictly increase", atSec > prev);
			prev = atSec;
		}
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.any;
import static org.mockito.Mockito.anyLong;
import static org.mockito.Mockito.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.client.game.ItemManager;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * WAVE 2 — real-time sync. Every tracked event flushes live (coalesced into a ~1s window so a burst is ONE
 * POST, not one per line), and a state-changing event (trade/ge/store/death) forces an immediate snapshot.
 */
public class RealtimeFlushTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private MockWebServer server;
	private AccountConnectPlugin plugin;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	private void inject(String fieldName, Object value) throws Exception
	{
		Field field = AccountConnectPlugin.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	private AccountConnectConfig cfg()
	{
		final String base = server.url("/").toString();
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

			@Override
			public String apiBaseUrl()
			{
				return base;
			}
		};
	}

	private static Map<String, Object> field(String k, Object v)
	{
		Map<String, Object> m = new LinkedHashMap<>();
		m.put(k, v);
		return m;
	}

	/** A burst of events schedules exactly one coalesced flush (not one per event). */
	@Test
	public void burstOfEventsSchedulesFlushOnce() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("config", cfg());
		ScheduledExecutorService exec = mock(ScheduledExecutorService.class);
		inject("executor", exec);

		plugin.emitEvent("chat", field("text", "line one"));
		plugin.emitEvent("chat", field("text", "line two"));
		plugin.emitEvent("chat", field("text", "line three"));

		verify(exec, times(1)).schedule(any(Runnable.class), anyLong(), eq(TimeUnit.MILLISECONDS));
		assertEquals("all three buffered for a single coalesced flush", 3, plugin.pendingEvents.size());
	}

	/** A rapid burst becomes exactly ONE /event-ingest POST carrying every event; a later event opens a new window. */
	@Test
	public void burstBecomesSinglePost() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("config", cfg());
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
		ScheduledExecutorService exec = Executors.newSingleThreadScheduledExecutor();
		inject("executor", exec);
		plugin.eventCoalesceMillis = 120L;
		server.enqueue(new MockResponse().setResponseCode(200));
		server.enqueue(new MockResponse().setResponseCode(200));

		plugin.emitEvent("chat", field("text", "a"));
		plugin.emitEvent("chat", field("text", "b"));
		plugin.emitEvent("chat", field("text", "c"));

		RecordedRequest r1 = server.takeRequest(5, TimeUnit.SECONDS);
		assertNotNull("the burst must flush", r1);
		assertTrue("chat flushes to /event-ingest (not a forced snapshot)", r1.getPath().contains("/event-ingest"));
		Map<?, ?> body = new Gson().fromJson(r1.getBody().readUtf8(), Map.class);
		assertEquals("three events coalesced into one POST", 3, ((List<?>) body.get("events")).size());
		assertNull("no second POST for the same burst", server.takeRequest(300, TimeUnit.MILLISECONDS));

		plugin.emitEvent("chat", field("text", "d"));
		RecordedRequest r2 = server.takeRequest(5, TimeUnit.SECONDS);
		assertNotNull("a later event opens a fresh window -> a second POST", r2);
		exec.shutdownNow();
	}

	/** A state-changing event forces an immediate snapshot AND flushes the event; chat only flushes the event. */
	@Test
	public void stateChangingEventForcesImmediateSnapshot() throws Exception
	{
		plugin = new AccountConnectPlugin();
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(player.getName()).thenReturn("TestPlayer");
		when(player.getCombatLevel()).thenReturn(100);
		ItemManager itemManager = mock(ItemManager.class);

		inject("client", client);
		inject("itemManager", itemManager);
		inject("config", cfg());
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
		inject("executor", Executors.newSingleThreadScheduledExecutor());
		plugin.eventCoalesceMillis = 60L;
		server.enqueue(new MockResponse().setResponseCode(200));
		server.enqueue(new MockResponse().setResponseCode(200));

		plugin.emitEvent("ge_buy", field("item", 4151));

		boolean sawSnapshot = false;
		boolean sawEvent = false;
		for (int i = 0; i < 2; i++)
		{
			RecordedRequest r = server.takeRequest(5, TimeUnit.SECONDS);
			assertNotNull("expected both a snapshot and an event POST", r);
			if (r.getPath().contains("/account-ingest"))
			{
				sawSnapshot = true;
			}
			if (r.getPath().contains("/event-ingest"))
			{
				sawEvent = true;
			}
		}
		assertTrue("a state-changing event must force an immediate snapshot", sawSnapshot);
		assertTrue("a state-changing event must also flush the event", sawEvent);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * CONTROLLED DROP -> SELF-PICKUP. Reproduces the live 2026-09-11 grokerini test: three items dropped in
 * rapid succession, one left on the ground, two picked back up by the same account.
 */
public class SelfPickupTest
{
	private static final int CHAPS = 2495;
	private static final int DIAMOND = 1617;
	private static final int COINS = 995;
	private static final int POT = 1931;
	private static final int TILE_X = 3210;
	private static final int TILE_Y = 3420;

	@Test
	public void dropThreeThenPickTwoBackUp() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1, DIAMOND, 1, COINS, 10);

		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));
		tick(plugin, 105);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		tick(plugin, 108);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));

		setInventory(plugin);	// inventory now empty of all three
		plugin.resolveDropPendingOnGroundSpawn(CHAPS, 0, 0L, 100);
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 105);
		plugin.resolveDropPendingOnGroundSpawn(COINS, 0, 0L, 108);

		assertEquals("all three drops must emit", 3, eventsOfType(plugin, "drop").size());

		// --- pick the diamond back up ---
		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));

		// --- pick the 10 coins back up ---
		tick(plugin, 150);
		plugin.onMenuOptionClicked(menu("Take", "Coins", COINS));
		setInventory(plugin, DIAMOND, 1, COINS, 10);
		plugin.onItemContainerChanged(containerChanged(plugin));

		List<Integer> picked = eventsOfType(plugin, "pickup");
		assertEquals("both self-pickups must emit exactly once: " + picked, 2, picked.size());
		assertTrue("diamond self-pickup lost", picked.contains(DIAMOND));
		assertTrue("coin self-pickup lost", picked.contains(COINS));
	}


	/** Isolates the PICKUP stage: one drop only, so the single-slot drop defect cannot confound it. */
	@Test
	public void oneDropThenPickItBackUp() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(DIAMOND, 1);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		setInventory(plugin);
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 100);
		assertEquals("the single drop must emit", 1, eventsOfType(plugin, "drop").size());

		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("self-pickup after own drop must emit", 1, eventsOfType(plugin, "pickup").size());
	}

	/** Bare pickup, no preceding drop — the general mechanism the corpus already shows working. */
	@Test
	public void barePickupWithNoPrecedingDrop() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("bare pickup must emit", 1, eventsOfType(plugin, "pickup").size());
	}

	/**
	 * THE REAL GROUND-TAKE SHAPE, captured from a live client on 2026-09-12.
	 *
	 * Dropping a Pot and taking it back on world 308 produced exactly this MenuOptionClicked:
	 *   option=Take target=<col=ff9040>Pot id=1931 itemId=-1 param0=49 param1=54
	 *   type=GROUND_ITEM_THIRD_OPTION
	 *
	 * This test previously asserted that NO pickup is emitted here, which encoded the defect as
	 * correct behaviour and is why a green suite missed a live failure on two real staff accounts.
	 */
	@Test
	public void aRealGroundTakeEmitsItsPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTake("Pot", POT));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("a ground Take carries its item id in the entry identifier, not getItemId()",
			1, eventsOfType(plugin, "pickup").size());
		assertEquals(Integer.valueOf(POT), eventsOfType(plugin, "pickup").get(0));
	}

	/** An entry with NEITHER source populated must still be skipped, not guessed at. */
	@Test
	public void aTakeWithNoUsableIdAnywhereStillEmitsNothing() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTake("Pot", -1));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals(0, eventsOfType(plugin, "pickup").size());
	}

	/** The fallback is pickup-ONLY: an inventory entry's identifier is an option index, not an item. */
	@Test
	public void theIdentifierFallbackDoesNotApplyToOtherOpcodes() throws Exception
	{
		MenuOptionClicked drop = mock(MenuOptionClicked.class);
		when(drop.getMenuOption()).thenReturn("Drop");
		when(drop.getItemId()).thenReturn(-1);
		when(drop.getId()).thenReturn(7);          // the real Drop entry's identifier: option index
		assertEquals("a Drop must never adopt the option index as an item id",
			-1, AccountConnectPlugin.offBookItemId(drop, "drop"));
	}

	/**
	 * The identifier is only an item id on a GROUND_ITEM_* opcode.
	 *
	 * Matching the option word "Take" alone would adopt the identifier of any other entry that
	 * happens to be labelled Take — a widget button, a future interface — where the identifier is
	 * an option index or a widget id, not an item. The opcode is what makes the field meaningful.
	 */
	@Test
	public void aTakeOnANonGroundOpcodeNeverAdoptsItsIdentifier()
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(9764864);	// a widget id, not an item
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.CC_OP_LOW_PRIORITY);
		assertEquals("only a ground-item opcode puts an item id in the identifier",
			-1, AccountConnectPlugin.offBookItemId(m, "pickup"));
	}

	/** Every ground-item option index is a valid source, not just the third. */
	@Test
	public void everyGroundItemOpcodeCarriesItsItemIdInTheIdentifier()
	{
		for (net.runelite.api.MenuAction a : new net.runelite.api.MenuAction[]{
			net.runelite.api.MenuAction.GROUND_ITEM_FIRST_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_SECOND_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_FOURTH_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_FIFTH_OPTION})
		{
			MenuOptionClicked m = mock(MenuOptionClicked.class);
			when(m.getItemId()).thenReturn(-1);
			when(m.getId()).thenReturn(POT);
			when(m.getMenuAction()).thenReturn(a);
			assertEquals(a.toString(), POT, AccountConnectPlugin.offBookItemId(m, "pickup"));
		}
	}

	/** An inventory action with a good getItemId() keeps using it, identifier ignored. */
	@Test
	public void aNormalInventoryActionStillUsesGetItemId()
	{
		MenuOptionClicked drop = mock(MenuOptionClicked.class);
		when(drop.getItemId()).thenReturn(1931);
		when(drop.getId()).thenReturn(7);
		assertEquals(1931, AccountConnectPlugin.offBookItemId(drop, "drop"));
	}


	/** EXACT live shape: three drops each confirmed by its own ground spawn, then a Take. */
	@Test
	public void liveShapeThreeConfirmedDropsThenTake() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1, DIAMOND, 1, COINS, 10);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));
		plugin.resolveDropPendingOnGroundSpawn(CHAPS, 0, 0L, 100);
		tick(plugin, 105);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 105);
		tick(plugin, 108);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		plugin.resolveDropPendingOnGroundSpawn(COINS, 0, 0L, 108);
		setInventory(plugin);
		assertEquals("live shape: all three drops emitted", 3, eventsOfType(plugin, "drop").size());

		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("the self-pickup after the live drop shape must emit",
			1, eventsOfType(plugin, "pickup").size());
	}

	/** A Drop click that never gets a ground spawn leaves a pending. Does it swallow a later Take? */
	@Test
	public void staleUnconfirmedDropDoesNotSwallowALaterPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));	// no ground spawn ever arrives

		tick(plugin, 102);					// 2 ticks later, well inside DROP_PENDING_MAX_TICKS
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, CHAPS, 1, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("a stale drop pending must not swallow a real pickup",
			1, eventsOfType(plugin, "pickup").size());
	}

	// ---------------------------------------------------------------- harness

	private static AccountConnectPlugin newPlugin(int... idQtyPairs) throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv0 = container(idQtyPairs);
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv0);
		when(client.getVarbitValue(Varbits.IN_WILDERNESS)).thenReturn(0);
		when(client.getTickCount()).thenReturn(100);
		// WorldPoint.fromScene() reads the world view's base coordinates. Base 0 makes the scene
		// coordinates in a Take menu entry equal to world coordinates, which keeps the tile
		// assertions readable. Without this the conversion returns null and every tile check
		// silently degrades to item-id-only matching — i.e. passes for the wrong reason.
		net.runelite.api.WorldView wv = mock(net.runelite.api.WorldView.class);
		when(wv.getBaseX()).thenReturn(0);
		when(wv.getBaseY()).thenReturn(0);
		when(client.getTopLevelWorldView()).thenReturn(wv);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(TILE_X, TILE_Y, 0));
		inject(plugin, "client", client);
		return plugin;
	}

	private static void setInventory(AccountConnectPlugin plugin, int... idQtyPairs) throws Exception
	{
		ItemContainer next = container(idQtyPairs);
		when(client(plugin).getItemContainer(InventoryID.INVENTORY)).thenReturn(next);
	}

	/** The real client hands the changed INVENTORY container to onItemContainerChanged. */
	private static net.runelite.api.events.ItemContainerChanged containerChanged(AccountConnectPlugin plugin)
		throws Exception
	{
		ItemContainer inv = client(plugin).getItemContainer(InventoryID.INVENTORY);
		return new net.runelite.api.events.ItemContainerChanged(InventoryID.INVENTORY.getId(), inv);
	}

	private static Client client(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		return (Client) f.get(plugin);
	}

	private static void tick(AccountConnectPlugin plugin, int t) throws Exception
	{
		when(client(plugin).getTickCount()).thenReturn(t);
	}

	private static List<Integer> eventsOfType(AccountConnectPlugin plugin, String type)
	{
		List<Integer> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if (type.equals(e.get("type")))
			{
				out.add((Integer) e.get("item"));
			}
		}
		return out;
	}

	/** The REAL ground-item Take entry: itemId is -1, the item id sits in the identifier. */
	private static MenuOptionClicked groundTake(String name, int itemId)
	{
		return groundTakeAt(name, itemId, TILE_X, TILE_Y);
	}

	/**
	 * The REAL ground-item Take entry, aimed at one specific tile.
	 *
	 * itemId is -1, the item id sits in the identifier, the opcode is GROUND_ITEM_THIRD_OPTION and
	 * param0/param1 carry the pile's SCENE coordinates. The test client mock reports base 0, so the
	 * scene coordinates ARE the world coordinates here.
	 */
	private static MenuOptionClicked groundTakeAt(String name, int itemId, int x, int y)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getMenuTarget()).thenReturn("<col=ff9040>" + name);
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(itemId);
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION);
		when(m.getParam0()).thenReturn(x);
		when(m.getParam1()).thenReturn(y);
		return m;
	}

	private static MenuOptionClicked menu(String option, String target, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn(option);
		when(m.getMenuTarget()).thenReturn(target);
		when(m.getItemId()).thenReturn(itemId);
		return m;
	}

	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static AccountConnectConfig onConfig()
	{
		return (AccountConnectConfig) java.lang.reflect.Proxy.newProxyInstance(
			AccountConnectConfig.class.getClassLoader(),
			new Class<?>[]{AccountConnectConfig.class},
			(proxy, method, args) -> {
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class || rt == Boolean.class) { return Boolean.TRUE; }
				if (rt == String.class) { return "0123456789abcdef0123456789abcdef"; }
				if (rt == int.class || rt == Integer.class) { return 0; }
				return null;
			});
	}
}

package com.osrsbestinslot.export;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The standalone reset countdown. Split from the nearby panel because a list that changes height
 * moved the number around the screen — so the arms here are mostly about STAYING STILL.
 */
public class StoreResetOverlayTest
{
	private static Graphics2D graphics()
	{
		return new BufferedImage(400, 300, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	/**
	 * THE JITTER FIX. The overlay must draw exactly one row in every state, so its height can never
	 * change. This is the whole reason it is a separate overlay.
	 */
	@Test
	public void alwaysDrawsExactlyOneRowWhateverTheState() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);

		// phase unknown
		o.render(graphics());
		assertEquals("waiting state must be one row", 1, o.builtRowCountForTest());

		// phase known — drive the anchor through the real field
		java.lang.reflect.Field a = AccountConnectPlugin.class.getDeclaredField("storeResetAnchorMs");
		a.setAccessible(true);
		a.setLong(p, System.currentTimeMillis() - 30_000L);
		o.render(graphics());
		assertEquals("counting state must also be one row", 1, o.builtRowCountForTest());
	}

	@Test
	public void repeatedRendersDoNotAccumulateRows() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);
		for (int i = 0; i < 25; i++)
		{
			o.render(graphics());
		}
		assertEquals("the panel must not grow across frames", 1, o.builtRowCountForTest());
	}

	@Test
	public void drawsNothingOutsideAShopOrWithoutTheGrant() throws Exception
	{
		AccountConnectPlugin outside = plugin();
		outside.setStoreToolsForTest(true);
		assertNull("no shop, no overlay", new StoreResetOverlay(outside).render(graphics()));

		AccountConnectPlugin ungranted = plugin();
		ungranted.setShopOpenForTest(true);
		assertNull("no grant, no overlay", new StoreResetOverlay(ungranted).render(graphics()));
	}

	@Test
	public void drawsWhileAShopIsOpenAndGranted() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		Dimension d = new StoreResetOverlay(p).render(graphics());
		assertNotNull(d);
	}

	@Test
	public void theWaitingStateIsNamedAndNeutral() throws Exception
	{
		// A blank or red waiting state is the failure: blank looks broken, red is a standing
		// "do not hand off" warning on a shop that has never reset.
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);
		o.render(graphics());
		assertEquals("sell junk", o.lastTextForTest());
		org.junit.Assert.assertNotEquals("waiting must not look urgent",
			StoreResetOverlay.countdownColor(1), o.lastColorForTest());
	}

	@Test
	public void theCountdownRoundsUpAndNeverShowsZero()
	{
		assertEquals("sell junk", StoreResetOverlay.resetText(0));
		assertEquals("sell junk", StoreResetOverlay.resetText(-5));
		assertEquals("1s", StoreResetOverlay.resetText(1));
		assertEquals("rounds up", "1s", StoreResetOverlay.resetText(999));
		assertEquals("13s", StoreResetOverlay.resetText(12_500));
		assertEquals("60s", StoreResetOverlay.resetText(60_000));
	}

	@Test
	public void theColourBandsAreDistinctAndOrdered()
	{
		java.awt.Color safe = StoreResetOverlay.countdownColor(StoreResetOverlay.SAFE_SECONDS);
		java.awt.Color mid = StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS + 1);
		java.awt.Color urgent = StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS);
		org.junit.Assert.assertNotEquals(safe, mid);
		org.junit.Assert.assertNotEquals(mid, urgent);
		org.junit.Assert.assertNotEquals(safe, urgent);
		assertTrue("urgent reads red", urgent.getRed() > urgent.getGreen());
		assertTrue("safe reads green", safe.getGreen() > safe.getRed());
	}

	@Test
	public void theUrgentBandIsInclusiveOfItsBoundary()
	{
		assertEquals(StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS),
			StoreResetOverlay.countdownColor(1));
		org.junit.Assert.assertNotEquals(
			StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS),
			StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS + 1));
	}
}

package com.osrsbestinslot.export;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * The release branch must not still declare the SHIPPED version.
 *
 * WHY THIS EXISTS, and it is not hypothetical. This branch sat at `version = '0.7.13'` through two
 * commits whose messages both said the version had been bumped. The bump was written, the write was
 * in a command a commit hook rejected, and the retry committed nothing — so the claim survived in
 * prose while the file never changed. A privacy review caught it, at which point the branch would
 * have shipped to the Plugin Hub declaring the version already pinned there, making a Hub build and
 * a local build indistinguishable by version.
 *
 * No build step reads this number for correctness, which is exactly why nothing else catches it.
 * The one number a human is guaranteed to quote in a release report is the one number nothing
 * verified.
 *
 * 0.7.14 is the SHIPPED version: the hub manifest `plugins/osrs-best-in-slot` pins commit
 * afb4721 (plugin-hub PR #17186, merged 2026-09-27), and that commit declares 0.7.14. So the rule is
 * stated as a DIFFERENCE from the shipped version rather than as an equality with a literal: this file
 * only has to be edited when the shipped baseline moves.
 */
public class ReleaseVersionTest
{
	/** The version declared by afb4721, the commit the Plugin Hub pins today. */
	private static final String SHIPPED_VERSION = "0.7.14";

	private static String declaredVersion() throws IOException
	{
		// Walk up to the module root rather than assuming the working directory: gradle and an IDE
		// start tests from different places, and a test that cannot find its own build file would
		// otherwise pass vacuously.
		Path dir = Paths.get("").toAbsolutePath();
		while (dir != null && !Files.exists(dir.resolve("build.gradle")))
		{
			dir = dir.getParent();
		}
		assertTrue("build.gradle must be findable, or this test proves nothing", dir != null);

		List<String> lines = Files.readAllLines(dir.resolve("build.gradle"));
		Pattern p = Pattern.compile("^version\\s*=\\s*'([^']+)'\\s*$");
		String found = null;
		int hits = 0;
		for (String line : lines)
		{
			Matcher m = p.matcher(line);
			if (m.matches())
			{
				found = m.group(1);
				hits++;
			}
		}
		// EXACTLY ONE, because two assignments would mean the build uses the last and a reader the
		// first. An ambiguous build file is a refusal, not a best guess.
		assertEquals("build.gradle must declare exactly one version", 1, hits);
		return found;
	}

	@Test
	public void theReleaseBranchDoesNotDeclareTheShippedVersion() throws IOException
	{
		assertNotEquals(
			"this branch still declares the SHIPPED version, so a Hub build and this build would be "
				+ "indistinguishable by version — bump build.gradle",
			SHIPPED_VERSION, declaredVersion());
	}

	@Test
	public void theDeclaredVersionIsAPlausibleRelease() throws IOException
	{
		// A guard against "fixing" the test above by deleting the number or writing something that
		// is not a version at all.
		assertTrue("the version must look like x.y.z", declaredVersion().matches("\\d+\\.\\d+\\.\\d+"));
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import okhttp3.mockwebserver.SocketPolicy;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * 0.7.4 item 2 — BOUNDED RELIABLE EVENT DELIVERY.
 *
 * <p>Before this change {@code flushEvents} cleared the buffer BEFORE sending and {@code onFailure} was
 * a bare {@code log.debug}, so any 429 / 5xx / timeout destroyed that batch silently and permanently.
 * Production evidence: the shared ingest ceiling was saturated for six consecutive hours on 2026-08-14,
 * which is exactly when clients would have been receiving those responses.
 *
 * <p>These tests drive a REAL {@link MockWebServer} over real OkHttp rather than a mocked call, because
 * the defect lives in the callback wiring — a stubbed client would test the stub. Each asserts the whole
 * contract: the batch SURVIVES, it is RETRIED, and on success it is delivered EXACTLY ONCE.
 */
public class EventDeliveryRetryTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private MockWebServer server;
	private AccountConnectPlugin plugin;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
		plugin = new AccountConnectPlugin();
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient.Builder()
			.connectTimeout(2, TimeUnit.SECONDS)
			.readTimeout(2, TimeUnit.SECONDS)
			.build());

		AccountConnectConfig config = mock(AccountConnectConfig.class);
		when(config.linkToken()).thenReturn(TOKEN);
		when(config.apiBaseUrl()).thenReturn(server.url("/api").toString().replaceAll("/+$", ""));
		inject("config", config);
	}

	@After
	public void tearDown() throws Exception
	{
		server.shutdown();
	}

	private void inject(String fieldName, Object value) throws Exception
	{
		Field field = AccountConnectPlugin.class.getDeclaredField(fieldName);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	/**
	 * Seed the buffer — this suite tests DELIVERY, not the emit path, so it appends directly rather than
	 * going through emitEvent (which would need a live client, an active token and an account hash).
	 *
	 * <p>It DOES reproduce emitEvent's drop-oldest cap (AccountConnectPlugin:753-757), because the 500
	 * bound is enforced by the two writers — emitEvent and requeueEvents — rather than by the list
	 * itself. A helper that appended without the cap would let the buffer exceed a limit the real code
	 * never allows, and the backpressure test would then be measuring the harness instead of the plugin.
	 */
	private void seed(String type)
	{
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", type);
		ev.put("ts", 1_700_000_000_000L);
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
			while (plugin.pendingEvents.size() > 500)
			{
				plugin.pendingEvents.remove(0);
			}
		}
	}

	private int buffered()
	{
		synchronized (plugin.pendingEvents)
		{
			return plugin.pendingEvents.size();
		}
	}

	/** Clear the backoff so a test can drive consecutive attempts without sleeping. */
	private void clearBackoff()
	{
		plugin.eventRetryBackoffUntilMs = 0L;
	}

	// ---------------------------------------------------------------- 5xx

	@Test
	public void serverErrorRequeuesTheBatchAndASubsequentFlushDeliversItExactlyOnce() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(503));
		server.enqueue(new MockResponse().setResponseCode(200));

		seed("trade");
		plugin.flushEvents();
		RecordedRequest first = server.takeRequest(3, TimeUnit.SECONDS);
		assertNotNull("the first POST should have been made", first);

		// The batch must be BACK in the buffer, not destroyed.
		waitFor(() -> buffered() == 1, "batch requeued after 503");
		assertTrue("a failure must arm the backoff", plugin.eventRetryBackoffUntilMs > 0);

		clearBackoff();
		plugin.flushEvents();
		RecordedRequest second = server.takeRequest(3, TimeUnit.SECONDS);
		assertNotNull("the batch should have been retried", second);
		assertTrue("the retry must carry the same event", second.getBody().readUtf8().contains("trade"));

		// Delivered: buffer drains and stays drained — exactly one successful delivery.
		waitFor(() -> buffered() == 0, "buffer drained after 200");
		plugin.flushEvents();
		assertNull("no third POST — an empty buffer must not resend",
			server.takeRequest(1, TimeUnit.SECONDS));
		assertEquals("exactly 2 requests total: the failure and the successful retry",
			2, server.getRequestCount());
	}

	// ---------------------------------------------------------------- 429

	@Test
	public void rateLimitRequeuesAndHonoursRetryAfter() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(429).setHeader("Retry-After", "42"));

		seed("store_buy");
		plugin.flushEvents();
		assertNotNull(server.takeRequest(3, TimeUnit.SECONDS));

		waitFor(() -> buffered() == 1, "batch requeued after 429");
		// WAIT ON THE BACKOFF, NOT THE BUFFER. requeueEvents refills pendingEvents FIRST and arms the
		// backoff fields afterwards, so buffered()==1 can be true while eventRetryBackoffUntilMs is
		// still 0. Reading it in that window measured -1789916708150ms and failed this arm, once, on
		// 2026-09-20. Production is unaffected: requeueEvents clears eventPostInFlight last of all, and
		// flushEvents refuses to send while that flag is set, so no early POST can escape.
		waitFor(() -> plugin.eventRetryBackoffUntilMs != 0L, "backoff armed after 429");
		// 42s from the server beats the 5s base rung of the ladder, and is under the 300s ceiling.
		long waitMs = plugin.eventRetryBackoffUntilMs - plugin.nowMs();
		assertTrue("Retry-After should push the next attempt out to ~42s, got " + waitMs + "ms",
			waitMs > 30_000L && waitMs <= 42_000L);

		// While backing off, a flush must NOT fire — that is the point of the backoff.
		plugin.flushEvents();
		assertNull("no POST while backing off", server.takeRequest(1, TimeUnit.SECONDS));
		assertEquals(1, buffered());
	}

	// ---------------------------------------------------------------- network failure

	@Test
	public void networkFailureRequeuesTheBatch() throws Exception
	{
		server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.DISCONNECT_AT_START));

		seed("ge_buy");
		plugin.flushEvents();

		waitFor(() -> buffered() == 1, "batch requeued after a network failure");
		assertTrue("a network failure must arm the backoff", plugin.eventRetryBackoffUntilMs > 0);
	}

	// ---------------------------------------------------------------- ordering + bound

	@Test
	public void requeuePreservesChronologicalOrderAgainstEventsLoggedDuringTheFlight() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(500));

		seed("older");
		plugin.flushEvents();
		assertNotNull(server.takeRequest(3, TimeUnit.SECONDS));
		waitFor(() -> buffered() >= 1, "requeued");

		seed("newer");	// logged after the failed batch was taken
		synchronized (plugin.pendingEvents)
		{
			assertEquals("the requeued (older) event must sit in FRONT of the newer one",
				"older", plugin.pendingEvents.get(0).get("type"));
			assertEquals("newer", plugin.pendingEvents.get(1).get("type"));
		}
	}

	@Test
	public void requeueIsBoundedByMaxPendingEventsSoAnOutageCannotGrowMemory() throws Exception
	{
		// A batch larger than the cap: the requeue must drop the OLDEST, exactly like logEvent does.
		List<Map<String, Object>> big = new ArrayList<>();
		for (int i = 0; i < 600; i++)
		{
			Map<String, Object> ev = new LinkedHashMap<>();
			ev.put("type", "e" + i);
			big.add(ev);
		}
		plugin.requeueEvents(big, 0L);

		assertEquals("requeue must respect MAX_PENDING_EVENTS (500)", 500, buffered());
		synchronized (plugin.pendingEvents)
		{
			assertEquals("the OLDEST should have been dropped, keeping the newest 500",
				"e100", plugin.pendingEvents.get(0).get("type"));
			assertEquals("e599", plugin.pendingEvents.get(499).get("type"));
		}
	}

	@Test
	public void backoffLadderDoublesAndIsCapped() throws Exception
	{
		List<Map<String, Object>> one = new ArrayList<>();
		one.add(new LinkedHashMap<>());

		plugin.requeueEvents(one, 0L);
		assertEquals("first rung is the 5s flush period", 5_000L, plugin.eventRetryBackoffMs);
		plugin.requeueEvents(one, 0L);
		assertEquals(10_000L, plugin.eventRetryBackoffMs);
		plugin.requeueEvents(one, 0L);
		assertEquals(20_000L, plugin.eventRetryBackoffMs);

		for (int i = 0; i < 20; i++)
		{
			plugin.requeueEvents(one, 0L);
		}
		assertEquals("the ladder must cap at 5 minutes", 300_000L, plugin.eventRetryBackoffMs);
	}

	// ---------------------------------------------------------------- non-retryable

	@Test
	public void nonRetryableClientErrorDropsTheBatchRatherThanLoopingForever() throws Exception
	{
		// A 400 would fail identically on every retry (malformed body / bad token), so retrying it
		// would be an infinite loop against the server. It is dropped deliberately.
		server.enqueue(new MockResponse().setResponseCode(400));

		seed("trade");
		plugin.flushEvents();
		assertNotNull(server.takeRequest(3, TimeUnit.SECONDS));

		waitFor(() -> buffered() == 0, "a 400 drops the batch");
		assertEquals("a non-retryable failure must NOT arm the backoff", 0L, plugin.eventRetryBackoffUntilMs);
	}

	@Test
	public void successResetsTheBackoffLadder() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(503));
		server.enqueue(new MockResponse().setResponseCode(200));

		seed("trade");
		plugin.flushEvents();
		assertNotNull(server.takeRequest(3, TimeUnit.SECONDS));
		waitFor(() -> plugin.eventRetryBackoffMs == 5_000L, "ladder armed");

		clearBackoff();
		plugin.flushEvents();
		assertNotNull(server.takeRequest(3, TimeUnit.SECONDS));
		waitFor(() -> plugin.eventRetryBackoffMs == 0L, "a delivery resets the ladder");
	}

	// ---------------------------------------------------------------- explicit no-duplicate proof

	/**
	 * EXACTLY-ONCE after recovery, proven by BODY not just by request count.
	 *
	 * <p>The failure mode worth fearing in a retry design is double delivery: the same event landing
	 * twice in production D1, silently inflating every downstream total. This drives a full
	 * fail → retry → succeed cycle and then asserts that across ALL requests the server received, the
	 * event appears exactly twice on the wire (once refused, once accepted) and that the buffer is empty
	 * afterwards — so no third copy can ever be sent.
	 */
	@Test
	public void aSuccessfulRetryDeliversTheEventExactlyOnceAndNeverAgain() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(503));
		server.enqueue(new MockResponse().setResponseCode(200));

		seed("trade_unique_marker");
		plugin.flushEvents();
		String firstBody = server.takeRequest(3, TimeUnit.SECONDS).getBody().readUtf8();
		waitFor(() -> buffered() == 1, "requeued after 503");

		clearBackoff();
		plugin.flushEvents();
		String secondBody = server.takeRequest(3, TimeUnit.SECONDS).getBody().readUtf8();
		waitFor(() -> buffered() == 0, "delivered");

		assertTrue("the refused attempt carried the event", firstBody.contains("trade_unique_marker"));
		assertTrue("the accepted attempt carried the event", secondBody.contains("trade_unique_marker"));
		assertEquals("one occurrence per request — never batched twice into one body",
			1, countOccurrences(secondBody, "trade_unique_marker"));

		// Drive several more ticks: nothing may be sent, because the buffer is genuinely empty.
		clearBackoff();
		plugin.flushEvents();
		plugin.flushEvents();
		assertNull("no further delivery after success", server.takeRequest(1, TimeUnit.SECONDS));
		assertEquals("exactly 2 HTTP requests total for one event", 2, server.getRequestCount());
	}

	/**
	 * BACKPRESSURE: a long outage must not grow memory, and must keep the NEWEST events.
	 *
	 * <p>Simulates a server that is down while the game keeps generating events. The buffer must settle
	 * at the 500 cap, and the events retained must be the most recent ones — during an incident the
	 * newest activity is the operationally useful part.
	 */
	@Test
	public void sustainedOutageHoldsAtTheCapAndKeepsTheNewestEvents() throws Exception
	{
		for (int i = 0; i < 12; i++)
		{
			server.enqueue(new MockResponse().setResponseCode(503));
		}
		for (int i = 0; i < 480; i++)
		{
			seed("old" + i);
		}
		plugin.flushEvents();
		assertNotNull(server.takeRequest(3, TimeUnit.SECONDS));
		waitFor(() -> buffered() == 480, "batch requeued whole");

		for (int i = 0; i < 200; i++)
		{
			seed("new" + i);	// the game keeps playing during the outage
		}
		synchronized (plugin.pendingEvents)
		{
			assertEquals("buffer must be capped, not unbounded", 500, plugin.pendingEvents.size());
			assertEquals("the NEWEST event must be retained",
				"new199", plugin.pendingEvents.get(499).get("type"));
			assertTrue("the oldest events are the ones dropped",
				String.valueOf(plugin.pendingEvents.get(0).get("type")).startsWith("old"));
		}
	}

	/**
	 * RESTART BEHAVIOUR, pinned as an explicit expectation rather than left implicit.
	 *
	 * <p>Retry is in-memory only. A new plugin instance starts with an empty buffer — buffered and
	 * awaiting-retry events do NOT survive a client restart. This test documents that limit so it cannot
	 * regress silently into a false belief that delivery is durable. See the flushEvents() javadoc.
	 */
	@Test
	public void unsentEventsAreMemoryOnlyAndDoNotSurviveARestart() throws Exception
	{
		seed("will_be_lost");
		assertEquals(1, buffered());

		AccountConnectPlugin restarted = new AccountConnectPlugin();
		synchronized (restarted.pendingEvents)
		{
			assertTrue("a fresh instance has no spool — restart loss is a KNOWN, accepted limit",
				restarted.pendingEvents.isEmpty());
		}
	}

	private static int countOccurrences(String haystack, String needle)
	{
		int n = 0;
		for (int i = haystack.indexOf(needle); i >= 0; i = haystack.indexOf(needle, i + needle.length()))
		{
			n++;
		}
		return n;
	}

	// ---------------------------------------------------------------- helper

	/** OkHttp callbacks land on another thread; poll briefly rather than sleeping a fixed time. */
	private void waitFor(java.util.function.BooleanSupplier cond, String what) throws Exception
	{
		long deadline = System.currentTimeMillis() + 3_000L;
		while (System.currentTimeMillis() < deadline)
		{
			if (cond.getAsBoolean())
			{
				return;
			}
			Thread.sleep(10);
		}
		throw new AssertionError("timed out waiting for: " + what);
	}
}

package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Segmented frame buffering: bounded memory, deterministic ordering, and honest accounting of
 * everything it refused.
 *
 * The property that matters most is the memory bound. The store path's ring keeps a fixed window
 * and is bounded by construction; this buffer must stay bounded while serving a session that runs
 * for minutes, which it does by flushing a segment and starting empty rather than accumulating.
 */
public class DropFrameSegmenterTest
{
	private static final long T0 = 5_000_000L;

	private static byte[] frame(int bytes)
	{
		byte[] b = new byte[bytes];
		b[0] = (byte) 0xff;
		b[1] = (byte) 0xd8;		// JPEG SOI, so the bytes look like what really flows
		return b;
	}

	// ---- segmenting and ordering ----

	@Test
	public void asegmentIsHandedOverExactlyWhenItFills()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(4, 1000, 1_000_000);
		assertNull(seg.add(frame(10), T0));
		assertNull(seg.add(frame(10), T0 + 33));
		assertNull(seg.add(frame(10), T0 + 66));
		DropFrameSegmenter.Segment s = seg.add(frame(10), T0 + 99);
		assertNotNull("the fourth frame completes the segment", s);
		assertEquals(4, s.frameCount());
		assertEquals(0, s.index);
		assertEquals("the segment carries its FIRST frame's time", T0, s.firstFrameMillis);
	}

	@Test
	public void segmentIndexesAreConsecutiveFromZero()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(2, 1000, 1_000_000);
		List<Integer> idx = new ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			DropFrameSegmenter.Segment s = seg.add(frame(10), T0 + i);
			if (s != null)
			{
				idx.add(s.index);
			}
		}
		assertEquals("[0, 1, 2, 3, 4]", idx.toString());
		assertEquals(5, seg.segmentCount());
	}

	/**
	 * The ordering key is the INDEX, not a timestamp. The store path infers chunk order by comparing
	 * captured_at values, which works but cannot survive two chunks sharing a second. A drop clip
	 * must join deterministically, so the index is explicit and monotonic even when the clock does
	 * not move at all.
	 */
	@Test
	public void indexesAreMonotonicEvenWhenTheClockDoesNotMove()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(1, 1000, 1_000_000);
		DropFrameSegmenter.Segment a = seg.add(frame(10), T0);
		DropFrameSegmenter.Segment b = seg.add(frame(10), T0);
		DropFrameSegmenter.Segment c = seg.add(frame(10), T0);
		assertEquals(0, a.index);
		assertEquals(1, b.index);
		assertEquals(2, c.index);
	}

	@Test
	public void framesKeepTheirOrderInsideASegment()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(3, 1000, 1_000_000);
		byte[] f1 = frame(11);
		byte[] f2 = frame(12);
		byte[] f3 = frame(13);
		seg.add(f1, T0);
		seg.add(f2, T0 + 1);
		DropFrameSegmenter.Segment s = seg.add(f3, T0 + 2);
		assertEquals(11, s.frames.get(0).length);
		assertEquals(12, s.frames.get(1).length);
		assertEquals(13, s.frames.get(2).length);
	}

	// ---- the memory bound ----

	/**
	 * THE BOUND. A long session must never hold more than one segment in memory. Ten thousand frames
	 * pass through here; at any moment the buffer holds fewer than segmentFrames.
	 */
	@Test
	public void memoryStaysBoundedAcrossALongSession()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(40, 1_000_000, Long.MAX_VALUE);
		int maxBuffered = 0;
		for (int i = 0; i < 10_000; i++)
		{
			seg.add(frame(30_000), T0 + i);
			maxBuffered = Math.max(maxBuffered, seg.bufferedFrames());
		}
		assertTrue("never more than one segment in memory, saw " + maxBuffered, maxBuffered < 40);
		assertEquals("every frame was accounted for", 10_000, seg.acceptedFrames());
		assertEquals(250, seg.segmentCount());
	}

	@Test
	public void bufferedCountReturnsToZeroAfterEachSegment()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(3, 1000, 1_000_000);
		seg.add(frame(10), T0);
		seg.add(frame(10), T0);
		assertEquals(2, seg.bufferedFrames());
		seg.add(frame(10), T0);
		assertEquals("handing a segment over empties the buffer", 0, seg.bufferedFrames());
	}

	// ---- the tail segment ----

	@Test
	public void flushRemainderHandsOverThePartialSegment()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(4, 1000, 1_000_000);
		seg.add(frame(10), T0);
		seg.add(frame(10), T0 + 1);
		DropFrameSegmenter.Segment tail = seg.flushRemainder();
		assertNotNull(tail);
		assertEquals(2, tail.frameCount());
		assertEquals(0, tail.index);
		assertEquals(1, seg.segmentCount());
	}

	@Test
	public void flushRemainderOnAnEmptyBufferIsNullNotAnEmptySegment()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(2, 1000, 1_000_000);
		seg.add(frame(10), T0);
		seg.add(frame(10), T0);	// exactly fills segment 0
		assertNull("no partial segment to flush", seg.flushRemainder());
		assertEquals("and no phantom segment is counted", 1, seg.segmentCount());
	}

	// ---- refusals, all counted ----

	@Test
	public void nullEmptyAndOversizedFramesAreRefusedAndCounted()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(10, 100, 1_000_000);
		assertNull(seg.add(null, T0));
		assertNull(seg.add(new byte[0], T0));
		assertNull(seg.add(frame(101), T0));
		assertEquals(0, seg.acceptedFrames());
		assertEquals("every refusal is counted, never silently dropped", 3, seg.rejectedFrames());
		assertEquals(0, seg.bufferedFrames());
	}

	/**
	 * The session byte budget keeps what is already captured — the drop is at the START — and stops
	 * taking more. It also RECORDS that it did. A truncated clip that does not say so is a lie about
	 * what happened after the cut.
	 */
	@Test
	public void theSessionBudgetTruncatesAndSaysSo()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(10, 1000, 250);
		for (int i = 0; i < 10; i++)
		{
			seg.add(frame(100), T0 + i);
		}
		assertFalse("the earliest frames are kept", seg.acceptedFrames() == 0);
		assertEquals("only two 100-byte frames fit in a 250-byte budget", 2, seg.acceptedFrames());
		assertTrue("and the truncation is recorded", seg.truncated());
		assertEquals(8, seg.rejectedFrames());
		assertEquals(200L, seg.sessionBytes());
	}

	@Test
	public void anUntruncatedSessionSaysSoToo()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(10, 1000, 1_000_000);
		seg.add(frame(100), T0);
		assertFalse(seg.truncated());
	}

	@Test
	public void sessionBytesCountsOnlyAcceptedFrames()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(10, 50, 1_000_000);
		seg.add(frame(40), T0);
		seg.add(frame(60), T0);		// over the per-frame cap
		assertEquals(40L, seg.sessionBytes());
	}

	@Test
	public void clearDropsTheBufferWithoutTouchingTheSegmentCount()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(4, 1000, 1_000_000);
		seg.add(frame(10), T0);
		seg.add(frame(10), T0);
		seg.clear();
		assertEquals(0, seg.bufferedFrames());
		assertNull(seg.flushRemainder());
	}

	@Test
	public void segmentFramesAreImmutableOnceHandedOut()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(1, 1000, 1_000_000);
		DropFrameSegmenter.Segment s = seg.add(frame(10), T0);
		try
		{
			s.frames.add(frame(10));
			org.junit.Assert.fail("a handed-out segment must not be mutable");
		}
		catch (UnsupportedOperationException expected)
		{
			// correct
		}
	}

	@Test
	public void theDefaultSegmentSizeMatchesTheServersSubrequestBudget()
	{
		// This is HALF of a contract with the server: it writes one R2 object per frame inside one
		// Worker invocation, and a 100-frame chunk was measured dying at 45-49 objects written.
		// Raising this alone silently loses the tail of every segment.
		assertEquals(40, DropFrameSegmenter.SEGMENT_FRAMES);
	}

	// ---- THE RETRY BUFFER: the budget bounds unacknowledged bytes, not the session ----

	/**
	 * THE CHANGE, stated as a test. A session far larger than the budget keeps FULL coverage as long
	 * as the server acknowledges, because an acknowledged segment's bytes are freed.
	 *
	 * This is the arm that was impossible before: the same traffic used to truncate.
	 */
	@Test
	public void aSessionFarLargerThanTheBudgetKeepsEveryFrameWhenUploadsAreAcknowledged()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(4, 1_000, 10_000);
		int frames = 4_000;		// 400,000 bytes of traffic through a 10,000-byte buffer
		int accepted = 0;
		for (int i = 0; i < frames; i++)
		{
			DropFrameSegmenter.Segment full = seg.add(new byte[100], 1_000L + i);
			accepted++;
			if (full != null)
			{
				seg.segmentAcknowledged(full.index);	// the server answered
			}
		}
		assertEquals("every frame accepted", frames, accepted);
		assertEquals("nothing refused", 0, seg.rejectedFrames());
		assertFalse("and the session is NOT truncated", seg.truncated());
		assertTrue("peak held " + seg.peakHeldBytes() + " stayed inside the buffer",
			seg.peakHeldBytes() <= 10_000);
	}

	/**
	 * THE KNOWN-BAD CONTROL for that arm. With NO acknowledgement the same traffic must truncate,
	 * because the retry buffer is the only thing holding those bytes. A budget that never fills
	 * would mean the guard is gone rather than repurposed.
	 */
	@Test
	public void theSameSessionWithNoAcknowledgementStillTruncates()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(4, 1_000, 10_000);
		for (int i = 0; i < 4_000; i++)
		{
			seg.add(new byte[100], 1_000L + i);
		}
		assertTrue("an unacknowledged session fills the buffer and truncates", seg.truncated());
		assertTrue("and says how much it refused", seg.rejectedFrames() > 0);
	}

	/** An acknowledgement frees exactly that segment's bytes, and only once. */
	@Test
	public void acknowledgementIsIdempotent()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(2, 1_000, 10_000);
		DropFrameSegmenter.Segment one = null;
		for (int i = 0; i < 2; i++)
		{
			DropFrameSegmenter.Segment f = seg.add(new byte[100], 1_000L + i);
			if (f != null)
			{
				one = f;
			}
		}
		assertEquals(200L, seg.heldBytes());
		seg.segmentAcknowledged(one.index);
		assertEquals(0L, seg.heldBytes());
		seg.segmentAcknowledged(one.index);
		assertEquals("a duplicate acknowledgement frees nothing twice", 0L, seg.heldBytes());
		assertEquals(0, seg.unsettledSegments());
	}

	/**
	 * A segment that will never be sent releases its bytes too.
	 *
	 * Holding them would let one dead segment permanently shrink the buffer, so a handful of
	 * failures early in a long session would strangle capture for the rest of it. The segment is
	 * still LOST and still counted as failed by the caller; freeing memory does not hide that.
	 */
	@Test
	public void anAbandonedSegmentReleasesItsBytes()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(2, 1_000, 10_000);
		DropFrameSegmenter.Segment one = null;
		for (int i = 0; i < 2; i++)
		{
			DropFrameSegmenter.Segment f = seg.add(new byte[100], 1_000L + i);
			if (f != null)
			{
				one = f;
			}
		}
		seg.segmentAbandoned(one.index);
		assertEquals(0L, seg.heldBytes());
	}

	/**
	 * INTERRUPTION AND RETRY: segments acknowledged LATE and OUT OF ORDER lose nothing and reorder
	 * nothing.
	 *
	 * A retry arrives whenever the network lets it, so acknowledgements are not ordered. The index
	 * is the ordering key and it is assigned when the segment is cut, so the order a segment is
	 * acknowledged in cannot affect where it sits in the session.
	 */
	@Test
	public void outOfOrderAcknowledgementLosesNothingAndReordersNothing()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(2, 1_000, 1_000_000);
		java.util.List<DropFrameSegmenter.Segment> cut = new java.util.ArrayList<>();
		for (int i = 0; i < 20; i++)
		{
			DropFrameSegmenter.Segment f = seg.add(new byte[100], 1_000L + i);
			if (f != null)
			{
				cut.add(f);
			}
		}
		assertEquals(10, cut.size());
		for (int i = 0; i < cut.size(); i++)
		{
			assertEquals("index is assigned at cut time, in order", i, cut.get(i).index);
		}
		// Acknowledge backwards, the shape a retry storm produces.
		for (int i = cut.size() - 1; i >= 0; i--)
		{
			seg.segmentAcknowledged(cut.get(i).index);
		}
		assertEquals("every segment settled", 0, seg.unsettledSegments());
		assertEquals(0L, seg.heldBytes());
		assertEquals("and the session still declares all ten", 10, seg.segmentCount());
		for (int i = 0; i < cut.size(); i++)
		{
			assertEquals("indexes are unchanged by acknowledgement order", i, cut.get(i).index);
		}
	}

	/**
	 * A STALLED upload recovers. The buffer fills, capture truncates, and once acknowledgements
	 * resume the client captures again rather than staying dead for the rest of the session.
	 */
	@Test
	public void captureResumesAfterTheBufferDrains()
	{
		DropFrameSegmenter seg = new DropFrameSegmenter(2, 1_000, 500);
		java.util.List<DropFrameSegmenter.Segment> stalled = new java.util.ArrayList<>();
		for (int i = 0; i < 20; i++)
		{
			DropFrameSegmenter.Segment f = seg.add(new byte[100], 1_000L + i);
			if (f != null)
			{
				stalled.add(f);		// the server is not answering
			}
		}
		assertTrue("the buffer filled", seg.truncated());
		int refusedWhileStalled = seg.rejectedFrames();
		assertTrue(refusedWhileStalled > 0);

		for (DropFrameSegmenter.Segment s : stalled)
		{
			seg.segmentAcknowledged(s.index);
		}
		int acceptedBefore = seg.acceptedFrames();
		for (int i = 0; i < 4; i++)
		{
			seg.add(new byte[100], 2_000L + i);
		}
		assertTrue("capture resumes once the buffer drains",
			seg.acceptedFrames() > acceptedBefore);
		assertTrue("and the session stays marked truncated, because frames WERE lost",
			seg.truncated());
	}

	/**
	 * A TWENTY-MINUTE SESSION at the real rate, with real segment sizes, holds bounded memory.
	 *
	 * 6fps for 20 minutes at the measured 39,073 bytes a frame is 7,200 frames and about 281MB of
	 * traffic. The client must never hold more than the buffer, and must lose nothing.
	 */
	@Test
	public void aTwentyMinuteSessionHoldsBoundedMemoryAndLosesNothing()
	{
		final int frameBytes = 39_073;
		final int frames = DropCaptureRate.BASELINE_FPS * 60 * 20;
		DropFrameSegmenter seg = new DropFrameSegmenter();
		for (int i = 0; i < frames; i++)
		{
			DropFrameSegmenter.Segment full = seg.add(new byte[frameBytes], 1_000L + i);
			if (full != null)
			{
				seg.segmentAcknowledged(full.index);
			}
		}
		assertEquals("every frame kept", frames, seg.acceptedFrames());
		assertEquals("nothing refused", 0, seg.rejectedFrames());
		assertFalse("not truncated", seg.truncated());
		long traffic = (long) frames * frameBytes;
		assertTrue("uploaded " + (traffic / 1_000_000) + "MB over the session",
			traffic > 250_000_000L);
		assertTrue("but never held more than " + (seg.peakHeldBytes() / 1_000_000) + "MB at once",
			seg.peakHeldBytes() <= (long) DropFrameSegmenter.SEGMENT_FRAMES * frameBytes * 2);
	}

	/** The budget constant is the operator's 72MB, unchanged, now bounding the retry buffer. */
	@Test
	public void theBufferBudgetIsTheOperatorsSeventyTwoMegabytes()
	{
		assertEquals(72_000_000L, DropFrameSegmenter.UNACKED_BYTE_BUDGET);
	}
}

package com.osrsbestinslot.export;

import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Adaptive capture: 8fps continuous, 30fps around the moments, and a lookbehind so the two seconds
 * BEFORE a removal survive.
 *
 * The acceptance property the operator set is coverage, not frame count: zero missing time from the
 * first Drop through five seconds after the last pile disappears. So the arms here measure GAPS
 * between kept frames, not how many frames were kept.
 */
public class DropCaptureRateTest
{
	private static final long T0 = 1_000_000L;
	/** One sampled frame at 30fps. */
	private static final long STEP = 1000L / DropCaptureRate.SAMPLE_FPS;
	/** Measured live, 2026-09-20: 71,972,119 bytes over 1,842 kept frames. Not a rounded guess. */
	private static final long MEASURED_FRAME_BYTES = 39_073L;

	private static byte[] frame(int n)
	{
		return new byte[]{(byte) 0xff, (byte) 0xd8, (byte) n};
	}

	// ---- the baseline ----

	@Test
	public void theBaselineKeepsSixFramesPerSecond()
	{
		DropCaptureRate r = new DropCaptureRate();
		for (int i = 0; i < DropCaptureRate.SAMPLE_FPS; i++)
		{
			r.offer(frame(i), T0 + i * STEP);
		}
		assertEquals("6 of every 30 sampled frames", 6, r.keptBaseline());
	}

	@Test
	public void theBaselineCadenceIsSteadyNotBursty()
	{
		// A drifting cadence would clump keeps together and leave a long gap, which is exactly the
		// "missing time" the operator refused. The longest gap must stay near 1/8s.
		DropCaptureRate r = new DropCaptureRate();
		long last = -1;
		long worstGap = 0;
		for (int i = 0; i < DropCaptureRate.SAMPLE_FPS * 4; i++)
		{
			long now = T0 + i * STEP;
			if (r.offer(frame(i), now) == DropCaptureRate.Decision.KEEP)
			{
				if (last >= 0)
				{
					worstGap = Math.max(worstGap, now - last);
				}
				last = now;
			}
		}
		assertTrue("longest baseline gap was " + worstGap + "ms, expected <= 167ms", worstGap <= 167);
	}

	// ---- bursts ----

	@Test
	public void anEventKeepsEveryFrameForTwoSeconds()
	{
		DropCaptureRate r = new DropCaptureRate();
		r.onEvent(DropCaptureRate.Event.PILE_REMOVED, T0);
		int kept = 0;
		for (int i = 0; i < 60; i++)		// 2 seconds at 30fps
		{
			if (r.offer(frame(i), T0 + i * STEP) == DropCaptureRate.Decision.KEEP)
			{
				kept++;
			}
		}
		assertEquals("every frame in the post-roll", 60, kept);
	}

	@Test
	public void theBurstEndsAndTheBaselineResumes()
	{
		DropCaptureRate r = new DropCaptureRate();
		r.onEvent(DropCaptureRate.Event.DROP_ACTION, T0);
		assertTrue(r.bursting(T0 + 1_999));
		assertFalse("2s is the end of the post-roll", r.bursting(T0 + 2_000));

		int kept = 0;
		for (int i = 0; i < DropCaptureRate.SAMPLE_FPS; i++)
		{
			if (r.offer(frame(i), T0 + 3_000 + i * STEP) == DropCaptureRate.Decision.KEEP)
			{
				kept++;
			}
		}
		assertEquals("back to the baseline", 6, kept);
	}

	/**
	 * THE LOOKBEHIND, and the reason this class exists. Two seconds before a removal cannot be
	 * chosen when the removal happens, because those frames are already past. They are held.
	 */
	@Test
	public void theTwoSecondsBeforeAnEventAreRecoveredFromThePreRoll()
	{
		DropCaptureRate r = new DropCaptureRate();
		// 2 seconds of quiet baseline at 30fps: 60 sampled, the baseline keeps 2 x BASELINE_FPS of
		// them, and every remaining frame is held rather than discarded.
		for (int i = 0; i < 60; i++)
		{
			r.offer(frame(i), T0 + i * STEP);
		}
		long eventAt = T0 + 60 * STEP;
		r.onEvent(DropCaptureRate.Event.PILE_REMOVED, eventAt);
		List<byte[]> pre = r.claimPreRoll(eventAt);
		int held = 60 - 2 * DropCaptureRate.BASELINE_FPS;
		assertEquals("every frame the baseline skipped in the last 2s is recovered",
			held, pre.size());
		assertEquals("and nothing was genuinely discarded", 0, r.discarded());
	}

	@Test
	public void thePreRollForgetsAnythingOlderThanItsWindow()
	{
		// The bound on this class's memory. A ten-second quiet stretch must not hold ten seconds.
		DropCaptureRate r = new DropCaptureRate();
		for (int i = 0; i < DropCaptureRate.SAMPLE_FPS * 10; i++)
		{
			r.offer(frame(i), T0 + i * STEP);
		}
		assertTrue("pre-roll held " + r.preRollSize() + " frames, expected under 2s worth",
			r.preRollSize() <= 60);
		assertTrue("and the old ones really were discarded", r.discarded() > 0);
	}

	@Test
	public void claimingAnEmptyPreRollIsSafe()
	{
		DropCaptureRate r = new DropCaptureRate();
		r.onEvent(DropCaptureRate.Event.DROP_ACTION, T0);
		assertTrue(r.claimPreRoll(T0).isEmpty());
	}

	// ---- rapid multi-drop ----

	/**
	 * Four drops a second apart must produce ONE continuous high-rate stretch. Restarting the burst
	 * each time would be correct too, but counting four separate bursts would misreport the clip.
	 */
	@Test
	public void rapidDropsExtendOneBurstRatherThanStackingFour()
	{
		DropCaptureRate r = new DropCaptureRate();
		for (int i = 0; i < 4; i++)
		{
			r.onEvent(DropCaptureRate.Event.DROP_ACTION, T0 + i * 1_000L);
		}
		assertEquals("one continuous burst", 1, r.bursts());
		assertTrue("still bursting 2s after the LAST drop", r.bursting(T0 + 3_000 + 1_999));
		assertFalse(r.bursting(T0 + 3_000 + 2_000));
	}

	@Test
	public void twoWidelySeparatedEventsAreTwoBursts()
	{
		DropCaptureRate r = new DropCaptureRate();
		r.onEvent(DropCaptureRate.Event.DROP_ACTION, T0);
		r.onEvent(DropCaptureRate.Event.PILE_REMOVED, T0 + 60_000);
		assertEquals(2, r.bursts());
	}

	// ---- COVERAGE: the operator's acceptance property ----

	/**
	 * THE ACCEPTANCE TEST, rewritten after it passed while the LIVE run failed.
	 *
	 * The first version modelled two bursts. The real 197-second session fired FOUR, totalling 13
	 * seconds at 30fps, and at an 8fps baseline it needed 73.8MB against a 72MB budget. It truncated
	 * the last 6 seconds, which is the tail. So this test now drives the measured shape: the drop,
	 * the spawn, the second drop, the removals, and the sizing uses the MEASURED per-frame size of
	 * 39,073 bytes rather than a rounded guess.
	 *
	 * The operator's acceptance property is coverage, not frame count: zero missing time from the
	 * first Drop through five seconds after the last pile disappears.
	 */
	@Test
	public void aTwoHundredSecondSessionHasNoMissingTime()
	{
		DropCaptureRate r = new DropCaptureRate();
		final long sessionMillis = 197_000L + DropSessionRecorder.TAIL_MILLIS;
		final int samples = (int) (sessionMillis / STEP);

		// The four moments the live run actually produced, spread so none merges into another.
		final long[] events = {0L, 3_000L, 196_000L, 197_000L};
		int nextEvent = 0;

		long last = -1;
		long worstGap = 0;
		int kept = 0;
		for (int i = 0; i < samples; i++)
		{
			long now = T0 + i * STEP;
			if (nextEvent < events.length && now >= T0 + events[nextEvent])
			{
				r.onEvent(DropCaptureRate.Event.PILE_REMOVED, now);
				kept += r.claimPreRoll(now).size();
				nextEvent++;
			}
			if (r.offer(frame(i), now) == DropCaptureRate.Decision.KEEP)
			{
				if (last >= 0)
				{
					worstGap = Math.max(worstGap, now - last);
				}
				last = now;
				kept++;
			}
		}
		assertEquals("all four moments fired", events.length, nextEvent);
		assertTrue("worst gap in coverage was " + worstGap + "ms; a baseline period is 167ms",
			worstGap <= 200);
		assertTrue("coverage runs to the end of the tail, last frame at "
			+ (last - T0) + "ms of " + sessionMillis, last >= T0 + sessionMillis - 200);

		// SIZE IS NO LONGER A COVERAGE QUESTION. The budget is a retry buffer, freed on each
		// acknowledgement, so a session of any length keeps full coverage while uploads work. What
		// the rate still decides is cost, so that is what is checked here.
		long bytes = (long) kept * MEASURED_FRAME_BYTES;
		assertTrue("197s of footage is " + (bytes / 1_000_000) + "MB uploaded", bytes > 0);
	}

	/**
	 * THE KNOWN-BAD CONTROL for the rate. The old 8fps baseline costs materially more for the same
	 * session, which is the reason the rate stayed at 6 after the budget stopped capping sessions.
	 * Reverting BASELINE_FPS to 8 turns this test red.
	 */
	@Test
	public void theOldEightFpsBaselineCostsMoreForTheSameSession()
	{
		long six = sessionBytesAtBaseline(DropCaptureRate.BASELINE_FPS);
		long eight = sessionBytesAtBaseline(8);
		assertTrue("6fps is " + (six / 1_000_000) + "MB and 8fps is " + (eight / 1_000_000)
			+ "MB for the same 197-second session", eight > six);
		assertEquals("and the configured rate is the cheaper one", 6, DropCaptureRate.BASELINE_FPS);
	}

	/**
	 * The comparison that justifies adaptive capture at all. The same session at a flat 30fps costs
	 * several times what the adaptive rate costs, which is what was measured live before this
	 * change: 1,814 frames kept and 4,058 dropped at a hard cap.
	 */
	@Test
	public void aFlatThirtyFpsCostsSeveralTimesTheAdaptiveRate()
	{
		long adaptive = sessionBytesAtBaseline(DropCaptureRate.BASELINE_FPS);
		long flat = ((197_000L + DropSessionRecorder.TAIL_MILLIS) / STEP) * MEASURED_FRAME_BYTES;
		assertTrue("flat 30fps is " + (flat / 1_000_000) + "MB against the adaptive "
			+ (adaptive / 1_000_000) + "MB", flat > adaptive * 3);
	}

	/**
	 * THE RETRY BUFFER HAS REAL HEADROOM AT THIS RATE.
	 *
	 * The buffer only fills when the server stops acknowledging. This measures how long a total
	 * upload outage a client can absorb before it must truncate. At 6fps that is minutes, not
	 * seconds, which is what makes truncation mean "the network died" rather than "the trade took a
	 * while".
	 */
	@Test
	public void theRetryBufferAbsorbsMinutesOfTotalUploadOutage()
	{
		long perSecond = DropCaptureRate.baselineBytesPerSecond(
			DropCaptureRate.BASELINE_FPS, (int) MEASURED_FRAME_BYTES);
		long outageSeconds = DropFrameSegmenter.UNACKED_BYTE_BUDGET / perSecond;
		assertTrue("a total upload outage of " + outageSeconds + "s is absorbed; expected over 120",
			outageSeconds > 120);
	}

	@Test
	public void theBaselineSizingIsCheckedNotAsserted()
	{
		long perSecond = DropCaptureRate.baselineBytesPerSecond(DropCaptureRate.BASELINE_FPS, 40_000);
		assertEquals(240_000L, perSecond);
	}

	/** Frames an adaptive session of the measured shape keeps at a given baseline rate. */
	private static long sessionBytesAtBaseline(int baselineFps)
	{
		DropCaptureRate r = new DropCaptureRate(baselineFps, DropCaptureRate.PRE_ROLL_MILLIS,
			DropCaptureRate.POST_ROLL_MILLIS);
		final long sessionMillis = 197_000L + DropSessionRecorder.TAIL_MILLIS;
		final int samples = (int) (sessionMillis / STEP);
		final long[] events = {0L, 3_000L, 196_000L, 197_000L};
		int nextEvent = 0;
		int kept = 0;
		for (int i = 0; i < samples; i++)
		{
			long now = T0 + i * STEP;
			if (nextEvent < events.length && now >= T0 + events[nextEvent])
			{
				r.onEvent(DropCaptureRate.Event.PILE_REMOVED, now);
				kept += r.claimPreRoll(now).size();
				nextEvent++;
			}
			if (r.offer(frame(i), now) == DropCaptureRate.Decision.KEEP)
			{
				kept++;
			}
		}
		return (long) kept * MEASURED_FRAME_BYTES;
	}

	@Test
	public void theConfiguredRatesAreTheOnesTheOperatorChose()
	{
		assertEquals(6, DropCaptureRate.BASELINE_FPS);
		assertEquals(30, DropCaptureRate.SAMPLE_FPS);
		assertEquals(2_000L, DropCaptureRate.PRE_ROLL_MILLIS);
		assertEquals(2_000L, DropCaptureRate.POST_ROLL_MILLIS);
	}

	@Test
	public void anInvalidBaselineIsRefusedRatherThanClamped()
	{
		for (int bad : new int[]{0, -1, 31})
		{
			try
			{
				new DropCaptureRate(bad, 2_000L, 2_000L);
				org.junit.Assert.fail("baseline " + bad + " must be refused");
			}
			catch (IllegalArgumentException expected)
			{
				// correct
			}
		}
	}
}

