package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Event volume bounds for the always-on capture events. The server event ingest has a global row ceiling,
 * and a 429 over it stops every event type for every user, so these events must stay coarse:
 * equip_change fires only when the SET of worn ids changes (never per ammo shot), xp_gain flushes at most
 * every 5 minutes plus once at session end, and the first bank open with an unloaded bank never reports
 * the whole bank as deposited.
 */
public class CaptureVolumeTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int WORN = net.runelite.api.gameval.InventoryID.WORN;
	private static final int BANK = net.runelite.api.gameval.InventoryID.BANK;
	private static final int BANK_GROUP = 12;	// InterfaceID.BANKMAIN
	private static final int TICKS_PER_HOUR = 6000;	// 0.6s per tick

	private static AccountConnectPlugin plug() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		});
		return p;
	}

	private static ItemContainer container(int[]... items)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] a = new Item[items.length];
		for (int i = 0; i < items.length; i++)
		{
			a[i] = new Item(items[i][0], items[i][1]);
		}
		when(c.getItems()).thenReturn(a);
		return c;
	}

	private static List<Map<String, Object>> ofType(AccountConnectPlugin p, String type)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		for (Map<String, Object> ev : p.pendingEvents)
		{
			if (type.equals(ev.get("type")))
			{
				out.add(ev);
			}
		}
		return out;
	}

	// ---- equip_change ----

	private static final int BOW = 861;		// magic shortbow
	private static final int ARROW = 892;	// rune arrow
	private static final int HELM = 1163;

	@Test
	public void hundredAmmoShotsEmitNoEquipChange() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{BOW, 1}, new int[]{ARROW, 500})));	// baseline
		for (int left = 499; left >= 400; left--)
		{
			p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{BOW, 1}, new int[]{ARROW, left})));
		}
		assertEquals("ammo spent while still worn is not an equipment change", 0, ofType(p, "equip_change").size());
	}

	@Test
	public void weaponSwapEmitsExactlyOneEquipChange() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{HELM, 1}, new int[]{BOW, 1}, new int[]{ARROW, 500})));
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{HELM, 1}, new int[]{ARROW, 499})));	// shot, then bow off
		assertEquals(1, ofType(p, "equip_change").size());	// the unequip of the bow
		p.pendingEvents.clear();

		// swap: whip on in the same slot, arrows also spent in the same change
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{HELM, 1}, new int[]{4151, 1}, new int[]{ARROW, 498})));
		List<Map<String, Object>> evs = ofType(p, "equip_change");
		assertEquals(1, evs.size());
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> equipped = (List<Map<String, Object>>) evs.get(0).get("equipped");
		assertEquals(1, equipped.size());
		assertEquals(4151, equipped.get(0).get("id"));
		assertNull("a quantity change of a still-worn id is not reported", evs.get(0).get("unequipped"));
	}

	@Test
	public void weaponReplacedInSlotEmitsOneEventWithBothSides() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{BOW, 1}, new int[]{ARROW, 500})));
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{4151, 1}, new int[]{ARROW, 500})));
		List<Map<String, Object>> evs = ofType(p, "equip_change");
		assertEquals(1, evs.size());
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> un = (List<Map<String, Object>>) evs.get(0).get("unequipped");
		assertEquals(1, un.size());
		assertEquals(BOW, un.get(0).get("id"));
	}

	@Test
	public void unequipEmitsExactlyOneEquipChange() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{BOW, 1}, new int[]{ARROW, 500})));
		p.onItemContainerChanged(new ItemContainerChanged(WORN, container(new int[]{BOW, 1})));	// quiver emptied / arrows removed
		List<Map<String, Object>> evs = ofType(p, "equip_change");
		assertEquals(1, evs.size());
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> un = (List<Map<String, Object>>) evs.get(0).get("unequipped");
		assertEquals(ARROW, un.get(0).get("id"));
		assertEquals(500L, un.get(0).get("qty"));
	}

	// ---- xp_gain ----

	@Test
	public void oneHourOfTrainingFlushesAtMostThirteenTimesAndLosesNoXp() throws Exception
	{
		AccountConnectPlugin p = plug();
		int xp = 1_000_000;
		p.onStatChanged(new StatChanged(Skill.WOODCUTTING, xp, 80, 80));	// baseline
		long gained = 0;
		for (int t = 0; t < TICKS_PER_HOUR; t++)
		{
			if (t % 4 == 0)		// one log every 4 ticks, 175 xp each
			{
				xp += 175;
				gained += 175;
				p.onStatChanged(new StatChanged(Skill.WOODCUTTING, xp, 80, 80));
			}
			p.onGameTick(new GameTick());
		}
		// a few ticks of extra xp after the last timed flush, then logout
		xp += 175;
		gained += 175;
		p.onStatChanged(new StatChanged(Skill.WOODCUTTING, xp, 80, 80));
		int beforeLogout = ofType(p, "xp_gain").size();
		assertTrue("timed flushes in one hour: " + beforeLogout, beforeLogout <= 12);

		p.onGameStateChanged(gameState(GameState.LOGIN_SCREEN));
		List<Map<String, Object>> evs = ofType(p, "xp_gain");
		assertEquals("logout flushes the rest", beforeLogout + 1, evs.size());
		assertTrue("flushes for the hour including logout: " + evs.size(), evs.size() <= 13);
		assertEquals("sum of xp in events == xp gained", gained, sumXp(evs, "Woodcutting"));
	}

	@Test
	public void worldHopFlushesAccumulatedXp() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.onStatChanged(new StatChanged(Skill.FISHING, 5000, 40, 40));
		p.onStatChanged(new StatChanged(Skill.FISHING, 5100, 40, 40));
		p.onGameTick(new GameTick());
		assertEquals("no flush before 5 minutes", 0, ofType(p, "xp_gain").size());
		p.onGameStateChanged(gameState(GameState.HOPPING));
		List<Map<String, Object>> evs = ofType(p, "xp_gain");
		assertEquals(1, evs.size());
		assertEquals(100L, sumXp(evs, "Fishing"));
	}

	private static long sumXp(List<Map<String, Object>> evs, String skill)
	{
		long sum = 0;
		for (Map<String, Object> ev : evs)
		{
			@SuppressWarnings("unchecked")
			List<Map<String, Object>> gains = (List<Map<String, Object>>) ev.get("gains");
			for (Map<String, Object> g : gains)
			{
				if (skill.equals(g.get("skill")))
				{
					sum += (Long) g.get("xp");
				}
			}
		}
		return sum;
	}

	private static GameStateChanged gameState(GameState s)
	{
		GameStateChanged e = new GameStateChanged();
		e.setGameState(s);
		return e;
	}

	// ---- bank first open ----

	private static AccountConnectPlugin bankPlugin(Client client) throws Exception
	{
		AccountConnectPlugin p = plug();
		inject(p, "client", client);
		return p;
	}

	@Test
	public void firstOpenWithUnloadedBankEmitsNoDeposit() throws Exception
	{
		Client client = mock(Client.class);
		AccountConnectPlugin p = bankPlugin(client);
		ItemContainer full = container(new int[]{995, 1_000_000}, new int[]{20997, 1}, new int[]{385, 200});
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(null);	// unloaded at open
		p.handleCaptureOnOpenWidgetLoaded(BANK_GROUP);
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(full);
		p.onItemContainerChanged(new ItemContainerChanged(BANK, full));	// contents arrive = baseline only
		p.handleBankWidgetClosed(BANK_GROUP);
		assertEquals("the first contents are a baseline, never a whole-bank deposit", 0, ofType(p, "bank_session").size());
	}

	@Test
	public void firstOpenWithEmptyBankContainerEmitsNoDepositThenDiffsNextChange() throws Exception
	{
		Client client = mock(Client.class);
		AccountConnectPlugin p = bankPlugin(client);
		ItemContainer empty = container();
		ItemContainer full = container(new int[]{995, 1_000_000}, new int[]{20997, 1});
		ItemContainer plusSharks = container(new int[]{995, 1_000_000}, new int[]{20997, 1}, new int[]{385, 50});
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(empty);	// empty at open
		p.handleCaptureOnOpenWidgetLoaded(BANK_GROUP);
		p.onItemContainerChanged(new ItemContainerChanged(BANK, full));	// baseline
		p.onItemContainerChanged(new ItemContainerChanged(BANK, plusSharks));	// the real deposit
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(plusSharks);
		p.handleBankWidgetClosed(BANK_GROUP);
		List<Map<String, Object>> sess = ofType(p, "bank_session");
		assertEquals(1, sess.size());
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> items = (List<Map<String, Object>>) sess.get(0).get("deposited");
		assertEquals("only the real deposit, never the whole bank", 1, items.size());
		assertEquals(385, items.get(0).get("id"));
		assertEquals(50L, items.get(0).get("qty"));
		assertTrue(((List<?>) sess.get(0).get("withdrawn")).isEmpty());
	}

	@Test
	public void bankThatNeverLoadsEmitsNothingOnClose() throws Exception
	{
		Client client = mock(Client.class);
		AccountConnectPlugin p = bankPlugin(client);
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(null);
		p.handleCaptureOnOpenWidgetLoaded(BANK_GROUP);
		ItemContainer full = container(new int[]{995, 1_000_000});
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(full);	// readable only at close
		p.handleBankWidgetClosed(BANK_GROUP);
		assertTrue(p.pendingEvents.isEmpty());
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.io.File;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

/**
 * Drift gate for the PLUGIN_VERSION constant. The plugin stamps PLUGIN_VERSION into every snapshot's
 * source.plugin_version, which is how osrsbestinslot.com tells which build an account is running. That
 * constant and build.gradle's project version are two hand-edited places, so they can silently diverge
 * (they did: the constant was "0.5.0" while the build shipped 0.6.0). This test parses build.gradle's
 * version and asserts the constant equals it, turning any future drift into a build failure — you can
 * no longer bump one without the other. It fails loud (not silently) if build.gradle can't be found or
 * the version line can't be uniquely located.
 */
public class VersionDriftTest
{
	@Test
	public void pluginVersionConstantMatchesBuildGradle() throws Exception
	{
		String buildVersion = parseBuildGradleVersion();
		String pluginVersion = readPluginVersionConstant();
		assertEquals(
			"PLUGIN_VERSION must equal build.gradle's version — bump both together",
			buildVersion, pluginVersion);
	}

	/** Read the private static final PLUGIN_VERSION reflectively (no need to widen production visibility). */
	private static String readPluginVersionConstant() throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("PLUGIN_VERSION");
		f.setAccessible(true);
		Object value = f.get(null);
		assertNotNull("PLUGIN_VERSION must be set", value);
		return (String) value;
	}

	/**
	 * Extract the single top-level {@code version = '...'} assignment from build.gradle. Case-sensitive
	 * and line-anchored on purpose: it must not match {@code def runeLiteVersion = 'latest.release'}
	 * (capital V) nor a dependency map's {@code version: runeLiteVersion} (colon, unquoted). Fails if the
	 * file is missing or the assignment is absent / ambiguous, so the gate can never pass vacuously.
	 */
	private static String parseBuildGradleVersion() throws Exception
	{
		File gradle = locateBuildGradle();
		String text = new String(Files.readAllBytes(gradle.toPath()), StandardCharsets.UTF_8);
		Pattern p = Pattern.compile("(?m)^\\s*version\\s*=\\s*['\"]([^'\"]+)['\"]\\s*$");
		Matcher m = p.matcher(text);
		String found = null;
		int count = 0;
		while (m.find())
		{
			found = m.group(1);
			count++;
		}
		assertEquals("expected exactly one top-level version assignment in build.gradle", 1, count);
		return found;
	}

	/** build.gradle lives at the module root = the gradle test working directory; probe the usual spots. */
	private static File locateBuildGradle()
	{
		File[] candidates = {
			new File("build.gradle"),
			new File(System.getProperty("user.dir"), "build.gradle"),
		};
		for (File f : candidates)
		{
			if (f.isFile())
			{
				return f;
			}
		}
		fail("could not locate build.gradle (cwd=" + System.getProperty("user.dir") + ")");
		return null; // unreachable — fail() throws
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.Dispatcher;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * PRODUCTION-EQUIVALENT INGEST CONTRACT — opt-in, network-dependent.
 *
 * <p>Everything else in this suite runs against a local MockWebServer. This class additionally checks
 * the payload the plugin actually builds against the REAL production ingest endpoint, because a locally
 * green test proves the client is self-consistent, not that the server accepts what it emits.
 *
 * <p><b>It writes nothing.</b> The token used is a syntactically valid but unowned 32-hex string, so
 * production replies {@code {"ok":true,"stored":0}} — the request is parsed and accepted, and zero rows
 * are persisted. That is exactly the signal wanted: schema acceptance without touching customer data.
 *
 * <p>Skipped unless {@code -DrunProdContract=true}, so the normal offline build stays hermetic and CI
 * never depends on the network.
 */
public class ProductionIngestContractTest
{
	private static final String PROD = "https://www.osrsbestinslot.com/wp-json/osrsbis/v1";
	/** Valid shape, owned by nobody → parsed and accepted, stored:0. */
	private static final String UNOWNED_TOKEN = "0123456789abcdef0123456789abcdef";

	private AccountConnectPlugin plugin;
	private MockWebServer proxy;

	/**
	 * Opt-in switch. Reads an ENV VAR, not a system property: Gradle forks the test JVM and does not
	 * forward {@code -D} flags to it unless build.gradle explicitly wires them, so a system-property
	 * gate silently evaluated false and these tests reported PASS in 0.376s without executing a single
	 * assertion — a false green, which is worse than no test. Env vars are inherited by the fork.
	 */
	private static boolean enabled()
	{
		return "true".equals(System.getenv("RUN_PROD_CONTRACT"));
	}

	/** Fails loudly if an enabled run somehow skips, so a silent no-op can never look like a pass again. */
	private static void requireEnabled()
	{
		if (!enabled())
		{
			throw new IllegalStateException("prod contract test ran without RUN_PROD_CONTRACT=true");
		}
	}

	@Before
	public void setUp() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient.Builder()
			.connectTimeout(10, TimeUnit.SECONDS)
			.readTimeout(10, TimeUnit.SECONDS)
			.build());
	}

	@After
	public void tearDown() throws Exception
	{
		if (proxy != null)
		{
			proxy.shutdown();
		}
	}

	private void inject(String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private void pointAt(String baseUrl)
	{
		AccountConnectConfig config = mock(AccountConnectConfig.class);
		when(config.linkToken()).thenReturn(UNOWNED_TOKEN);
		when(config.apiBaseUrl()).thenReturn(baseUrl);
		try
		{
			inject("config", config);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	private void seed(String type, Map<String, Object> fields)
	{
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", type);
		ev.put("ts", System.currentTimeMillis());
		ev.putAll(fields);
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}
	}

	/**
	 * The 0.7.4 trade payload — counterparty + itemised received[] — is ACCEPTED by production.
	 *
	 * <p>This is the schema half of the trade validation. It proves the server takes the new fields
	 * (which it does opaquely: `fields` is stored as a JSON blob, so no server change is needed). It does
	 * NOT prove the widget read works in a live client — only a genuine two-sided in-game trade can, and
	 * that is recorded as a separate manual step.
	 */
	@Test
	public void productionAcceptsTheNew074TradePayload() throws Exception
	{
		if (!enabled())
		{
			return;
		}
		requireEnabled();
		pointAt(PROD);
		Map<String, Object> fields = new LinkedHashMap<>();
		List<Map<String, Object>> given = new ArrayList<>();
		Map<String, Object> g = new LinkedHashMap<>();
		g.put("id", 995);
		g.put("qty", 1_000_000);
		given.add(g);
		List<Map<String, Object>> received = new ArrayList<>();
		Map<String, Object> r = new LinkedHashMap<>();
		r.put("id", 4151);
		r.put("qty", 1);
		received.add(r);
		fields.put("given", given);
		fields.put("received", received);		// 0.7.4: itemised, was always []
		fields.put("counterparty", "ZZZ_CONTRACT_TEST");	// 0.7.4: was never present
		seed("trade", fields);

		plugin.flushEvents();
		Thread.sleep(4000);

		synchronized (plugin.pendingEvents)
		{
			assertTrue("a 2xx from production must drain the buffer — if this fails the payload was "
				+ "rejected and requeued", plugin.pendingEvents.isEmpty());
		}
		assertEquals("a successful delivery resets the backoff ladder", 0L, plugin.eventRetryBackoffMs);
	}

	/**
	 * The 0.7.4 store payload with an exact gp_total and NO unit_price_gp (the merged-quantity case) is
	 * accepted by production.
	 */
	@Test
	public void productionAcceptsTheMergedStorePayload() throws Exception
	{
		if (!enabled())
		{
			return;
		}
		requireEnabled();
		pointAt(PROD);
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", 453, 20, 1_000_000L, 998_000L, false, true);
		assertEquals(2_000L, fields.get("gp_total"));
		assertTrue("merged qty must carry no unit price", !fields.containsKey("unit_price_gp"));
		seed("store_buy", fields);

		plugin.flushEvents();
		Thread.sleep(4000);

		synchronized (plugin.pendingEvents)
		{
			assertTrue("production must accept the merged store payload", plugin.pendingEvents.isEmpty());
		}
	}

	/**
	 * REAL-WORLD RETRY: a forced 429 in front of the REAL production endpoint.
	 *
	 * <p>A local proxy returns 429 for the first attempt and transparently forwards the second to
	 * production. So the failure is injected, but the eventual delivery is a genuine production accept —
	 * proving the batch survives a rate-limit against the live server and lands exactly once.
	 */
	@Test
	public void forced429InFrontOfProductionRetriesAndLandsExactlyOnce() throws Exception
	{
		if (!enabled())
		{
			return;
		}
		requireEnabled();
		final AtomicInteger attempts = new AtomicInteger();
		final List<String> bodies = new ArrayList<>();
		proxy = new MockWebServer();
		proxy.setDispatcher(new Dispatcher()
		{
			@Override
			public MockResponse dispatch(RecordedRequest request)
			{
				int n = attempts.incrementAndGet();
				synchronized (bodies)
				{
					bodies.add(request.getBody().readUtf8());
				}
				if (n == 1)
				{
					return new MockResponse().setResponseCode(429).setHeader("Retry-After", "1");
				}
				// Second attempt: forward the real payload to production and mirror its status.
				try
				{
					String body;
					synchronized (bodies)
					{
						body = bodies.get(bodies.size() - 1);
					}
					okhttp3.OkHttpClient c = new okhttp3.OkHttpClient();
					okhttp3.Request fwd = new okhttp3.Request.Builder()
						.url(PROD + "/event-ingest")
						.post(okhttp3.RequestBody.create(
							okhttp3.MediaType.parse("application/json"), body))
						.build();
					try (okhttp3.Response resp = c.newCall(fwd).execute())
					{
						String payload = resp.body() == null ? "" : resp.body().string();
						return new MockResponse().setResponseCode(resp.code()).setBody(payload);
					}
				}
				catch (Exception e)
				{
					return new MockResponse().setResponseCode(500);
				}
			}
		});
		proxy.start();
		pointAt(proxy.url("/api").toString().replaceAll("/+$", ""));

		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("skill", "Attack");
		fields.put("level", 99);
		seed("level_up", fields);

		plugin.flushEvents();				// attempt 1 → 429
		Thread.sleep(2000);
		synchronized (plugin.pendingEvents)
		{
			assertEquals("the batch must survive the 429", 1, plugin.pendingEvents.size());
		}
		assertTrue("the 429 must arm the backoff", plugin.eventRetryBackoffUntilMs > 0);

		plugin.eventRetryBackoffUntilMs = 0L;	// jump the wait rather than sleeping it out
		plugin.flushEvents();				// attempt 2 → forwarded to production
		Thread.sleep(5000);

		synchronized (plugin.pendingEvents)
		{
			assertTrue("production accepted the retry, so the buffer must be empty",
				plugin.pendingEvents.isEmpty());
		}
		assertEquals("exactly two attempts: the refused one and the accepted one", 2, attempts.get());
		synchronized (bodies)
		{
			assertNotNull(bodies.get(0));
			assertEquals("both attempts must carry the same single event", bodies.get(0), bodies.get(1));
		}
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * The orphaned {@code uploadTradeScreenshots} key.
 *
 * Its config item was deleted when delivery-proof screenshots became part of core sync, but RuneLite
 * keeps a stored value whose item is gone, so the key is still in every upgraded profile. It was read
 * out of a live profile on 2026-09-15. Nothing reads it, so the risk is not behaviour: it is that a
 * profile file advertises a toggle the code does not have.
 */
public class OrphanConfigKeyTest
{
	@Test
	public void startUpUnsetsTheOrphanedKey() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		ConfigManager cm = mock(ConfigManager.class);
		inject(plugin, "configManager", cm);

		Method startUp = AccountConnectPlugin.class.getDeclaredMethod("startUp");
		startUp.setAccessible(true);
		startUp.invoke(plugin);

		verify(cm, times(1)).unsetConfiguration(
			AccountConnectPlugin.CONFIG_GROUP, AccountConnectPlugin.ORPHAN_SCREENSHOT_KEY);
	}

	/** A missing ConfigManager must not throw — startUp runs before injection in some test paths. */
	@Test
	public void aMissingConfigManagerIsASafeNoOp() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "configManager", null);
		plugin.removeOrphanedKeys();
	}

	/** And the key must genuinely be orphaned — if an item ever declares it again, this unset is a bug. */
	@Test
	public void theKeyIsNotDeclaredByAnyConfigItem()
	{
		for (Method m : AccountConnectConfig.class.getDeclaredMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			assertFalse("no live config item may own the orphaned key",
				AccountConnectPlugin.ORPHAN_SCREENSHOT_KEY.equals(item.keyName()));
		}
	}

	private static void inject(AccountConnectPlugin p, String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(p, value);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WorldChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Wave 1 default-on events: equip_change (worn-container diff), the two parsed milestones (kill_count,
 * pet) and world_hop. Logic proven against mocked containers and messages. Real event timing is
 * field-verified on the live client.
 *
 * NO CHAT-CHANNEL TESTS, DELIBERATELY. The original Wave 1 commit also logged private, friends, clan and
 * trade-request lines with the speaker's name. That is the broad chat sweep the hub pushed back on and
 * main deleted in b7a4f9f, so only the two own-account milestones were restored here.
 */
public class Wave1EventsTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		};
	}

	private static ItemContainer worn(int[]... items)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] a = new Item[items.length];
		for (int i = 0; i < items.length; i++)
		{
			a[i] = new Item(items[i][0], items[i][1]);
		}
		when(c.getItems()).thenReturn(a);
		return c;
	}

	private static AccountConnectPlugin plug() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", onConfig());
		return p;
	}

	// ---- equip_change ----

	@Test
	public void firstEquipChangeOnlyBaselines() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.handleEquipmentChanged(worn(new int[]{1234, 1}));
		assertTrue("first observation = baseline, no event", p.pendingEvents.isEmpty());
	}

	@Test
	public void equipThenUnequipEmitted() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.handleEquipmentChanged(worn(new int[]{1234, 1}));					// baseline: helm
		p.handleEquipmentChanged(worn(new int[]{1234, 1}, new int[]{5678, 1}));	// + weapon
		assertEquals(1, p.pendingEvents.size());
		Map<String, Object> ev = p.pendingEvents.get(0);
		assertEquals("equip_change", ev.get("type"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> equipped = (List<Map<String, Object>>) ev.get("equipped");
		assertEquals(1, equipped.size());
		assertEquals(5678, equipped.get(0).get("id"));
		assertNull(ev.get("unequipped"));

		p.handleEquipmentChanged(worn(new int[]{5678, 1}));					// unequip helm
		Map<String, Object> ev2 = p.pendingEvents.get(1);
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> un = (List<Map<String, Object>>) ev2.get("unequipped");
		assertEquals(1, un.size());
		assertEquals(1234, un.get(0).get("id"));
		assertNull(ev2.get("equipped"));
	}

	@Test
	public void equipChangeIsSilentWithoutALinkedToken() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "";
			}
		});
		p.handleEquipmentChanged(worn(new int[]{1234, 1}));
		p.handleEquipmentChanged(worn(new int[]{1234, 1}, new int[]{5678, 1}));
		assertTrue("no token = no events", p.pendingEvents.isEmpty());
	}

	// ---- parsed milestones ----

	@Test
	public void killCountParsedAndCommaStripped() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.emitParsedMilestones("Your Zulrah kill count is: 1,024");
		assertEquals("exactly one event", 1, p.pendingEvents.size());
		Map<String, Object> e = p.pendingEvents.get(0);
		assertEquals("kill_count", e.get("type"));
		assertEquals("comma-stripped count", 1024L, e.get("count"));
		assertEquals("raw line carried so the count says WHAT was killed",
			"Your Zulrah kill count is: 1,024", e.get("text"));
	}

	@Test
	public void petParsed() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.emitParsedMilestones("You have a funny feeling like you're being followed.");
		assertEquals(1, p.pendingEvents.size());
		assertEquals("pet", p.pendingEvents.get(0).get("type"));
	}

	@Test
	public void ordinaryGameMessageEmitsNothing() throws Exception
	{
		AccountConnectPlugin p = plug();
		p.emitParsedMilestones("Oh dear, you are dead!");
		assertTrue("no milestone false-positive, and no raw chat line either", p.pendingEvents.isEmpty());
	}

	@Test
	public void milestonesAreSilentWithoutALinkedToken() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return "";
			}
		});
		p.emitParsedMilestones("Your Zulrah kill count is: 1,024");
		assertTrue("no token = no events", p.pendingEvents.isEmpty());
	}

	// ---- world_hop ----

	@Test
	public void worldHopEmitsFromToAndSuppressesLogin() throws Exception
	{
		AccountConnectPlugin p = plug();
		Client c = mock(Client.class);
		inject(p, "client", c);
		when(c.getWorld()).thenReturn(302);
		p.onWorldChanged(mock(WorldChanged.class));		// first change = login, suppressed
		assertTrue("login world change suppressed", p.pendingEvents.isEmpty());
		when(c.getWorld()).thenReturn(330);
		p.onWorldChanged(mock(WorldChanged.class));		// real hop 302 -> 330
		Map<String, Object> e = p.pendingEvents.get(0);
		assertEquals("world_hop", e.get("type"));
		assertEquals(302, e.get("from"));
		assertEquals(330, e.get("to"));
	}

	/**
	 * F-H1 (rig 2026-09-27): logging in to the world the login screen already had fires no WorldChanged,
	 * so the first hop of the session was swallowed as if it were the login. LOGGED_IN seeds the world.
	 */
	@Test
	public void firstHopAfterLoginToTheAlreadySelectedWorldIsLogged() throws Exception
	{
		AccountConnectPlugin p = plug();
		Client c = mock(Client.class);
		inject(p, "client", c);
		when(c.getWorld()).thenReturn(308);
		p.onGameStateChanged(gameState(GameState.LOGIN_SCREEN));
		p.onGameStateChanged(gameState(GameState.LOGGING_IN));
		p.onGameStateChanged(gameState(GameState.LOGGED_IN));	// no WorldChanged: same world as the login screen
		p.pendingEvents.clear();								// drop login/logout rows; only the hop is under test
		when(c.getWorld()).thenReturn(301);
		p.onWorldChanged(mock(WorldChanged.class));
		assertEquals("first hop of the session is logged", 1, hops(p).size());
		assertEquals(308, hops(p).get(0).get("from"));
		assertEquals(301, hops(p).get(0).get("to"));
	}

	/** A LOGGED_IN after a hop must not re-seed: the hop row stays exactly one, with the right from/to. */
	@Test
	public void loggedInAfterAHopDoesNotDoubleOrLoseTheHop() throws Exception
	{
		AccountConnectPlugin p = plug();
		Client c = mock(Client.class);
		inject(p, "client", c);
		when(c.getWorld()).thenReturn(308);
		p.onGameStateChanged(gameState(GameState.LOGGED_IN));
		p.pendingEvents.clear();
		p.onGameStateChanged(gameState(GameState.HOPPING));
		when(c.getWorld()).thenReturn(301);
		p.onWorldChanged(mock(WorldChanged.class));
		p.onGameStateChanged(gameState(GameState.LOGGED_IN));
		when(c.getWorld()).thenReturn(330);
		p.onGameStateChanged(gameState(GameState.HOPPING));
		p.onWorldChanged(mock(WorldChanged.class));
		p.onGameStateChanged(gameState(GameState.LOGGED_IN));
		List<Map<String, Object>> h = hops(p);
		assertEquals(2, h.size());
		assertEquals(308, h.get(0).get("from"));
		assertEquals(301, h.get(0).get("to"));
		assertEquals(301, h.get(1).get("from"));
		assertEquals(330, h.get(1).get("to"));
	}

	/**
	 * If the hop's LOGGED_IN arrives after the client already reports the new world but BEFORE WorldChanged,
	 * the seed must not overwrite the old world, or the hop reads as 301 -> 301 and is lost.
	 */
	@Test
	public void loggedInBeforeWorldChangedOnAHopKeepsTheOldWorld() throws Exception
	{
		AccountConnectPlugin p = plug();
		Client c = mock(Client.class);
		inject(p, "client", c);
		when(c.getWorld()).thenReturn(308);
		p.onGameStateChanged(gameState(GameState.LOGGED_IN));
		p.onGameStateChanged(gameState(GameState.HOPPING));
		when(c.getWorld()).thenReturn(301);
		p.onGameStateChanged(gameState(GameState.LOGGED_IN));
		p.onWorldChanged(mock(WorldChanged.class));
		List<Map<String, Object>> h = hops(p);
		assertEquals(1, h.size());
		assertEquals(308, h.get(0).get("from"));
		assertEquals(301, h.get(0).get("to"));
	}

	/** A login to a DIFFERENT world than the login screen had is still not a hop. */
	@Test
	public void loginToAnotherWorldIsStillNotAHop() throws Exception
	{
		AccountConnectPlugin p = plug();
		Client c = mock(Client.class);
		inject(p, "client", c);
		when(c.getWorld()).thenReturn(308);
		p.onGameStateChanged(gameState(GameState.LOGIN_SCREEN));
		when(c.getWorld()).thenReturn(420);
		p.onWorldChanged(mock(WorldChanged.class));		// world picked on the login screen
		p.onGameStateChanged(gameState(GameState.LOGGED_IN));
		assertTrue("no hop at login", hops(p).isEmpty());
	}

	private static GameStateChanged gameState(GameState s)
	{
		GameStateChanged e = new GameStateChanged();
		e.setGameState(s);
		return e;
	}

	private static List<Map<String, Object>> hops(AccountConnectPlugin p)
	{
		List<Map<String, Object>> out = new java.util.ArrayList<>();
		for (Map<String, Object> e : p.pendingEvents)
		{
			if ("world_hop".equals(e.get("type")))
			{
				out.add(e);
			}
		}
		return out;
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Map;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * THE STOP CONTRACT. Thirteen named cases, one arm each, driven through the plugin's own methods.
 *
 * THE CONTRACT THESE ARMS ENFORCE, stated once:
 *
 *   FIRST Drop action -> one continuous session
 *     -> every live pile AND every pending drop represented correctly
 *     -> no stop while ANY of those remain
 *     -> the final pile disappears, or the final pending drop definitively expires
 *     -> exactly TAIL_MILLIS more -> stop.
 *
 * WHY THIS FILE EXISTS. The 0.7.14 privacy review measured a recorder that could never stop in
 * three ordinary cases, while both user-facing strings promised it stopped five seconds after the
 * last pile went. The old suite was green throughout, because its longest arm asserted the recorder
 * KEEPS GOING — the opposite property — and nothing asserted an end at all.
 *
 * AND THE SECOND RULE. An outcome that cannot be PROVEN is never COMPLETE. Cases 2, 5, 6, 7, 8, 9,
 * 10 and 11 all end INTERRUPTED, each for a reason the manifest names in outcome_reason.
 */
public class DropStopContractTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final String OTHER_TOKEN = "fedcba9876543210".repeat(2);

	/** A config whose two user-controlled values can be changed mid-session, exactly as a user can. */
	private static final class MutableConfig implements AccountConnectConfig
	{
		/** false models the user clearing the link token, the one user-side stop. */
		volatile boolean upload = true;
		volatile String token = TOKEN;

		@Override
		public String linkToken()
		{
			return upload ? token : "";
		}
	}

	private static final class Rig
	{
		final AccountConnectPlugin plugin = new AccountConnectPlugin();
		final MutableConfig config = new MutableConfig();
	}

	private static Rig rig() throws Exception
	{
		Rig r = new Rig();
		Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(r.plugin, r.config);
		r.plugin.setStoreToolsForTest(true);		// the shop-overlay grant
		r.plugin.setDropProofRolloutForTest(true);	// the SEPARATE drop-proof rollout flag
		return r;
	}

	private static void dropAction(AccountConnectPlugin p) throws Exception
	{
		Method m = AccountConnectPlugin.class.getDeclaredMethod("onDropActionForProof");
		m.setAccessible(true);
		m.invoke(p);
	}

	private static AccountConnectPlugin.DroppedGroundItem pile(int item, long qty, int x, int y)
	{
		Map<String, Object> loc = new java.util.LinkedHashMap<>();
		loc.put("region_id", 12853);
		loc.put("plane", 0);
		return new AccountConnectPlugin.DroppedGroundItem(item, qty, x, y, 0, loc, 100, 400);
	}

	private static void attach(AccountConnectPlugin p, AccountConnectPlugin.DroppedGroundItem g)
		throws Exception
	{
		Method m = AccountConnectPlugin.class.getDeclaredMethod(
			"attachPileToDropSession", AccountConnectPlugin.DroppedGroundItem.class);
		m.setAccessible(true);
		m.invoke(p, g);
	}

	private static void release(AccountConnectPlugin p, AccountConnectPlugin.DroppedGroundItem g)
		throws Exception
	{
		Method m = AccountConnectPlugin.class.getDeclaredMethod(
			"releasePileFromDropSession", AccountConnectPlugin.DroppedGroundItem.class);
		m.setAccessible(true);
		m.invoke(p, g);
	}

	private static Object field(AccountConnectPlugin p, String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(p);
	}

	private static Map<String, Object> manifest(AccountConnectPlugin p)
	{
		for (Map<String, Object> e : p.pendingEvents)
		{
			if ("drop_trade_clip".equals(e.get("type")))
			{
				return e;
			}
		}
		return null;
	}

	/** Make an armed tail due without sleeping five real seconds. */
	private static void forceTailDue(AccountConnectPlugin p) throws Exception
	{
		Field f = DropSessionRecorder.class.getDeclaredField("stopAtMillis");
		f.setAccessible(true);
		f.setLong(p.dropSession, 1L);
	}

	/**
	 * Move every pending drop's deadline into the past, so the next poll expires it.
	 *
	 * The alternative is sleeping PENDING_DROP_EXPIRY_MILLIS, which would put ten real seconds into
	 * the suite for every arm that needs one. The DEADLINE is what the production code reads, so
	 * rewriting it exercises the same branch a real ten-second wait would.
	 */
	@SuppressWarnings("unchecked")
	private static void forcePendingsExpired(AccountConnectPlugin p) throws Exception
	{
		Field f = DropSessionRecorder.class.getDeclaredField("pendingDrops");
		f.setAccessible(true);
		Map<Integer, Long> pendings = (Map<Integer, Long>) f.get(p.dropSession);
		for (Map.Entry<Integer, Long> e : pendings.entrySet())
		{
			e.setValue(1L);
		}
	}

	/** Drive the tick poll enough times that nothing can be waiting on a later tick. */
	private static void poll(AccountConnectPlugin p, int times)
	{
		for (int i = 0; i < times; i++)
		{
			p.pollDropSession();
		}
	}

	// ================= CASE 1 — a single ordinary drop =================

	@Test
	public void case01_singleOrdinaryDropStopsFiveSecondsAfterThePileGoes() throws Exception
	{
		Rig r = rig();
		AccountConnectPlugin p = r.plugin;
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 1_000_000L, 3200, 3400);
		attach(p, g);
		assertEquals("the pile resolves the pending", 0, p.dropSession.pendingDropCount());
		assertEquals(1, p.dropSession.activePileCount());

		p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, 1}, 1_000L);
		poll(p, 5);
		assertTrue("a live pile means no stop, however long we poll", p.dropSession.active());
		assertFalse(p.dropSession.stopPending());

		release(p, g);
		assertTrue("the last pile going arms the tail", p.dropSession.stopPending());
		poll(p, 1);
		assertTrue("and the tail has NOT elapsed yet", p.dropSession.active());

		forceTailDue(p);
		poll(p, 1);
		assertFalse("the tail elapsed, so the session is over", p.dropSession.active());
		Map<String, Object> m = manifest(p);
		assertNotNull(m);
		assertEquals("COMPLETE", m.get("outcome"));
		assertNull("a complete session names no reason", m.get("outcome_reason"));
	}

	// ============ CASE 2 — two stackable drops, ONE physical pile ============

	/**
	 * FINDING F1 PATH A, the case that could never stop.
	 *
	 * Dropping a stackable onto our own live pile of the same item on the same tile MERGES it in
	 * the game. The client fires one ItemQuantityChanged growth, and later exactly ONE
	 * ItemDespawned. The old code tracked a second pile and minted a second session key, which no
	 * despawn could ever release, so the tail never armed.
	 */
	@Test
	public void case02_twoStackableDropsOnOneTileAreOnePileAndOneDespawn() throws Exception
	{
		Rig r = rig();
		AccountConnectPlugin p = r.plugin;

		dropAction(p);
		p.trackGroundDrop(995, 500L, 3200, 3400, 0, null, 100, 400, false);
		assertEquals("the first drop makes one real pile", 1, p.dropSession.activePileCount());

		dropAction(p);
		// The SECOND drop arrives as a quantity growth on the same tile — a merge, not a spawn.
		p.trackGroundDrop(995, 1_000L, 3200, 3400, 0, null, 101, 400, true);

		assertEquals("the game has ONE pile, so the session must hold ONE key",
			1, p.dropSession.activePileCount());
		assertEquals("and the merged drop's pending is resolved, not left outstanding",
			0, p.dropSession.pendingDropCount());
		assertEquals("two drops are still counted", 2, p.dropSession.dropCount());

		// The one despawn the client will actually fire.
		AccountConnectPlugin.DroppedGroundItem tracked = onlyTrackedPile(p);
		release(p, tracked);
		assertTrue("the single despawn must arm the tail", p.dropSession.stopPending());

		forceTailDue(p);
		poll(p, 1);
		assertFalse("and the session must actually end", p.dropSession.active());
		assertEquals("every drop was observed on the merged pile, so this IS complete",
			"COMPLETE", manifest(p).get("outcome"));
	}

	@SuppressWarnings("unchecked")
	private static AccountConnectPlugin.DroppedGroundItem onlyTrackedPile(AccountConnectPlugin p)
		throws Exception
	{
		java.util.Deque<AccountConnectPlugin.DroppedGroundItem> q =
			(java.util.Deque<AccountConnectPlugin.DroppedGroundItem>) field(p, "groundDrops");
		assertEquals("exactly one tracked pile", 1, q.size());
		return q.peekFirst();
	}

	// ================= CASE 3 — rapid multi-drop =================

	@Test
	public void case03_rapidMultiDropIsOneSessionThatStopsOnlyAfterTheLastPile() throws Exception
	{
		Rig r = rig();
		AccountConnectPlugin p = r.plugin;
		AccountConnectPlugin.DroppedGroundItem[] piles = new AccountConnectPlugin.DroppedGroundItem[8];
		String sid = null;
		for (int i = 0; i < 8; i++)
		{
			dropAction(p);
			if (sid == null)
			{
				sid = p.dropSession.sessionId();
			}
			assertEquals("eight drops, ONE session", sid, p.dropSession.sessionId());
			// Eight DIFFERENT tiles, so these are eight genuinely separate piles.
			piles[i] = pile(4151, 1L, 3200 + i, 3400);
			attach(p, piles[i]);
		}
		assertEquals(8, p.dropSession.activePileCount());
		assertEquals(0, p.dropSession.pendingDropCount());

		for (int i = 0; i < 7; i++)
		{
			release(p, piles[i]);
			assertFalse("seven gone, one live — still no stop", p.dropSession.stopPending());
		}
		release(p, piles[7]);
		assertTrue("the eighth arms the tail", p.dropSession.stopPending());
		forceTailDue(p);
		poll(p, 1);
		assertEquals("COMPLETE", manifest(p).get("outcome"));
		assertEquals(8, manifest(p).get("drops"));
	}

	// ========= CASE 4 — a new drop during the tail cancels the stop =========

	@Test
	public void case04_aDropInsideTheTailCancelsTheStopAndKeepsOneSession() throws Exception
	{
