				p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, (byte) i}, 1_000L + i);
				p.trackGroundDrop(1931, qty[i], 3200, 3400, 0, null, 100 + i, 900, false);
				physical[i] = scene.lay("OURS" + i, 1931, 3200, 3400, qty[i]);
			}

			int[] takeOrder = oldestFirst ? new int[]{0, 1, 2} : new int[]{2, 1, 0};
			for (int t = 0; t < 3; t++)
			{
				int i = takeOrder[t];
				AccountConnectPlugin.DroppedGroundItem chosen =
					despawnInScene(p, scene, physical[i], 500 + t * 10, true);
				assertNotNull("FINDING R7 (" + order + "): take " + (t + 1) + " must not be refused",
					chosen);
				poll(p, 2);
				Map<String, Object> row = lastRemoval(p);
				assertEquals("FINDING R7 (" + order + "): the row must carry the DEPARTED pile's qty",
					qty[i], row.get("qty"));
				assertEquals("FINDING R7 (" + order + "): and its own drop_seq",
					i + 1, row.get("drop_seq"));
			}

			assertEquals("all three rows published (" + order + ")", 3, allRemovals(p).size());
			assertFalse("nothing is unprovable (" + order + ")", p.dropSession.unprovable());
			forceTailDue(p);
			poll(p, 1);
			assertEquals("FINDING R7 (" + order + "): the trade ends COMPLETE",
				"COMPLETE", manifest(p).get("outcome"));
		}
	}

	// ===== CASE 60 — the SAME trade with ONE STRANGER'S PILE: refused, never COMPLETE =====

	/**
	 * Ten own piles PLUS one untracked rival of the same item on the same tile. The count rule must
	 * come down on the CONSERVATIVE side here: with C piles left and |S| records owned, C >= |S|
	 * means at least one pile on that tile is not ours, so the despawn is refused whole. No row may
	 * be fabricated and the manifest must never say COMPLETE.
	 *
	 * This is the control that stops "just stop refusing" from passing case 58. FINDING R4 must stay
	 * closed.
	 */
	@Test
	public void case60_oneStrangerPileAmongTenOwnPilesStillRefusesAndNeverCompletes()
		throws Exception
	{
		Rig r = rig();
		AccountConnectPlugin p = r.plugin;
		FakeScene scene = withScene(p);

		// The physical ground: a REAL rival pile of item 1931 the plugin NEVER tracked.
		FakePile rival = scene.lay("RIVAL", 1931, 3200, 3400, 777L);

		FakePile[] physical = new FakePile[10];
		for (int i = 0; i < 10; i++)
		{
			dropAction(p);
			p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, (byte) i}, 1_000L + i);
			p.trackGroundDrop(1931, 11L * (i + 1), 3200, 3400, 0, null, 100 + i, 900, false);
			physical[i] = scene.lay("OURS" + i, 1931, 3200, 3400, 11L * (i + 1));
		}
		assertEquals("the plugin tracks only OUR ten", 10, p.groundDropCount());

		// The customer takes one of OURS while the stranger's pile is still down.
		AccountConnectPlugin.DroppedGroundItem chosen =
			despawnInScene(p, scene, physical[0], 500, true);
		poll(p, 5);

		// THE OUTCOME, asserted first.
		assertTrue("FINDING R4: NO EARLY STOP while a pile we do not own is on the tile",
			p.dropSession.active());
		assertFalse("and the tail must NOT arm", p.dropSession.stopPending());
		assertTrue("FINDING R4: COMPLETE is out of reach", p.dropSession.unprovable());
		assertEquals("FINDING R4: NO row may be fabricated for an ambiguous take",
			0, allRemovals(p).size());
		assertNull("the despawn itself is refused", chosen);
		assertEquals("the session keeps every key", 10, p.dropSession.activePileCount());

		// The whole tile then clears, ours and the stranger's alike.
		for (int i = 1; i < 10; i++)
		{
			despawnInScene(p, scene, physical[i], 510 + i, true);
			poll(p, 2);
		}
		despawnInScene(p, scene, rival, 600, true);
		poll(p, 5);
		forceTailDue(p);
		poll(p, 1);
		assertFalse(p.dropSession.active());
		assertEquals("FINDING R4: a session that shared its tile with a stranger's pile is "
				+ "INTERRUPTED, never COMPLETE", "INTERRUPTED", manifest(p).get("outcome"));
	}

	// ===== CASE 61 — EQUAL-quantity own piles: rows still published, session still provable =====

	/**
	 * Three of the session's own piles of one item on one tile, ALL with the same quantity. The
	 * count still proves one of OURS left, so a row is owed. Which of our equal piles it was cannot
	 * be told apart, so the row says so in `attribution_uncertain` and keeps its honest qty and
	 * session linkage.
	 *
	 * The SESSION must NOT be marked unprovable. Two of our own equal piles are not a stranger, and
	 * refusing the whole trade over them would be FINDING R7 again in a smaller form.
	 */
	@Test
	public void case61_equalQuantityOwnPilesStillPublishRowsAndTheSessionStaysProvable()
		throws Exception
	{
		Rig r = rig();
		AccountConnectPlugin p = r.plugin;
		FakeScene scene = withScene(p);

		FakePile[] physical = new FakePile[3];
		for (int i = 0; i < 3; i++)
		{
			dropAction(p);
			p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, (byte) i}, 1_000L + i);
			p.trackGroundDrop(1931, 50L, 3200, 3400, 0, null, 100 + i, 900, false);
			physical[i] = scene.lay("OURS" + i, 1931, 3200, 3400, 50L);
		}

		for (int t = 0; t < 3; t++)
		{
			AccountConnectPlugin.DroppedGroundItem chosen =
				despawnInScene(p, scene, physical[t], 500 + t, true);
			assertNotNull("equal quantities are OURS either way, so the take is not refused", chosen);
			poll(p, 2);
		}

		// THE OUTCOME, asserted first.
		assertEquals("all three rows are published", 3, allRemovals(p).size());
		assertFalse("the session is NOT unprovable: every candidate pile was ours",
			p.dropSession.unprovable());
		assertTrue("the tail arms", p.dropSession.stopPending());
		forceTailDue(p);
		poll(p, 1);
		assertEquals("and the trade ends COMPLETE", "COMPLETE", manifest(p).get("outcome"));

		// The rows are honest about the ONE thing that is uncertain.
		java.util.List<Map<String, Object>> rows = allRemovals(p);
		assertEquals("the first two rows name their tie", "equal_quantity_own_piles",
			rows.get(0).get("attribution_uncertain"));
		assertEquals("equal_quantity_own_piles", rows.get(1).get("attribution_uncertain"));
		assertNull("the LAST pile has no equal left to be confused with",
			rows.get(2).get("attribution_uncertain"));
		for (Map<String, Object> row : rows)
		{
			assertEquals("the quantity is certain, because every candidate carried it",
				50L, row.get("qty"));
			assertNotNull("and the linkage is kept: the pile was certainly ours",
				row.get("drop_session_id"));
		}
	}

	// ===== CASE 62 — FINDING R8: the per-poll release COUNTS, it does not ask presence =====

	/**
	 * Two of the session's own piles of ONE item on ONE tile, with different quantities. One leaves
	 * with NO despawn event reaching us, which is the state FINDING R5 was about.
	 *
	 * On 3967e39 the poll asked "is an item of that id still on that tile?" once per RECORD, so both
	 * records asked the SAME question, got PRESENT, and BOTH keys were kept. The recording then ran
	 * past the moment the disclosure names. Counting releases exactly the one key whose pile is
	 * gone, and the QUANTITY says which one.
	 */
	@Test
	public void case62_thePerPollReleaseCountsPilesAndPicksTheOneWhoseQuantityIsGone()
		throws Exception
	{
		Rig r = rig();
		AccountConnectPlugin p = r.plugin;
		FakeScene scene = withScene(p);

		dropAction(p);
		p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, 1}, 1_000L);
		p.trackGroundDrop(1931, 7L, 3200, 3400, 0, null, 100, 900, false);
		FakePile seven = scene.lay("OURS7", 1931, 3200, 3400, 7L);
		dropAction(p);
		p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, 2}, 1_001L);
		p.trackGroundDrop(1931, 9L, 3200, 3400, 0, null, 101, 900, false);
		scene.lay("OURS9", 1931, 3200, 3400, 9L);
		assertEquals("two own piles of one item on one tile", 2, p.dropSession.activePileCount());

		// The pile of 7 physically leaves and NO despawn event reaches the plugin.
		scene.remove(seven);
		poll(p, 3);

		// THE OUTCOME, asserted first. Keeping BOTH keys is the LATE direction FINDING R5 named: the
		// recording runs on past the moment a pile the disclosure counts actually disappeared, and
		// every one of those frames uploads. Releasing BOTH would be the EARLY direction.
		assertEquals("FINDING R8: NOT LATE and NOT EARLY — exactly ONE key is released, because "
				+ "exactly one of our two piles left the tile",
			1, p.dropSession.activePileCount());
		assertTrue("the session is still recording, because our other pile is still down",
			p.dropSession.active());
		assertFalse("NO EARLY STOP: the tail must not arm while a session pile is on the ground",
			p.dropSession.stopPending());
		assertTrue("a pile released without being observed to leave makes the session unprovable",
			p.dropSession.unprovable());

		// And it released the RIGHT one: the surviving record is the pile still physically down.
		assertEquals("one record survives", 1, p.groundDropCount());
		assertEquals("FINDING R8: and it is the pile of 9, which is still on the tile",
			9L, groundDrops(p).iterator().next().qty);

		// When the second pile goes too, the tail arms on the very next poll.
		scene.piles.clear();
		poll(p, 2);
		assertEquals("both keys released", 0, p.dropSession.activePileCount());
		assertTrue("NOT LATE: the tail arms one poll after the tile is clear",
			p.dropSession.stopPending());
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The drop-proof path as the PLUGIN wires it, not as its parts behave alone.
 *
 * The three unit suites prove the session machine, the segmenter and the candidate rule in
 * isolation. Isolation is exactly where a wiring bug survives: a correct session machine that the
 * plugin never tells about a removal still produces a clip that stops in the wrong place. These
 * arms drive the plugin's own methods — the drop action, the pile attach, the removal emit, the
 * frame accept — and assert on the events it actually buffers.
 *
 * The frame path is driven with synthetic bytes through acceptDropFrame, so there is no render
 * loop, no DrawManager and no ImageIO here. What is being tested is the plugin's bookkeeping.
 */
public class DropProofIntegrationTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

		});
		p.setStoreToolsForTest(true);		// the shop-overlay grant
		p.setDropProofRolloutForTest(true);	// the SEPARATE drop-proof rollout flag (finding F4)
		return p;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static Object get(AccountConnectPlugin p, String field) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return f.get(p);
	}

	/** Drive the plugin's own drop-action entry point. */
	private static void dropAction(AccountConnectPlugin p) throws Exception
	{
		Method m = AccountConnectPlugin.class.getDeclaredMethod("onDropActionForProof");
		m.setAccessible(true);
		m.invoke(p);
	}

	private static AccountConnectPlugin.DroppedGroundItem pile(int item, long qty, int x, int y)
	{
		java.util.Map<String, Object> loc = new java.util.LinkedHashMap<>();
		loc.put("region_id", 12853);
		loc.put("plane", 0);
		return new AccountConnectPlugin.DroppedGroundItem(item, qty, x, y, 0, loc, 100, 400);
	}

	private static void attach(AccountConnectPlugin p, AccountConnectPlugin.DroppedGroundItem g)
		throws Exception
	{
		Method m = AccountConnectPlugin.class.getDeclaredMethod(
			"attachPileToDropSession", AccountConnectPlugin.DroppedGroundItem.class);
		m.setAccessible(true);
		m.invoke(p, g);
	}

	private static void release(AccountConnectPlugin p, AccountConnectPlugin.DroppedGroundItem g)
		throws Exception
	{
		Method m = AccountConnectPlugin.class.getDeclaredMethod(
			"releasePileFromDropSession", AccountConnectPlugin.DroppedGroundItem.class);
		m.setAccessible(true);
		m.invoke(p, g);
	}

	private static Map<String, Object> eventOfType(AccountConnectPlugin p, String type)
	{
		for (Map<String, Object> e : p.pendingEvents)
		{
			if (type.equals(e.get("type")))
			{
				return e;
			}
		}
		return null;
	}

	// ---- session linkage on the events ----

	@Test
	public void aDropActionStartsASessionAndThePileJoinsIt() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		assertTrue("the ACTION starts the session, not the drop event", p.dropSession.active());
		String sid = p.dropSession.sessionId();
		assertNotNull(sid);

		AccountConnectPlugin.DroppedGroundItem g = pile(995, 1_000_000L, 3200, 3400);
		attach(p, g);
		assertEquals("the pile knows its drop sequence", 1, p.dropSeqForPile(g));
		assertEquals("and its session", sid, p.dropSessionForPile(g));
		assertEquals(1, p.dropSession.activePileCount());
	}

	@Test
	public void twoPilesOfTheSameItemOnTheSameTileGetDifferentSequences() throws Exception
	{
		// The ordinary shape of a drop trade. If both piles share a key the second removal finds
		// nothing and the session's tail arms while a pile is still live.
		AccountConnectPlugin p = plugin();
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem a = pile(995, 500L, 3200, 3400);
		attach(p, a);
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem b = pile(995, 500L, 3200, 3400);
		attach(p, b);

		assertEquals(1, p.dropSeqForPile(a));
		assertEquals(2, p.dropSeqForPile(b));
		assertEquals("two distinct live piles", 2, p.dropSession.activePileCount());

		release(p, a);
		assertFalse("one pile still live — no tail yet", p.dropSession.stopPending());
		release(p, b);
		assertTrue("last pile gone — tail armed", p.dropSession.stopPending());
	}

	/** A removal emits ONE ground_removed carrying the session id, the sequence and the pile tile. */
	@Test
	public void aRemovalCarriesSessionLinkageAndThePileTile() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		String sid = p.dropSession.sessionId();
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 1_000_000L, 3211, 3455);
		attach(p, g);

		p.emitGroundRemoval(g, 120, false);

		Map<String, Object> ev = eventOfType(p, "ground_removed");
		assertNotNull("a removal was emitted", ev);
		assertEquals(sid, ev.get("drop_session_id"));
		assertEquals(1, ev.get("drop_seq"));
		@SuppressWarnings("unchecked")
		Map<String, Object> tile = (Map<String, Object>) ev.get("tile");
		assertNotNull("the pile's OWN tile is on the row", tile);
		assertEquals(3211, tile.get("x"));
		assertEquals(3455, tile.get("y"));
		assertEquals(0, tile.get("plane"));
	}

	@Test
	public void aRemovalAlsoReleasesThePileSoTheTailCanArm() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 5L, 3200, 3400);
		attach(p, g);
		assertEquals(1, p.dropSession.activePileCount());

		p.emitGroundRemoval(g, 120, false);

		assertEquals("emitting the removal releases the pile", 0, p.dropSession.activePileCount());
		assertTrue(p.dropSession.stopPending());
	}

	// ---- causes, all preserved ----

	@Test
	public void everyCauseCarriesACounterpartyStatus() throws Exception
	{
		// removed_early with nobody around
		AccountConnectPlugin p = plugin();
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem early = pile(995, 5L, 3200, 3400);
		attach(p, early);
		p.emitGroundRemoval(early, 120, false);
		Map<String, Object> ev = eventOfType(p, "ground_removed");
		assertEquals("removed_early", ev.get("cause"));
		assertEquals(DropCandidates.STATUS_UNKNOWN, ev.get("counterparty_status"));
		assertEquals("the taker is never asserted", "UNKNOWN", ev.get("recipient"));

		// self_pickup — the cause must survive, and it must not be read as a counterparty case
		AccountConnectPlugin p2 = plugin();
		dropAction(p2);
		AccountConnectPlugin.DroppedGroundItem self = pile(995, 5L, 3200, 3400);
		self.selfPickedUp = true;
		attach(p2, self);
		p2.emitGroundRemoval(self, 120, false);
		Map<String, Object> ev2 = eventOfType(p2, "ground_removed");
		assertEquals("self_pickup", ev2.get("cause"));
		assertEquals(DropCandidates.STATUS_UNKNOWN, ev2.get("counterparty_status"));
		assertNull("a self-pickup never carries candidates", ev2.get("taken_by_candidates"));
		assertNull(ev2.get("counterparty_inferred"));
	}

	/**
	 * Counterparty distance is measured from the PILE, not from our character. The staff member has walked
	 * 10 tiles off; the customer stands on the pile. Player-centred measurement would drop the customer
	 * (out of range) and could name a bystander next to us instead.
	 */
	@Test
	public void theCounterpartyIsMeasuredFromThePileNotFromUs() throws Exception
	{
		AccountConnectPlugin p = plugin();
		net.runelite.api.Client c = org.mockito.Mockito.mock(net.runelite.api.Client.class);
		net.runelite.api.Player me = org.mockito.Mockito.mock(net.runelite.api.Player.class);
		org.mockito.Mockito.when(me.getWorldLocation()).thenReturn(new net.runelite.api.coords.WorldPoint(3210, 3400, 0));
		net.runelite.api.Player customer = player("Customer", 3200, 3400);
		net.runelite.api.Player bystander = player("Bystander", 3210, 3400);	// standing on OUR tile
		org.mockito.Mockito.when(c.getLocalPlayer()).thenReturn(me);
		org.mockito.Mockito.when(c.getPlayers()).thenReturn(java.util.Arrays.asList(me, customer, bystander));
		inject(p, "client", c);
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 5L, 3200, 3400);
		attach(p, g);
		p.emitGroundRemoval(g, 120, false);
		Map<String, Object> ev = eventOfType(p, "ground_removed");
		assertEquals("removed_early", ev.get("cause"));
		assertEquals("the player on the pile is named", "Customer", ev.get("counterparty_inferred"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> cands = (List<Map<String, Object>>) ev.get("taken_by_candidates");
		assertNotNull(cands);
		assertEquals("Customer", cands.get(0).get("rsn"));
		assertEquals("dist is from the pile", 0, cands.get(0).get("dist"));
		for (Map<String, Object> m : cands)
		{
			assertFalse("a player 10 tiles from the pile is not a candidate", "Bystander".equals(m.get("rsn")));
		}
	}

	private static net.runelite.api.Player player(String name, int x, int y)
	{
		net.runelite.api.Player pl = org.mockito.Mockito.mock(net.runelite.api.Player.class);
		org.mockito.Mockito.when(pl.getName()).thenReturn(name);
		org.mockito.Mockito.when(pl.getWorldLocation()).thenReturn(new net.runelite.api.coords.WorldPoint(x, y, 0));
		org.mockito.Mockito.when(pl.getCombatLevel()).thenReturn(3);
		return pl;
	}

	@Test
	public void theDespawnTimerCauseSurvivesAndCarriesNoCandidates() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		// dropTick 100, despawnTick 400: a removal AT the deadline, with the full timer elapsed.
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 5L, 3200, 3400);
		attach(p, g);
		p.emitGroundRemoval(g, 400, false);
		Map<String, Object> ev = eventOfType(p, "ground_removed");
		assertEquals("despawn_timer", ev.get("cause"));
		assertEquals(DropCandidates.STATUS_UNKNOWN, ev.get("counterparty_status"));
		assertNull(ev.get("taken_by_candidates"));
	}

	@Test
	public void anUnreliableObservationStaysUnknown() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 5L, 3200, 3400);
		attach(p, g);
		// A scene reload despawns every pile at once, so nothing about a taker can be read from it.
		p.emitGroundRemoval(g, 120, true);
		Map<String, Object> ev = eventOfType(p, "ground_removed");
		assertEquals("unknown", ev.get("cause"));
		assertEquals(DropCandidates.STATUS_UNKNOWN, ev.get("counterparty_status"));
	}

	// ---- interruption ----

	@Test
	public void anInterruptEndsTheSessionAndLabelsTheManifest() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		String sid = p.dropSession.sessionId();
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 5L, 3200, 3400);
		attach(p, g);
		// One real frame through the real accept path, so the manifest has something to report.
		p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, 1, 2, 3}, 1_000L);

		p.interruptDropSession();

		assertFalse("the session is over", p.dropSession.active());
		Map<String, Object> manifest = eventOfType(p, "drop_trade_clip");
		assertNotNull("an interrupted session still publishes its manifest", manifest);
		assertEquals(sid, manifest.get("drop_session_id"));
		assertEquals("INTERRUPTED", manifest.get("outcome"));
		assertEquals("the captured frame is NOT discarded", 1, manifest.get("frames"));
		assertEquals(1, manifest.get("drops"));
	}

	@Test
	public void aCompleteSessionPublishesACompleteManifest() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		AccountConnectPlugin.DroppedGroundItem g = pile(995, 5L, 3200, 3400);
		attach(p, g);
		p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, 9}, 1_000L);
		release(p, g);

		// Force the tail to be due, then poll exactly as the tick handler does.
		p.dropSession.pileRemoved("no-such-pile", 0L);		// no-op; the tail is already armed
		Thread.sleep(5);
		forceTailDue(p);
		p.pollDropSession();

		assertFalse(p.dropSession.active());
		Map<String, Object> manifest = eventOfType(p, "drop_trade_clip");
		assertNotNull(manifest);
		assertEquals("COMPLETE", manifest.get("outcome"));
		assertEquals("drop_frames", manifest.get("media_kind"));
		assertEquals(30, manifest.get("fps"));
	}

	/** Make the armed tail due without sleeping 5 real seconds. */
	private static void forceTailDue(AccountConnectPlugin p) throws Exception
	{
		Field f = DropSessionRecorder.class.getDeclaredField("stopAtMillis");
		f.setAccessible(true);
		f.setLong(p.dropSession, 1L);	// any past instant; 0 is not a sentinel here
	}

	@Test
	public void theManifestNamesADistinctMediaKindNotTheStoreOne() throws Exception
	{
		// A drop clip is not a shop visit. The collector, the stitcher and the staff surfaces all
		// key off this string, so mislabelling one as the other mixes two kinds of evidence.
		assertEquals("drop_frames", AccountConnectPlugin.DROP_MEDIA_KIND);
		assertFalse("store_frames".equals(AccountConnectPlugin.DROP_MEDIA_KIND));
	}

	// ---- the gate ----

	@Test
	public void noServerGrantMeansNoSessionAtAll() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

		});
		// setStoreToolsForTest NOT called: no grant.
		dropAction(p);
		assertFalse("an ungranted client records nothing", p.dropSession.active());
		assertTrue(p.pendingEvents.isEmpty());
	}

	@Test
	public void theDevOverrideIsOffUnlessAJvmFlagSetsIt() throws Exception
	{
		// The override exists so the field rig can reach the capture path on a non-staff token. It
		// must be OFF by default, or a Hub build would capture for every granted user regardless of
		// what the server said about clips.
		assertFalse("no system property set", AccountConnectPlugin.dropProofDevOverride());
		try
		{
			System.setProperty("osrsbis.dropproof", "on");
			assertTrue(AccountConnectPlugin.dropProofDevOverride());
			System.setProperty("osrsbis.dropproof", "nonsense");
			assertFalse("only on/true/1 enable it", AccountConnectPlugin.dropProofDevOverride());
		}
		finally
		{
			System.clearProperty("osrsbis.dropproof");
		}
	}

	@Test
	public void theOverrideCannotBypassTheServerSTORETOOLSGrant() throws Exception
	{
		// It overrides the CLIPS half only. Without the store-tools grant there is still no session,
		// so the override can never turn an ungranted ordinary player into a recording one.
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}

		});
		p.setDropProofRolloutForTest(true);
		try
		{
			System.setProperty("osrsbis.dropproof", "on");
			dropAction(p);
			assertFalse("no store-tools grant means no session, override or not", p.dropSession.active());
		}
		finally
		{
			System.clearProperty("osrsbis.dropproof");
		}
	}

	// ---- the segment path through the plugin ----

	@Test
	public void framesFlowThroughThePluginIntoBoundedSegments() throws Exception
	{
		AccountConnectPlugin p = plugin();
		dropAction(p);
		// 95 frames: two full 40-frame segments plus a 15-frame remainder.
		for (int i = 0; i < 95; i++)
		{
			p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, (byte) i}, 1_000L + i);
		}
		DropFrameSegmenter seg = (DropFrameSegmenter) get(p, "dropSegmenter");
		assertNotNull(seg);
		assertEquals("two full segments handed over", 2, seg.segmentCount());
		assertEquals("the remainder is still buffered", 15, seg.bufferedFrames());
		assertEquals(95, seg.acceptedFrames());

		p.interruptDropSession();
		Map<String, Object> manifest = eventOfType(p, "drop_trade_clip");
		assertEquals("the remainder is flushed as a third segment", 3, manifest.get("segments"));
		assertEquals(95, manifest.get("frames"));
	}

	@Test
	public void theManifestNamesItsUploadCountsAsAnEmitTimeSNAPSHOT() throws Exception
	{
		// FOUND IN LIVE DATA 2026-09-20, on a real session: segments 5, uploaded 3, failed 0. The
		// arithmetic does not close, because uploads are async and two segments were still on the
		// wire when the row was emitted. Waiting for them would block the client thread on a network
		// round trip and would publish nothing at all for a client that logs out after a trade.
		//
		// So the row states what it knows AT EMIT TIME, says so in the field names, and declares the
		// in-flight remainder. `segments` stays the authoritative total; the stitcher compares
		// against what actually reached R2.
		AccountConnectPlugin p = plugin();
		dropAction(p);
		for (int i = 0; i < 45; i++)		// one full segment plus a remainder
		{
			p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8, (byte) i}, 1_000L + i);
		}
		p.interruptDropSession();

		Map<String, Object> m = eventOfType(p, "drop_trade_clip");
		assertNotNull(m);
		assertEquals("two segments declared", 2, m.get("segments"));
		assertNotNull("the snapshot is named as one", m.get("segments_uploaded_at_emit"));
		assertNotNull(m.get("segments_failed_at_emit"));
		assertNull("the old ambiguous names must be gone", m.get("segments_uploaded"));
		assertNull(m.get("segments_failed"));
		// No executor in this harness, so both segments count as failed rather than in flight, and
		// the remainder is 0. What is pinned is the NAMING and the arithmetic, not the values.
		int declared = (Integer) m.get("segments");
		int sent = (Integer) m.get("segments_uploaded_at_emit");
		int failed = (Integer) m.get("segments_failed_at_emit");
		Object flight = m.get("segments_in_flight_at_emit");
		int inFlight = flight == null ? 0 : (Integer) flight;
		assertEquals("declared = sent + failed + in-flight, always", declared, sent + failed + inFlight);
	}

	@Test
	public void acceptingAFrameWithNoSessionIsASafeNoOp() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.acceptDropFrame(new byte[]{(byte) 0xff, (byte) 0xd8}, 1_000L);
		assertNull(get(p, "dropSegmenter"));
		assertTrue(p.pendingEvents.isEmpty());
	}

	// ---- candidate resolution through the plugin's own emit ----

	@Test
	public void theRemovalRowReportsResolvedWhenOneCandidateIsOnTheTile() throws Exception
	{
		// Driven through DropCandidates exactly as emitGroundRemoval does, because observedPlayers()
		// needs a live client. What this pins is the FIELD NAMES the row must carry, which a
		// downstream reader depends on.
		List<Map<String, Object>> c = DropCandidates.candidatesAt(
			java.util.Arrays.asList(new DropCandidates.Observed("Customer", 3200, 3400, 0, 90)),
			3200, 3400, 0);
		String resolved = DropCandidates.resolveCounterparty(c);
		assertEquals("Customer", resolved);
		assertEquals(DropCandidates.STATUS_RESOLVED, DropCandidates.statusFor(c, resolved));
	}

	/**
	 * DEFECT 4 (security review, 2026-09-20): the session id must fit every downstream limit.
	 *
	 * The id travels into the R2 key, and the staff-ops stitcher puts it inside a D1 `LIKE` pattern.
	 * D1 refuses a pattern over 50 characters, so a long id silently broke the consumer. The fix is
	 * a SHORTER id at the source, not a wider limit downstream.
	 */
	@Test
	public void theSessionIdFitsEveryDownstreamLimit()
	{
		for (int i = 0; i < 200; i++)
		{
			String id = AccountConnectPlugin.DROP_SESSION_ID_MAX > 0
				? newIdForTest() : "";
			assertTrue("id '" + id + "' is " + id.length() + " chars, max is "
					+ AccountConnectPlugin.DROP_SESSION_ID_MAX,
				id.length() <= AccountConnectPlugin.DROP_SESSION_ID_MAX);
			// The server sanitizes to [a-z0-9_-]. An id that loses characters there would stop
			// matching the manifest the stitcher joins on.
			assertTrue("id '" + id + "' must survive the server's key sanitizer unchanged",
				id.matches("^[a-z0-9_-]+$"));
			// And the D1 LIKE pattern the stitcher builds must stay legal.
			String pattern = "%\"drop_session_id\":\"" + id + "\"%";
			assertTrue("LIKE pattern is " + pattern.length() + " chars, D1 allows 50",
				pattern.length() <= 50);
		}
	}

	/** The plugin's cap must equal the server's, or one of them silently truncates the other's id. */
	@Test
	public void thePluginAndServerAgreeOnTheIdLength()
	{
		assertEquals(24, AccountConnectPlugin.DROP_SESSION_ID_MAX);
	}

	private static String newIdForTest()
	{
		String id = Long.toHexString(System.currentTimeMillis())
			+ Integer.toHexString(java.util.concurrent.ThreadLocalRandom.current().nextInt(1 << 24));
		return id.length() > AccountConnectPlugin.DROP_SESSION_ID_MAX
			? id.substring(0, AccountConnectPlugin.DROP_SESSION_ID_MAX) : id;
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Bank move capture — ONE bank_session per bank session, carrying the GROSS per-item deposits and
 * withdrawals seen across every bank container change, plus complete (closed normally) and truncated.
 * Bank transfers fire no trade / GE / store event, so this is the only event-plane record of what left or
 * entered the bank (the audit gap seen on regardo's session: 2 Twisted bows withdrawn, zero events). The
 * 0.7.14 build diffed only open against close, so a deposit and a withdraw of the same item inside one
 * session cancelled out and disappeared. Logic proven against mocked ItemContainers; container timing at
 * real WidgetLoaded / WidgetClosed is runtime-only (the rig bank deposit + withdraw is the field check).
 */
public class BankMoveCaptureTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int BANK_GROUP = 12;	// InterfaceID.BANKMAIN

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	/** Mock ItemContainer whose getItems() returns the given [id,qty] items (Item is final — construct it). */
	private static ItemContainer containerOf(int[]... items)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] arr = new Item[items.length];
		for (int i = 0; i < items.length; i++)
		{
			arr[i] = new Item(items[i][0], items[i][1]);
		}
		when(c.getItems()).thenReturn(arr);
		return c;
	}

	private static final class Rig
	{
		final AccountConnectPlugin plugin;
		final Client client;

		Rig(AccountConnectPlugin plugin, Client client)
		{
			this.plugin = plugin;
			this.client = client;
		}

		/** The bank opens reading {@code bank}. */
		void open(ItemContainer bank)
		{
			when(client.getItemContainer(InventoryID.BANK)).thenReturn(bank);
			plugin.handleCaptureOnOpenWidgetLoaded(BANK_GROUP);
		}

		/** A bank container change (a deposit or a withdraw lands). */
		void change(ItemContainer bank)
		{
			when(client.getItemContainer(InventoryID.BANK)).thenReturn(bank);
			plugin.handleBankContainerChanged(bank);
		}

		void close()
		{
			plugin.handleBankWidgetClosed(BANK_GROUP);
		}

		void state(GameState s)
		{
			GameStateChanged e = new GameStateChanged();
			e.setGameState(s);
			plugin.onGameStateChanged(e);
		}

		List<Map<String, Object>> sessions()
		{
			List<Map<String, Object>> out = new ArrayList<>();
			for (Map<String, Object> e : plugin.pendingEvents)
			{
				if ("bank_session".equals(e.get("type")))
				{
					out.add(e);
				}
			}
			return out;
		}
	}

	private static Rig rig() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		inject(plugin, "client", client);
		return new Rig(plugin, client);
	}

	@SuppressWarnings("unchecked")
	private static Map<Integer, Long> list(Map<String, Object> ev, String key)
	{
		Map<Integer, Long> m = new LinkedHashMap<>();
		for (Map<String, Object> it : (List<Map<String, Object>>) ev.get(key))
		{
			m.put((Integer) it.get("id"), (Long) it.get("qty"));
		}
		return m;
	}

	// ---- the three required cases ----

	/** Deposit then withdraw the SAME item in one session: both movements survive (net would be zero). */
	@Test
	public void depositThenWithdrawOfTheSameItemKeepsBothMovements() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}, new int[]{303, 1}));
		r.change(containerOf(new int[]{995, 1000}, new int[]{303, 2}));	// deposit 1 net
		r.change(containerOf(new int[]{995, 1000}, new int[]{303, 1}));	// withdraw 1 net
		r.close();
		List<Map<String, Object>> s = r.sessions();
		assertEquals("exactly one summary per session", 1, s.size());
		assertEquals(Long.valueOf(1), list(s.get(0), "deposited").get(303));
		assertEquals(Long.valueOf(1), list(s.get(0), "withdrawn").get(303));
		assertEquals(true, s.get(0).get("complete"));
		assertNull(s.get(0).get("truncated"));
	}

	/** An item absent at open, deposited and withdrawn again, is still both movements. */
	@Test
	public void aNewItemDepositedAndWithdrawnAgainKeepsBothMovements() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}));
		r.change(containerOf(new int[]{995, 1000}, new int[]{385, 50}));
		r.change(containerOf(new int[]{995, 1000}));
		r.close();
		Map<String, Object> s = r.sessions().get(0);
		assertEquals(Long.valueOf(50), list(s, "deposited").get(385));
		assertEquals(Long.valueOf(50), list(s, "withdrawn").get(385));
	}

	/** First open after login with the bank not loaded yet: the first contents are a baseline, not a deposit. */
	@Test
	public void firstOpenAfterLoginNeverLooksLikeAWholeBankDeposit() throws Exception
	{
		Rig r = rig();
		r.state(GameState.LOGGED_IN);
		r.open(null);		// unloaded at open
		r.change(containerOf(new int[]{995, 1_000_000}, new int[]{20997, 1}, new int[]{385, 200}));
		r.close();
		assertTrue("no whole-bank deposit", r.sessions().isEmpty());

		Rig r2 = rig();
		r2.open(containerOf());	// empty (not yet populated) at open
		r2.change(containerOf(new int[]{995, 1_000_000}, new int[]{20997, 1}));	// baseline
		r2.change(containerOf(new int[]{995, 1_000_000}, new int[]{20997, 1}, new int[]{385, 50}));	// real
		r2.close();
		assertEquals(1, r2.sessions().size());
		Map<Integer, Long> dep = list(r2.sessions().get(0), "deposited");
		assertEquals("only the real deposit", 1, dep.size());
		assertEquals(Long.valueOf(50), dep.get(385));
	}

	/** Hop, logout and disconnect before the close: the session is marked incomplete; nothing is invented. */
	@Test
	public void anInterruptedSessionIsIncompleteAndCarriesOnlyWhatWasSeen() throws Exception
	{
		for (GameState s : new GameState[]{GameState.HOPPING, GameState.LOGIN_SCREEN, GameState.CONNECTION_LOST})
		{
			Rig r = rig();
			r.open(containerOf(new int[]{995, 1000}, new int[]{303, 1}));
			r.change(containerOf(new int[]{995, 1000}));	// withdrew the net
			// the bank still reads a different state when the session breaks; it must NOT be diffed
			ItemContainer unseen = containerOf(new int[]{995, 5});
			when(r.client.getItemContainer(InventoryID.BANK)).thenReturn(unseen);
			r.state(s);
			List<Map<String, Object>> sess = r.sessions();
			assertEquals(s + ": one summary", 1, sess.size());
			assertEquals(s + ": incomplete", false, sess.get(0).get("complete"));
			assertEquals(s + ": the seen withdraw", Long.valueOf(1), list(sess.get(0), "withdrawn").get(303));
			assertNull(s + ": no coins move invented from the unseen state", list(sess.get(0), "withdrawn").get(995));
			assertTrue(s + ": nothing deposited", list(sess.get(0), "deposited").isEmpty());
			assertNull(s + ": session cleared", field(r.plugin, "bankAtOpen"));
			r.close();	// a late close after the break must not emit a second row
			assertEquals(s + ": no second row", 1, r.sessions().size());
		}
	}

	/** A re-open while a session is still running (close never seen) ends the old one as incomplete. */
	@Test
	public void aReopenEndsTheUnclosedSessionAsIncomplete() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}, new int[]{303, 1}));
		r.change(containerOf(new int[]{995, 1000}));
		r.open(containerOf(new int[]{995, 1000}));
		assertEquals(1, r.sessions().size());
		assertEquals(false, r.sessions().get(0).get("complete"));
	}

	/** Review M2: a bank close while the client is hopping/logging out is incomplete, not a close. */
	@Test
	public void aCloseDuringAHopIsIncompleteAndDoesNotReadTheTeardownBank() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}, new int[]{303, 1}));
		r.change(containerOf(new int[]{995, 1000}));
		ItemContainer teardown = containerOf(new int[]{995, 5});
		when(r.client.getItemContainer(InventoryID.BANK)).thenReturn(teardown);
		when(r.client.getGameState()).thenReturn(GameState.HOPPING);
		r.plugin.onWidgetClosed(widgetClosed(true));
		assertEquals(1, r.sessions().size());
		assertEquals(false, r.sessions().get(0).get("complete"));
		assertNull("the teardown read is not diffed", list(r.sessions().get(0), "withdrawn").get(995));
	}

	/**
	 * Rig 2026-09-27: an ordinary X-button bank close arrives as WidgetClosed(unload=true). While logged in
	 * that is a normal, COMPLETE close.
	 */
	@Test
	public void anOrdinaryCloseWithUnloadTrueIsComplete() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}, new int[]{1511, 1}));
		r.change(containerOf(new int[]{995, 1000}, new int[]{1511, 2}));
		r.change(containerOf(new int[]{995, 1000}, new int[]{1511, 1}));
		when(r.client.getGameState()).thenReturn(GameState.LOGGED_IN);
		r.plugin.onWidgetClosed(widgetClosed(true));
		assertEquals(1, r.sessions().size());
		assertEquals(true, r.sessions().get(0).get("complete"));
	}

	private static net.runelite.api.events.WidgetClosed widgetClosed(boolean unload)
	{
		return new net.runelite.api.events.WidgetClosed(BANK_GROUP, 0, unload);
	}

	/** Review M1: a disabled plugin keeps no bank session that a later account's bank could be diffed against. */
	@Test
	public void shutDownDiscardsTheBankSessionWithoutARow() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}, new int[]{303, 1}));
		r.change(containerOf(new int[]{995, 1000}));
		r.plugin.shutDown();
		r.change(containerOf(new int[]{4151, 1}));		// another account's bank, after re-enable
		r.open(containerOf(new int[]{4151, 1}));
		r.close();
		assertTrue("nothing emitted, nothing mixed", r.sessions().isEmpty());
	}

	/** Review L1: moves between the last change and a re-open are kept in the incomplete row. */
	@Test
	public void aReopenKeepsMovesSeenOnlyInTheReopenRead() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}, new int[]{303, 1}));
		r.open(containerOf(new int[]{995, 1000}));	// 303 left before the re-open, no change event seen
		assertEquals(1, r.sessions().size());
		assertEquals(Long.valueOf(1), list(r.sessions().get(0), "withdrawn").get(303));
	}

	// ---- budget, shape and prior behaviour ----

	@Test
	public void manyChangesStillEmitOneSummaryWithGrossTotals() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}));
		for (int i = 0; i < 20; i++)
		{
			r.change(containerOf(new int[]{995, 900}));
			r.change(containerOf(new int[]{995, 1000}));
		}
		r.close();
		assertEquals("one event for 40 container changes", 1, r.plugin.pendingEvents.size());
		Map<String, Object> s = r.sessions().get(0);
		assertEquals(Long.valueOf(2000), list(s, "withdrawn").get(995));
		assertEquals(Long.valueOf(2000), list(s, "deposited").get(995));
	}

	@Test
	public void theItemListsAreCappedAndMarkedTruncated() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1}));
		int n = AccountConnectPlugin.BANK_SESSION_ITEM_CAP + 5;
		int[][] items = new int[n + 1][];
		items[0] = new int[]{995, 1};
		for (int i = 1; i <= n; i++)
		{
			items[i] = new int[]{10000 + i, 1};
		}
		r.change(containerOf(items));
		r.close();
		Map<String, Object> s = r.sessions().get(0);
		assertEquals(AccountConnectPlugin.BANK_SESSION_ITEM_CAP, list(s, "deposited").size());
		assertEquals(true, s.get("truncated"));
	}

	@Test
	public void aWithdrawSeenOnlyAtCloseIsStillCounted() throws Exception
	{
		// open: 3 Twisted bows + 1000 coins; close reads 1 bow -> 2 bows withdrawn (no change event seen).
		Rig r = rig();
		r.open(containerOf(new int[]{20997, 3}, new int[]{995, 1000}));
		ItemContainer atClose = containerOf(new int[]{20997, 1}, new int[]{995, 1000});
		when(r.client.getItemContainer(InventoryID.BANK)).thenReturn(atClose);
		r.close();
		Map<String, Object> s = r.sessions().get(0);
		assertEquals(Long.valueOf(2), list(s, "withdrawn").get(20997));
		assertTrue(list(s, "deposited").isEmpty());
		assertNull("bankAtOpen cleared after close", field(r.plugin, "bankAtOpen"));
	}

	/** A transient empty read mid-session is not a whole-bank withdraw followed by a whole-bank deposit. */
	@Test
	public void aTransientEmptyReadFabricatesNothing() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{995, 1000}, new int[]{20997, 1}));
		r.change(containerOf());
		r.change(containerOf(new int[]{995, 1000}, new int[]{20997, 1}));
		r.close();
		assertTrue("no movement invented", r.sessions().isEmpty());
	}

	@Test
	public void noChangeEmitsNothing() throws Exception
	{
		Rig r = rig();
		r.open(containerOf(new int[]{1, 10}));
		r.change(containerOf(new int[]{1, 10}));
		r.close();
		assertTrue(r.plugin.pendingEvents.isEmpty());
