package com.osrsbestinslot.export;

import com.sun.net.httpserver.HttpServer;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import okhttp3.OkHttpClient;
import org.junit.After;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Store-clip chunk RETRY (finding F-A3, 2026-09-25). One failed POST used to lose the whole chunk
 * silently. These tests drive the real submitStoreClipUpload against a local HTTP stub, with the
 * retry delay seam recording the requested wait and running the retry at once.
 */
public class StoreClipRetryTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";
	private static final Pattern CAPTURED_AT = Pattern.compile("name=\"captured_at\"\\r\\n(?:[^\\r\\n]*\\r\\n)*\\r\\n(\\d+)");

	private HttpServer server;
	private final Map<String, AtomicInteger> requestsPerChunk = new ConcurrentHashMap<>();
	private final Map<String, AtomicInteger> storedPerChunk = new ConcurrentHashMap<>();
	private final AtomicInteger totalRequests = new AtomicInteger();

	/** A reply: status, body, optional Retry-After. */
	private static final class Reply
	{
		final int code;
		final String body;
		final String retryAfter;

		Reply(int code, String body, String retryAfter)
		{
			this.code = code;
			this.body = body;
			this.retryAfter = retryAfter;
		}
	}

	private static class RecordingPlugin extends AccountConnectPlugin
	{
		final List<Long> delays = Collections.synchronizedList(new ArrayList<>());

		@Override
		void scheduleClipRetry(Runnable retry, long delayMs)
		{
			delays.add(delayMs);
			retry.run();
		}
	}

	@After
	public void stop()
	{
		if (server != null)
		{
			server.stop(0);
		}
	}

	/** Start a stub; `policy` maps (captured_at, attempt number from 1) to the reply. */
	private String startServer(java.util.function.BiFunction<String, Integer, Reply> policy) throws Exception
	{
		server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", exchange ->
		{
			String body = new String(readAll(exchange.getRequestBody()), StandardCharsets.ISO_8859_1);
			Matcher m = CAPTURED_AT.matcher(body);
			String key = m.find() ? m.group(1) : "?";
			int n = requestsPerChunk.computeIfAbsent(key, k -> new AtomicInteger()).incrementAndGet();
			totalRequests.incrementAndGet();
			Reply r = policy.apply(key, n);
			if (r.code == 200 && !r.body.contains("dropped"))
			{
				storedPerChunk.computeIfAbsent(key, k -> new AtomicInteger()).incrementAndGet();
			}
			if (r.retryAfter != null)
			{
				exchange.getResponseHeaders().add("Retry-After", r.retryAfter);
			}
			byte[] resp = r.body.getBytes(StandardCharsets.UTF_8);
			exchange.sendResponseHeaders(r.code, resp.length);
			exchange.getResponseBody().write(resp);
			exchange.close();
		});
		server.start();
		return "http://127.0.0.1:" + server.getAddress().getPort() + "/wp-json/osrsbis/v1";
	}

	private static RecordingPlugin plugin(String base) throws Exception
	{
		RecordingPlugin p = new RecordingPlugin();
		inject(p, "config", config(base));
		inject(p, "executor", Executors.newSingleThreadScheduledExecutor());
		inject(p, "okHttpClient", new OkHttpClient());
		return p;
	}

	/** `n` frames, two chunks when n > CLIP_CHUNK_FRAMES, chunk first-frame times 1s apart. */
	private static void upload(AccountConnectPlugin p, int n)
	{
		List<byte[]> frames = new ArrayList<>();
		List<Long> times = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			frames.add(new byte[]{(byte) 0xFF, (byte) 0xD8, (byte) i, 1, 2, 3});
			times.add(1_700_000_000_000L + (i / AccountConnectPlugin.CLIP_CHUNK_FRAMES) * 1000L + i);
		}
		p.submitStoreClipUpload(frames, times);
	}

	private static void awaitFinished(AccountConnectPlugin p, int chunks) throws InterruptedException
	{
		long end = System.currentTimeMillis() + 20_000L;
		while (p.clipChunksSent.get() + p.clipChunksLost.get() < chunks
			&& System.currentTimeMillis() < end)
		{
			Thread.sleep(20);
		}
		Thread.sleep(200);	// let any wrong extra retry land, so it is counted
	}

	/** 500 then 200: every chunk is stored exactly once, and its bytes are released. */
	@Test
	public void aChunkThatFailsWith500IsRetriedAndStoredExactlyOnce() throws Exception
	{
		String base = startServer((key, attempt) -> attempt == 1
			? new Reply(500, "{\"ok\":false,\"error\":\"Storage failed.\"}", null)
			: new Reply(200, "{\"ok\":true,\"id\":1}", null));
		RecordingPlugin p = plugin(base);
		upload(p, AccountConnectPlugin.CLIP_CHUNK_FRAMES + 5);	// two chunks
		awaitFinished(p, 2);

		assertEquals("two chunks, two distinct captured_at values", 2, requestsPerChunk.size());
		for (Map.Entry<String, AtomicInteger> e : requestsPerChunk.entrySet())
		{
			assertEquals("chunk " + e.getKey() + ": one failed POST then one retry", 2, e.getValue().get());
			assertEquals("chunk " + e.getKey() + " must be stored exactly once",
				1, storedPerChunk.get(e.getKey()).get());
		}
		assertEquals("both chunks stored", 2, p.clipChunksSent.get());
		assertEquals("nothing lost", 0, p.clipChunksLost.get());
		assertEquals("retry bytes must be released", 0L, p.clipRetryHeldBytes.get());
		assertEquals("first retry waits the first ladder step",
			AccountConnectPlugin.CLIP_CHUNK_RETRY_DELAYS_MS[0], (long) p.delays.get(0));
	}

	/** Every attempt 503: give up after CLIP_CHUNK_ATTEMPTS, and release the bytes. */
	@Test
	public void aChunkGivesUpAfterTheBoundedAttemptsAndReleasesItsMemory() throws Exception
	{
		String base = startServer((key, attempt) -> new Reply(503, "{}", null));
		RecordingPlugin p = plugin(base);
		upload(p, 3);
		awaitFinished(p, 1);

		assertEquals("exactly CLIP_CHUNK_ATTEMPTS POSTs", AccountConnectPlugin.CLIP_CHUNK_ATTEMPTS, totalRequests.get());
		assertEquals("the chunk is counted lost", 1, p.clipChunksLost.get());
		assertEquals("nothing stored", 0, p.clipChunksSent.get());
		assertEquals("retry memory released after giving up", 0L, p.clipRetryHeldBytes.get());
		List<Long> expected = new ArrayList<>();
		for (long d : AccountConnectPlugin.CLIP_CHUNK_RETRY_DELAYS_MS)
		{
			expected.add(d);
		}
		assertEquals("backoff ladder", expected, p.delays);
		long sum = 0;
		for (long d : AccountConnectPlugin.CLIP_CHUNK_RETRY_DELAYS_MS)
		{
			sum += d;
		}
		assertTrue("the retry window must stay bounded (waits " + sum + "ms)", sum <= 10 * 60_000L);
		assertEquals("one delay per retry", AccountConnectPlugin.CLIP_CHUNK_ATTEMPTS - 1,
			AccountConnectPlugin.CLIP_CHUNK_RETRY_DELAYS_MS.length);
	}

	/** A network failure (nothing listening) is retried too. */
	@Test
	public void aNetworkFailureIsRetried() throws Exception
	{
		int port;
		try (ServerSocket s = new ServerSocket(0))
		{
			port = s.getLocalPort();
		}
		RecordingPlugin p = plugin("http://127.0.0.1:" + port);
		upload(p, 3);
		awaitFinished(p, 1);

		assertEquals("a refused connection must be retried the full ladder",
			AccountConnectPlugin.CLIP_CHUNK_ATTEMPTS - 1, p.delays.size());
		assertEquals(1, p.clipChunksLost.get());
		assertEquals(0L, p.clipRetryHeldBytes.get());
	}

	/** A 400 fails the same way forever: exactly one POST, no retry. */
	@Test
	public void a400IsNotRetried() throws Exception
	{
		String base = startServer((key, attempt) -> new Reply(400, "{\"ok\":false,\"error\":\"Frame count mismatch.\"}", null));
		RecordingPlugin p = plugin(base);
		upload(p, 3);
		awaitFinished(p, 1);

		assertEquals("a 400 must be sent once", 1, totalRequests.get());
		assertTrue("no retry may be scheduled for a 400", p.delays.isEmpty());
		assertEquals(1, p.clipChunksLost.get());
		assertEquals(0L, p.clipRetryHeldBytes.get());
	}

	/** A 200 {"dropped":...} is a deliberate refusal: not retried, not counted as stored. */
	@Test
	public void a200RefusalIsNotRetried() throws Exception
	{
		String base = startServer((key, attempt) -> new Reply(200, "{\"ok\":true,\"dropped\":\"not_staff\"}", null));
		RecordingPlugin p = plugin(base);
		upload(p, 3);
		long end = System.currentTimeMillis() + 10_000L;
		while (totalRequests.get() < 1 && System.currentTimeMillis() < end)
		{
			Thread.sleep(20);
		}
		Thread.sleep(500);

		assertEquals("a refusal must be sent once", 1, totalRequests.get());
		assertTrue("no retry for a refusal", p.delays.isEmpty());
		assertEquals("a refusal is not a store", 0, p.clipChunksSent.get());
		assertEquals("a refusal is not a loss either", 0, p.clipChunksLost.get());
	}

	/** 429 with Retry-After: the retry waits at least that long. */
	@Test
	public void a429HonoursRetryAfter() throws Exception
	{
		String base = startServer((key, attempt) -> attempt == 1
			? new Reply(429, "{\"ok\":false}", "100")
			: new Reply(200, "{\"ok\":true,\"id\":2}", null));
		RecordingPlugin p = plugin(base);
		upload(p, 3);
		awaitFinished(p, 1);

		assertEquals("one retry", 1, p.delays.size());
		assertEquals("the retry waits the server's Retry-After", 100_000L, (long) p.delays.get(0));
		assertEquals(1, p.clipChunksSent.get());
		assertEquals(0L, p.clipRetryHeldBytes.get());
	}

	/** 429 without Retry-After falls back to the ladder; one longer than the window gives up. */
	@Test
	public void a429WithoutOrWithAnOverlongRetryAfter() throws Exception
	{
		String base = startServer((key, attempt) -> attempt == 1
			? new Reply(429, "{}", null)
			: new Reply(200, "{\"ok\":true}", null));
		RecordingPlugin p = plugin(base);
		upload(p, 3);
		awaitFinished(p, 1);
		assertEquals(AccountConnectPlugin.CLIP_CHUNK_RETRY_DELAYS_MS[0], (long) p.delays.get(0));
		assertEquals(1, p.clipChunksSent.get());
		stop();

		requestsPerChunk.clear();
		totalRequests.set(0);
		String base2 = startServer((key, attempt) -> new Reply(429, "{}", "3600"));
		RecordingPlugin p2 = plugin(base2);
		upload(p2, 3);
		awaitFinished(p2, 1);
		assertEquals("an hour-long Retry-After is not waited out with the bytes held", 1, totalRequests.get());
		assertTrue(p2.delays.isEmpty());
		assertEquals(1, p2.clipChunksLost.get());
		assertEquals(0L, p2.clipRetryHeldBytes.get());
	}

	/** With the retry byte budget full, a failing chunk is given up instead of held. */
	@Test
	public void aFullRetryBudgetGivesUpInsteadOfHolding() throws Exception
	{
		String base = startServer((key, attempt) -> new Reply(500, "{}", null));
		RecordingPlugin p = plugin(base);
		p.clipRetryHeldBytes.set(AccountConnectPlugin.CLIP_RETRY_BYTE_BUDGET);
		upload(p, 3);
		awaitFinished(p, 1);

		assertEquals("no room: one POST, no retry", 1, totalRequests.get());
		assertTrue(p.delays.isEmpty());
		assertEquals(1, p.clipChunksLost.get());
		assertEquals("the budget is not exceeded", AccountConnectPlugin.CLIP_RETRY_BYTE_BUDGET, p.clipRetryHeldBytes.get());
		assertTrue("the budget is bounded to a small number of visits",
			AccountConnectPlugin.CLIP_RETRY_BYTE_BUDGET <= 3L * AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
	}

	/** A retry after the user linked another token is dropped, never filed under the new token. */
	@Test
	public void aRetryAfterATokenSwapIsNotSent() throws Exception
	{
		String base = startServer((key, attempt) -> new Reply(500, "{}", null));
		final String[] tok = {TEST_TOKEN};
		RecordingPlugin p = new RecordingPlugin()
		{
			@Override
			void scheduleClipRetry(Runnable retry, long delayMs)
			{
				delays.add(delayMs);
				tok[0] = "fedcba9876543210".repeat(2);
				retry.run();
			}
		};
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return tok[0];
			}

			@Override
			public String apiBaseUrl()
			{
				return base;
			}
		});
		inject(p, "executor", Executors.newSingleThreadScheduledExecutor());
		inject(p, "okHttpClient", new OkHttpClient());
		upload(p, 3);
		awaitFinished(p, 1);

		assertEquals("the retry must not be sent under the new token", 1, totalRequests.get());
		assertEquals(1, p.clipChunksLost.get());
		assertEquals(0L, p.clipRetryHeldBytes.get());
	}

	// ---- helpers ----

	private static AccountConnectConfig config(String baseUrl)
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}

			@Override
			public String apiBaseUrl()
			{
				return baseUrl;
			}
		};
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static byte[] readAll(InputStream in) throws java.io.IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] chunk = new byte[8192];
		int n;
		while ((n = in.read(chunk)) != -1)
		{
			out.write(chunk, 0, n);
		}
		return out.toByteArray();
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * WAVE 1b — trade received[] (the counterparty's side). There is NO counterparty ItemContainer, so the
 * received items are read from the confirm-screen "You will receive" widget (packed component 21889048,
 * javap-verified: net.runelite.api.gameval.InterfaceID$Tradeconfirm.YOU_WILL_RECEIVE).
 *
 * These tests cover the emit wiring and the widget-parse logic against MOCKED widgets. They do NOT — and
 * cannot — verify the real confirm-screen structure: whether YOU_WILL_RECEIVE exposes item children vs a
 * text summary, and whether it is populated at WidgetLoaded time, both need one live two-sided trade.
 */
public class Wave1bTradeReceivedTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";
	// javap-verified packed component id (group 334 << 16 | child 24) for Tradeconfirm.YOU_WILL_RECEIVE.
	private static final int RECEIVE_COMPONENT = 21889048;

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	@Test
	public void tradeEventCarriesStructuredReceivedItems() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "pendingTradeGiven", itemList(20997, 1));      // twisted bow given
		inject(plugin, "pendingCounterparty", "Bob");
		inject(plugin, "pendingTradeReceived", itemList(995, 5000));  // 5000 coins received

		plugin.emitTradeEvent();

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("trade", ev.get("type"));
		assertEquals("Bob", ev.get("counterparty"));
		assertTrue("given present", ev.containsKey("given"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> received = (List<Map<String, Object>>) ev.get("received");
		assertEquals(1, received.size());
		assertEquals(995, received.get(0).get("id"));
		assertEquals(5000, received.get(0).get("qty"));
		assertFalse("no text fallback when structured items exist", ev.containsKey("received_text"));
	}

	@Test
	public void tradeEventFallsBackToReceivedText() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "pendingTradeGiven", itemList(20997, 1));
		inject(plugin, "pendingTradeReceived", new ArrayList<Map<String, Object>>()); // empty structured read
		inject(plugin, "pendingReceivedText", "Blood rune x 100");

		plugin.emitTradeEvent();

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("Blood rune x 100", ev.get("received_text"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> received = (List<Map<String, Object>>) ev.get("received");
		assertTrue("received[] present but empty", received.isEmpty());
	}

	@Test
	public void tradeEventReceivedDefaultsToEmptyList() throws Exception
	{
		// Nothing captured for the received side (widget was absent): received[] must still be present + empty.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "pendingTradeGiven", itemList(20997, 1));

		plugin.emitTradeEvent();

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertTrue(ev.containsKey("received"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> received = (List<Map<String, Object>>) ev.get("received");
		assertTrue(received.isEmpty());
		assertFalse(ev.containsKey("received_text"));
	}

	@Test
	public void readReceivedOfferReadsItemChildren() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		Client client = mock(Client.class);
		Widget root = mock(Widget.class);
		Widget slotA = mock(Widget.class);
		Widget slotB = mock(Widget.class);
		Widget blank = mock(Widget.class); // an empty slot (id -1) must be skipped
		when(client.getWidget(RECEIVE_COMPONENT)).thenReturn(root);
		when(root.getChildren()).thenReturn(new Widget[]{slotA, slotB, blank});
		when(slotA.getItemId()).thenReturn(995);
		when(slotA.getItemQuantity()).thenReturn(5000);
		when(slotB.getItemId()).thenReturn(560);
		when(slotB.getItemQuantity()).thenReturn(100);
		when(blank.getItemId()).thenReturn(-1);
		inject(plugin, "client", client);

		List<Map<String, Object>> got = plugin.readReceivedOffer();
		assertEquals(2, got.size());
		assertEquals(995, got.get(0).get("id"));
		assertEquals(5000, got.get(0).get("qty"));
		assertEquals(560, got.get(1).get("id"));
		assertEquals(100, got.get(1).get("qty"));
	}

	@Test
	public void readReceivedOfferFallsToDynamicChildren() throws Exception
	{
		// getChildren() empty → the dynamic-child array is consulted instead.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		Client client = mock(Client.class);
		Widget root = mock(Widget.class);
		Widget slot = mock(Widget.class);
		when(client.getWidget(RECEIVE_COMPONENT)).thenReturn(root);
		when(root.getChildren()).thenReturn(new Widget[0]);
		when(root.getDynamicChildren()).thenReturn(new Widget[]{slot});
		when(slot.getItemId()).thenReturn(4151);
		when(slot.getItemQuantity()).thenReturn(1);
		inject(plugin, "client", client);

		List<Map<String, Object>> got = plugin.readReceivedOffer();
		assertEquals(1, got.size());
		assertEquals(4151, got.get(0).get("id"));
	}

	@Test
	public void readReceivedTextCapturesRawSummary() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		Client client = mock(Client.class);
		Widget root = mock(Widget.class);
		when(client.getWidget(RECEIVE_COMPONENT)).thenReturn(root);
		when(root.getText()).thenReturn("Blood rune x 100<br>Coins x 5,000"); // raw, tags intact
		inject(plugin, "client", client);

		String text = plugin.readReceivedText();
		assertEquals("Blood rune x 100<br>Coins x 5,000", text);
		// and the structured read finds no items on a text-only widget
		assertTrue(plugin.readReceivedOffer().isEmpty());
	}

	@Test
	public void readReceivedNullSafeWhenWidgetAbsent() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		Client client = mock(Client.class);
		when(client.getWidget(RECEIVE_COMPONENT)).thenReturn(null);
		inject(plugin, "client", client);

		assertTrue("no widget → empty structured read", plugin.readReceivedOffer().isEmpty());
		assertNull("no widget → null text", plugin.readReceivedText());
	}

	@Test
	public void readReceivedNullSafeWhenClientNull() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin(); // client not injected
		assertTrue(plugin.readReceivedOffer().isEmpty());
		assertNull(plugin.readReceivedText());
	}

	@Test
	public void resetTradeStateClearsReceived() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "pendingTradeReceived", itemList(995, 1));
		inject(plugin, "pendingReceivedText", "something");
		invokeReset(plugin);
		assertNull(field(plugin, "pendingTradeReceived"));
		assertNull(field(plugin, "pendingReceivedText"));
	}

	private static List<Map<String, Object>> itemList(int id, int qty)
	{
		List<Map<String, Object>> l = new ArrayList<>();
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("id", id);
		m.put("qty", qty);
		l.add(m);
		return l;
	}

	private static void invokeReset(AccountConnectPlugin plugin) throws Exception
	{
		java.lang.reflect.Method m = AccountConnectPlugin.class.getDeclaredMethod("resetTradeState");
		m.setAccessible(true);
		m.invoke(plugin);
	}

	private static Object field(AccountConnectPlugin plugin, String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;

/**
 * Regression guards for the two HIGH defects found by the 0.7.4 adversarial review. Both were
 * introduced BY 0.7.4 and neither was covered by the release's own tests — the suite was green while
 * both were live, which is why these exist.
 */
public class TradeLeakAndFlushWedgeTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int TRADE_MAIN_GROUP_ID = 335;

	private AccountConnectPlugin plugin;

	@Before
	public void setUp() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
	}

	private void inject(String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private Object get(String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private void configWith(String apiBaseUrl) throws Exception
	{
		AccountConnectConfig config = mock(AccountConnectConfig.class);
		when(config.linkToken()).thenReturn(TOKEN);
		when(config.apiBaseUrl()).thenReturn(apiBaseUrl);
		inject("config", config);
	}

	// ============================================================ FINDING 1 — cross-trade leak

	/**
	 * A trade that ends WITHOUT acceptance must not leak its counterparty or received items into the
	 * next trade's event.
	 *
	 * <p>The leak path: a decline routes through handleTradeChat, which early-returns when trade
	 * screenshots are off — the DEFAULT — so resetTradeState() never runs. handleTradeWidgetClosed only
	 * resets when tradeArmed, which is set at confirm-load with screenshots ON, so a trade abandoned at
	 * the first screen never arms either. 0.7.4's last-non-empty-wins poll then PRESERVES the stale
	 * items past a next partner who offers nothing — the classic gold-delivery shape — producing
	 * {@code counterparty=Alice, received=[Bob's item]}.
	 *
	 * <p>0.7.3 could not do this: it assigned the pendings unconditionally at confirm, so every trade
	 * overwrote the last. The fix clears them at 335-load, the one point guaranteed to run per trade.
	 */
	@Test
	public void a335LoadClearsStalePendingsFromAnAbandonedTrade() throws Exception
	{
		configWith("https://example.invalid/api");

		// Trade 1 with Bob ended without acceptance — pendings survive in the real leak scenario.
		List<Map<String, Object>> bobsOffer = new ArrayList<>();
		Map<String, Object> bandos = new LinkedHashMap<>();
		bandos.put("id", 11832);
		bandos.put("qty", 1);
		bobsOffer.add(bandos);
		inject("pendingCounterparty", "Bob");
		inject("pendingTradeReceived", bobsOffer);
		inject("pendingReceivedText", "Bandos chestplate x 1");

		// Trade 2 opens. The 335-load must wipe Bob's residue before any polling happens.
		plugin.handleActivityWidgetLoaded(TRADE_MAIN_GROUP_ID);

		assertNull("counterparty from the abandoned trade must not survive", get("pendingCounterparty"));
		assertNull("received items must not survive — this is the field the release exists to fix",
			get("pendingTradeReceived"));
		assertNull("the text fallback must not survive either", get("pendingReceivedText"));
		assertTrue("polling must still be armed for the new trade", plugin.tradeMainOpen);
	}

	@Test
	public void repeatedAbandonedTradesNeverAccumulateResidue() throws Exception
	{
		configWith("https://example.invalid/api");
		for (int i = 0; i < 3; i++)
		{
			inject("pendingCounterparty", "Ghost" + i);
			List<Map<String, Object>> junk = new ArrayList<>();
			Map<String, Object> it = new LinkedHashMap<>();
			it.put("id", 4151 + i);
			it.put("qty", 1);
			junk.add(it);
			inject("pendingTradeReceived", junk);

			plugin.handleActivityWidgetLoaded(TRADE_MAIN_GROUP_ID);

			assertNull("each new trade starts clean", get("pendingCounterparty"));
			assertNull(get("pendingTradeReceived"));
		}
	}

	// ============================================================ FINDING 2 — permanent flush wedge

	/**
	 * A throw between draining the buffer and enqueueing the request must not lose the batch, and must
	 * NEVER leave delivery permanently wedged.
	 *
	 * <p>{@code apiBaseUrl} is user-editable and {@code Request.Builder.url()} throws
	 * IllegalArgumentException on a malformed value — a pasted non-URL is enough. Before the guard, that
	 * threw AFTER the buffer was cleared and {@code eventPostInFlight} set, so the batch was lost and
	 * every later flush early-returned forever, silently, with no further log lines. 0.7.3 recovered as
	 * soon as the user fixed the typo; unguarded 0.7.4 would stay dead until a plugin restart.
	 */
	@Test
	public void aMalformedApiUrlRequeuesTheBatchAndDoesNotWedgeDelivery() throws Exception
	{
		configWith("not a url at all");

		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", "trade");
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}

		plugin.flushEvents();	// must not propagate

		synchronized (plugin.pendingEvents)
		{
			assertEquals("the batch must be preserved, not destroyed by the throw",
				1, plugin.pendingEvents.size());
		}
		assertFalse("the in-flight flag MUST be cleared, or every later flush early-returns forever",
			plugin.eventPostInFlight);
		assertTrue("the failure must arm the backoff like any other", plugin.eventRetryBackoffUntilMs > 0);
	}

	/**
	 * The recovery half: after the user CORRECTS the URL, delivery must resume. This is the difference
	 * between a transient config typo and a session-long silent outage.
	 */
	@Test
	public void deliveryResumesOnceTheUrlIsCorrected() throws Exception
	{
		configWith("not a url at all");
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", "trade");
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}
		plugin.flushEvents();
		assertFalse(plugin.eventPostInFlight);

		// User fixes the config; the next tick must actually attempt a send rather than early-return.
		configWith("http://127.0.0.1:1/api");	// refused connection, but a VALID url
		plugin.eventRetryBackoffUntilMs = 0L;
		plugin.flushEvents();

		// The batch left the buffer (a real attempt happened) or came back via onFailure — either way
		// the flag must not be stuck true, which is what "wedged" means.
		Thread.sleep(500);
		assertFalse("delivery must not be permanently wedged after a corrected config",
			plugin.eventPostInFlight);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.game.ItemManager;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Off-book value events: drop / pickup / alch (inventory-delta arm+resolve), death items_lost + death_kind,
 * and the looting-bag / seed-vault / group-storage snapshot blocks. Buffer-only (no live client for the emit
 * assertions); the menu-shape (esp. alch spell-on-item) and death-tick timing are flagged [verify in-client].
 */
public class OffBookEventsTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int COINS = 995;

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		};
	}

	// ---------- classifier ----------

	@Test
	public void classifiesDropTakeAndAlch()
	{
		assertEquals("drop", AccountConnectPlugin.offBookMenuAction(menu("Drop", "", 0)));
		assertEquals("pickup", AccountConnectPlugin.offBookMenuAction(menu("Take", "", 0)));
		// menu shape A: the spell name is on the option itself
		assertEquals("alch_high", AccountConnectPlugin.offBookMenuAction(menu("Cast High Level Alchemy", "", 0)));
		// menu shape B (the likely runtime shape): option "Cast", spell name in the target
		assertEquals("alch_low",
			AccountConnectPlugin.offBookMenuAction(menu("Cast", "<col=00ff00>Low Level Alchemy</col> -> Item", 0)));
		assertNull(AccountConnectPlugin.offBookMenuAction(menu("Wield", "", 0)));
		assertNull(AccountConnectPlugin.offBookMenuAction(menu("Drop-all", "", 0))); // not the bare "Drop"
	}

	// ---------- drop ----------

	@Test
	public void dropArmsThenResolvesOnlyViaGroundSpawn() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv = container(560, 5); // 5 death runes — build the stub before nesting it in when()
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv);
		when(client.getVarbitValue(Varbits.IN_WILDERNESS)).thenReturn(1);
		when(client.getTickCount()).thenReturn(10);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3100, 3900, 0)); // deep wild
		inject(plugin, "client", client);

		plugin.onMenuOptionClicked(menu("Drop", "", 560));
		AccountConnectPlugin.InvDeltaPending p = invDeltaPending(plugin);
		assertNotNull("drop must arm a pending", p);
		assertEquals("drop", p.base);
		assertEquals(560, p.item);
		assertEquals(5L, p.beforeCount);
		assertEquals(Boolean.TRUE, p.wilderness);
		assertTrue("drop defers emit", plugin.pendingEvents.isEmpty());

		// an inventory removal ALONE must never emit a drop (it could be a bank / destroy / equip)
		plugin.resolveInvDeltaPending(0L, 0L, 11);
		assertTrue("inventory delta alone never emits a drop", plugin.pendingEvents.isEmpty());
		assertNotNull("pending survives awaiting the ground spawn", invDeltaPending(plugin));

		// the ground spawn at our tile + the inventory loss together confirm the drop
		plugin.resolveDropPendingOnGroundSpawn(560, 0, 0L, 11);
		assertNull("pending consumed", invDeltaPending(plugin));
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("drop", e.get("type"));
		assertEquals(560, e.get("item"));
		assertEquals(5L, e.get("qty"));
		assertEquals(true, e.get("wilderness"));
		assertNotNull("drop carries a location", e.get("location"));
	}

	@Test
	public void dropOutsideWildernessFlagsFalse() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 526, null, 1L, 0L, null, Boolean.FALSE, 5));
		plugin.resolveDropPendingOnGroundSpawn(526, 1, 0L, 6);
		assertEquals(false, plugin.pendingEvents.get(0).get("wilderness"));
	}

	/**
	 * M3 core guarantee: an armed drop whose item leaves the inventory for a NON-drop reason (equip after a
	 * cancelled drop-warning, bank "Deposit inventory", a Destroy confirm) spawns NO ground item — so no drop
	 * event can be fabricated, no matter what the inventory does.
	 */
	@Test
	public void inventoryRemovalWithoutGroundSpawnNeverFabricatesDrop() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 20997, null, 1L, 0L, null, Boolean.FALSE, 5));
		// tbow leaves the inventory (equip / deposit / destroy) — inv-change path sees it, must not emit
		plugin.resolveInvDeltaPending(0L, 0L, 6);
		assertTrue("no fabricated drop", plugin.pendingEvents.isEmpty());
		// window passes with no ground spawn -> pending expires silently
		plugin.resolveInvDeltaPending(0L, 0L, 30);
		assertNull("stale drop pending expired", invDeltaPending(plugin));
		assertTrue(plugin.pendingEvents.isEmpty());
	}

	/**
	 * The reverse guard: a ground item appearing at our tile that we did NOT lose from the inventory
	 * (another player's drop becoming visible) must not resolve the pending.
	 */
	@Test
	public void groundSpawnWithoutInventoryLossDoesNotEmit() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 560, null, 5L, 0L, null, Boolean.FALSE, 5));
		// same item id spawns at our feet but our inventory still holds all 5 -> not our drop
		plugin.resolveDropPendingOnGroundSpawn(560, 0, 5L, 6);
		assertTrue("no emit without a matching inventory loss", plugin.pendingEvents.isEmpty());
		assertNotNull("pending kept (the real drop may still land)", invDeltaPending(plugin));
	}

	/**
	 * Death guard: dying spawns YOUR items on the ground at your tile WITH an inventory loss — exactly the
	 * dual drop signal. An armed drop pending must be killed by the death (the loss belongs to the death
	 * event's items_lost, not a fabricated player-initiated drop).
	 */
	@Test
	public void deathKillsArmedDropPendingSoDeathLootIsNotADrop() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv = container(20997, 1);
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3100, 3900, 0));
		inject(plugin, "client", client);
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 20997, null, 1L, 0L, null, Boolean.TRUE, 5));

		plugin.onActorDeath(new net.runelite.api.events.ActorDeath((net.runelite.api.Actor) player));
		assertNull("death disarms any pending drop/pickup/alch", invDeltaPending(plugin));

		// the death's ground spawns + inventory wipe must not resolve as a drop
		plugin.resolveDropPendingOnGroundSpawn(20997, 0, 0L, 6);
		assertTrue("no fabricated drop from death loot", plugin.pendingEvents.isEmpty());
	}

	/**
	 * Order-independence (verifier BLOCKING find): if the client processes the ground spawn BEFORE the
	 * inventory decrement, the spawn must record a corroboration and the later inventory-change path must
	 * complete the emit — otherwise every drop in that event order is silently missed with no retry.
	 */
	@Test
	public void spawnFirstThenInventoryLossStillEmitsDrop() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		AccountConnectPlugin.InvDeltaPending p =
			new AccountConnectPlugin.InvDeltaPending("drop", 560, null, 5L, 0L, null, Boolean.TRUE, 5);
		armPending(plugin, p);

		// spawn arrives while the inventory still shows the full count -> no emit yet, corroboration recorded
		plugin.resolveDropPendingOnGroundSpawn(560, 0, 5L, 6);
		assertTrue("no emit while the inventory loss is unconfirmed", plugin.pendingEvents.isEmpty());
		assertNotNull("pending kept", invDeltaPending(plugin));

		// the inventory decrement lands next -> the inv-change path completes the dual signal
		plugin.resolveInvDeltaPending(0L, 0L, 6);
		assertNull("pending consumed", invDeltaPending(plugin));
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("drop", e.get("type"));
		assertEquals(560, e.get("item"));
		assertEquals(5L, e.get("qty"));
		assertEquals(true, e.get("wilderness"));
	}

	/** A stale spawn corroboration must not pair with a much-later unrelated inventory removal. */
	@Test
	public void staleSpawnCorroborationDoesNotPairWithLateRemoval() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 560, null, 5L, 0L, null, Boolean.FALSE, 5));
		plugin.resolveDropPendingOnGroundSpawn(560, 0, 5L, 6); // corroborated at tick 6, no loss yet
		plugin.resolveInvDeltaPending(0L, 0L, 14); // loss lands 8 ticks later (bank deposit) -> too stale
		assertTrue("stale corroboration never pairs", plugin.pendingEvents.isEmpty());
	}

	/**
	 * Verifier minor: a SHRINKING nearby ground stack (another player looting it) is not our drop landing —
	 * only a fresh spawn or a GROWING stack corroborates.
	 */
	@Test
	public void shrinkingGroundStackDoesNotCorroborate() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		AccountConnectPlugin.InvDeltaPending p =
			new AccountConnectPlugin.InvDeltaPending("drop", 560, null, 5L, 0L, null, Boolean.FALSE, 5);
		armPending(plugin, p);
		// direct core call with grew=false must record nothing
		plugin.resolveDropPendingOnGroundSpawn(560, 0, 0L, 6, false);
		assertTrue("shrinking stack is never our drop", plugin.pendingEvents.isEmpty());
		assertEquals("no corroboration recorded", -1, p.spawnCorroboratedTick);
	}

	/** Death belt: while a death is settling, NO ground spawn may corroborate a drop (they're the death's items). */
	@Test
	public void spawnDuringDeathSettleNeverCorroborates() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 20997, null, 1L, 0L, null, Boolean.TRUE, 5));
		inject(plugin, "deathPending",
			new AccountConnectPlugin.DeathPending(null, "wilderness", new LinkedHashMap<>(), 5));
		plugin.resolveDropPendingOnGroundSpawn(20997, 0, 0L, 6); // the death's tbow hits the floor
		assertTrue("death-settle spawns never become drops", plugin.pendingEvents.isEmpty());
		assertNull("pending killed by the death belt", invDeltaPending(plugin));
	}

	/** Ownership discriminator: a ground item not owned by US can never corroborate our drop. */
	@Test
	public void foreignOwnedGroundItemNeverCorroborates() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv = container(560, 0); // build the stub before nesting it in when()
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv);
		when(client.getTickCount()).thenReturn(6);
		inject(plugin, "client", client);
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 560, null, 5L, 0L, null, Boolean.FALSE, 5));

		net.runelite.api.TileItem it = mock(net.runelite.api.TileItem.class);
		when(it.getId()).thenReturn(560);
		when(it.getOwnership()).thenReturn(net.runelite.api.TileItem.OWNERSHIP_OTHER);
		net.runelite.api.Tile tile = mock(net.runelite.api.Tile.class);
		when(tile.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));

		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(tile, it));
		assertTrue("foreign-owned pile rejected", plugin.pendingEvents.isEmpty());
		AccountConnectPlugin.InvDeltaPending p = invDeltaPending(plugin);
		assertNotNull("pending untouched", p);
		assertEquals("no corroboration recorded either", -1, p.spawnCorroboratedTick);
	}

	/**
	 * Drop row completeness (0.7.15): the drop row carries the PILE's exact tile (not the player's) and the
	 * world, so a staff card can locate it even when no ground_removed row follows.
	 */
	@Test
	public void dropRowCarriesThePileTileAndWorld() throws Exception
	{
		AccountConnectPlugin plugin = spawnRig(308, 0);
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 560, null, 1L, 0L, null, Boolean.FALSE, 5));
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(tileAt(3201, 3199), ownItem(560)));
		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("drop", e.get("type"));
		@SuppressWarnings("unchecked")
		Map<String, Object> tile = (Map<String, Object>) e.get("tile");
		assertNotNull("drop row carries the tile", tile);
		assertEquals("pile x, not the player's 3200", 3201, tile.get("x"));
		assertEquals("pile y, not the player's 3200", 3199, tile.get("y"));
		assertEquals(0, tile.get("plane"));
		assertEquals(308, e.get("world"));
		assertEquals(false, e.get("wilderness"));
	}

	/** Spawn BEFORE the inventory loss: the tile recorded at the spawn still reaches the drop row. */
	@Test
	public void dropRowCarriesTheTileWhenTheSpawnArrivesFirst() throws Exception
	{
		AccountConnectPlugin plugin = spawnRig(301, 1);
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 560, null, 1L, 0L, null, Boolean.FALSE, 5));
		plugin.onItemSpawned(new net.runelite.api.events.ItemSpawned(tileAt(3199, 3200), ownItem(560)));
		assertTrue("spawn first only corroborates", plugin.pendingEvents.isEmpty());
		plugin.resolveInvDeltaPending(0L, 0L, 7);
		assertEquals(1, plugin.pendingEvents.size());
		@SuppressWarnings("unchecked")
		Map<String, Object> tile = (Map<String, Object>) plugin.pendingEvents.get(0).get("tile");
		assertNotNull(tile);
		assertEquals(3199, tile.get("x"));
		assertEquals(3200, tile.get("y"));
		assertEquals(301, plugin.pendingEvents.get(0).get("world"));
	}

	/**
	 * Theft investigation M5 (event 40325): a stale armed drop of the same item sat ahead of a fresh one.
	 * The spawn found the stale one first, discarded it and stopped, so the fresh drop never got its spawn
	 * and no drop row was written, while the pile was tracked and later produced a ground_removed row.
	 */
	@Test
	public void aStaleDropOfTheSameItemDoesNotSwallowTheFreshDrop() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 995, null, 100L, 0L, null, Boolean.FALSE, 5));
		AccountConnectPlugin.InvDeltaPending fresh =
			new AccountConnectPlugin.InvDeltaPending("drop", 995, null, 100L, 0L, null, Boolean.FALSE, 40);
		appendPending(plugin, fresh);
		plugin.resolveDropPendingOnGroundSpawn(995, 0, 0L, 41);	// the fresh drop's spawn, loss visible
		assertEquals("the fresh drop is emitted", 1, plugin.pendingEvents.size());
		assertEquals("drop", plugin.pendingEvents.get(0).get("type"));
		assertEquals(100L, plugin.pendingEvents.get(0).get("qty"));
		assertNull("both pendings are gone: stale discarded, fresh consumed", invDeltaPending(plugin));
	}

	/** Same, spawn first: the fresh drop records the corroboration and emits when the loss lands. */
	@Test
	public void aStaleDropDoesNotSwallowTheFreshDropWhenTheSpawnArrivesFirst() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		armPending(plugin, new AccountConnectPlugin.InvDeltaPending("drop", 995, null, 100L, 0L, null, Boolean.FALSE, 5));
		AccountConnectPlugin.InvDeltaPending fresh =
			new AccountConnectPlugin.InvDeltaPending("drop", 995, null, 100L, 0L, null, Boolean.FALSE, 40);
		appendPending(plugin, fresh);
		plugin.resolveDropPendingOnGroundSpawn(995, 0, 100L, 41);	// spawn before the loss
		assertEquals(41, fresh.spawnCorroboratedTick);
		plugin.resolveInvDeltaPending(0L, 0L, 42);
		assertEquals(1, plugin.pendingEvents.size());
		assertEquals("drop", plugin.pendingEvents.get(0).get("type"));
	}

	private static void appendPending(AccountConnectPlugin plugin, AccountConnectPlugin.InvDeltaPending p)
		throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("invDeltaPendings");
		f.setAccessible(true);
		@SuppressWarnings("unchecked")
		java.util.Deque<AccountConnectPlugin.InvDeltaPending> d =
			(java.util.Deque<AccountConnectPlugin.InvDeltaPending>) f.get(plugin);
		d.addLast(p);
	}

