/*
 * Pile-centred counterparty candidates, and the one rule that turns them into a name.
 *
 * ⚠ THE HONESTY CONSTRAINT, AND IT IS THE WHOLE POINT OF THIS FILE.
 * The Take happens in the OTHER player's client. Nothing in our packet stream names the taker, so
 * no amount of geometry can prove who picked a pile up. What this class produces is EVIDENCE with a
 * stated strength, never a fact. The one case worth naming is the case a human would accept on
 * sight: exactly one other player standing ON the pile's own tile at the moment it vanished.
 * Everything else — two people on the tile, nobody on it, somebody one step away — resolves to
 * AMBIGUOUS or UNKNOWN and names nobody.
 *
 * WHY PILE-CENTRED AND NOT PLAYER-CENTRED. The existing nearby snapshot measures from OUR
 * character. In a drop trade the staff member routinely walks off before the customer arrives, so a
 * player at distance 0 from US is not on the pile, and a player on the pile can be many tiles from
 * us. Measuring from the pile's own tile is the difference between an answer and a coincidence.
 *
 * Pure: JDK only, no RuneLite types, so every branch is testable without a client.
 */
package com.osrsbestinslot.export;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class DropCandidates
{
	private DropCandidates()
	{
	}

	/** How the counterparty question was answered for one pile. Written onto every removal row. */
	public static final String STATUS_RESOLVED = "RESOLVED";
	/** More than one player stood on the pile's tile. Somebody took it; we cannot say which. */
	public static final String STATUS_AMBIGUOUS = "AMBIGUOUS";
	/** Nobody was on the tile, or the cause was not an early removal. Nothing to say. */
	public static final String STATUS_UNKNOWN = "UNKNOWN";

	/**
	 * How far from the pile a player is still recorded as a candidate.
	 *
	 * Wider than the resolve rule on purpose. Only distance 0 ever RESOLVES, but a reviewer looking
	 * at an ambiguous pile wants to see who else was around, and the server-side resolver may later
	 * weigh persistence across ticks. Recording more than we resolve on costs a few bytes and keeps
	 * the evidence; resolving on more than distance 0 would be a guess.
	 */
	public static final int CANDIDATE_RANGE_TILES = 3;

	/**
	 * Cap on recorded candidates for one pile. A crowded tile cannot make the row unbounded. Nearest
	 * first, so the players that matter are never the ones cut.
	 */
	public static final int CANDIDATE_CAP = 8;

	/** Animation id when the client reports none (the game's own idle value). */
	public static final int NO_ANIMATION = -1;

	/** One observed player, in world tiles. Deliberately a plain value type, not a RuneLite Player. */
	public static final class Observed
	{
		public final String rsn;
		public final int x;
		public final int y;
		public final int plane;
		public final int combatLevel;
		/** The animation the player was playing at the moment of observation, or NO_ANIMATION. */
		public final int animation;

		public Observed(String rsn, int x, int y, int plane, int combatLevel)
		{
			this(rsn, x, y, plane, combatLevel, NO_ANIMATION);
		}

		public Observed(String rsn, int x, int y, int plane, int combatLevel, int animation)
		{
			this.rsn = rsn;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.combatLevel = combatLevel;
			this.animation = animation;
		}
	}

	/**
	 * One sighting of a Telekinetic Grab aimed at a tile: the travelling projectile (which names its
	 * caster) or the impact graphic on the tile (which does not). A grab takes a pile from up to ten
	 * tiles away, so a player standing on the tile when it vanished may be an innocent bystander.
	 */
	public static final class TelegrabSighting
	{
		public final int x;
		public final int y;
		public final int plane;
		public final int tick;
		/** "projectile" or "impact". */
		public final String via;
		/** Caster name, only known from a projectile. Null otherwise. */
		public final String caster;
		/** True when the caster is our own character. */
		public final boolean casterSelf;
		public final int casterX;
		public final int casterY;

		public TelegrabSighting(int x, int y, int plane, int tick, String via,
			String caster, boolean casterSelf, int casterX, int casterY)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.tick = tick;
			this.via = via;
			this.caster = caster;
			this.casterSelf = casterSelf;
			this.casterX = casterX;
			this.casterY = casterY;
		}
	}

	/**
	 * How many ticks before a pile vanished a grab aimed at its tile still counts. The projectile flies
	 * for a few ticks before the item leaves the ground; ten covers the longest cast range with margin
	 * and keeps an old, unrelated grab on the same tile out.
	 */
	public static final int TELEGRAB_WINDOW_TICKS = 10;

	/** Telekinetic Grab reaches about ten tiles; a caster further out cannot have taken the pile. */
	public static final int TELEGRAB_RANGE_TILES = 10;

	/** The player animation of a Telekinetic Grab cast (gameval AnimationID.HUMAN_CASTTELEGRAB). */
	public static final int TELEGRAB_CAST_ANIMATION = 723;

	/** The travelling grab projectile (gameval SpotanimID.TELEGRAB_TRAVEL). */
	public static final int TELEGRAB_PROJECTILE = 143;

	/** The grab's impact graphic on the item's tile (gameval SpotanimID.TELEGRAB_IMPACT). */
	public static final int TELEGRAB_IMPACT = 144;

	/**
	 * The Telekinetic Grab evidence for one pile, or null when no grab aimed at this exact tile was seen
	 * in the window before the removal. A named caster comes from the most recent projectile.
	 */
	public static Map<String, Object> telegrabAt(List<TelegrabSighting> sightings,
		int pileX, int pileY, int pilePlane, int removalTick)
	{
		if (sightings == null)
		{
			return null;
		}
		TelegrabSighting latest = null;
		TelegrabSighting named = null;
		java.util.Set<String> via = new java.util.TreeSet<>();
		for (TelegrabSighting s : sightings)
		{
			if (s == null || s.x != pileX || s.y != pileY || s.plane != pilePlane)
			{
				continue;
			}
			int age = removalTick - s.tick;
			if (age < 0 || age > TELEGRAB_WINDOW_TICKS)
			{
				continue;
			}
			via.add(s.via);
			if (latest == null || s.tick >= latest.tick)
			{
				latest = s;
			}
			if ((s.caster != null || s.casterSelf) && (named == null || s.tick >= named.tick))
			{
				named = s;
			}
		}
		if (latest == null)
		{
			return null;
		}
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("via", new ArrayList<>(via));
		m.put("ticks_before", removalTick - latest.tick);
		if (named != null)
		{
			if (named.casterSelf)
			{
				m.put("caster_self", true);
			}
			else
			{
				m.put("caster", named.caster);
				m.put("caster_dx", named.casterX - pileX);
				m.put("caster_dy", named.casterY - pileY);
				m.put("caster_dist", tileDistance(named.casterX, named.casterY, pileX, pileY));
			}
		}
		return m;
	}

	/**
	 * Chebyshev distance, which is how OSRS measures tiles: one diagonal step is distance 1, not
	 * 1.41. A Euclidean measure here would make a diagonal neighbour look further away than an
	 * orthogonal one when the game treats them identically.
	 */
	public static int tileDistance(int ax, int ay, int bx, int by)
	{
		return Math.max(Math.abs(ax - bx), Math.abs(ay - by));
	}

	/**
	 * Candidates for one pile, nearest first, each carrying its offset FROM THE PILE.
	 *
	 * A player on another plane is never a candidate whatever its x/y: planes are separate floors and
	 * a player directly above the pile cannot have taken it.
	 */
	public static List<Map<String, Object>> candidatesAt(List<Observed> players,
		int pileX, int pileY, int pilePlane)
	{
		List<Map<String, Object>> out = new ArrayList<>();
		if (players == null)
		{
			return out;
		}
		List<Observed> inRange = new ArrayList<>();
		for (Observed p : players)
		{
			if (p == null || p.rsn == null || p.rsn.isEmpty() || p.plane != pilePlane)
			{
				continue;
			}
			int d = tileDistance(p.x, p.y, pileX, pileY);
			// The mechanically relevant area is not one fixed ring: a player further out who is casting
			// Telekinetic Grab can take the pile from range, so that player is a candidate too.
			if (d <= CANDIDATE_RANGE_TILES
				|| (d <= TELEGRAB_RANGE_TILES && p.animation == TELEGRAB_CAST_ANIMATION))
			{
				inRange.add(p);
			}
		}
		// Order for the cap: players ON the pile first, then grab casters (they can take it from range),
		// then everyone else by distance; name breaks ties so the order is stable.
		Collections.sort(inRange, (a, b) ->
		{
			int c = Integer.compare(capRank(a, pileX, pileY), capRank(b, pileX, pileY));
			if (c == 0)
			{
				c = Integer.compare(tileDistance(a.x, a.y, pileX, pileY), tileDistance(b.x, b.y, pileX, pileY));
			}
			return c != 0 ? c : a.rsn.compareTo(b.rsn);
		});
		for (Observed p : inRange)
		{
			if (out.size() >= CANDIDATE_CAP)
			{
				break;
			}
			Map<String, Object> m = new LinkedHashMap<>();
			m.put("rsn", p.rsn);
			// Offsets FROM THE PILE, not from us. A reader must never have to know where we stood.
			m.put("dx", p.x - pileX);
			m.put("dy", p.y - pileY);
			m.put("dist", tileDistance(p.x, p.y, pileX, pileY));
			m.put("cb", p.combatLevel);
			// What the player was DOING when the pile vanished. A floor pickup plays one animation and a
			// grab cast another, so a reader can rule out a bystander who was doing something else.
			m.put("anim", p.animation);
			out.add(m);
		}
		return out;
	}

	private static int capRank(Observed p, int pileX, int pileY)
	{
		if (tileDistance(p.x, p.y, pileX, pileY) == 0)
		{
			return 0;
		}
		return p.animation == TELEGRAB_CAST_ANIMATION ? 1 : 2;
	}

	/**
	 * The resolve rule: exactly ONE candidate standing on the pile's own tile.
	 *
	 * @return the RSN when that holds, otherwise null. The caller pairs this with
	 *         {@link #statusFor} so the row always states which of the three answers it got.
	 */
	public static String resolveCounterparty(List<Map<String, Object>> candidates)
	{
		if (candidates == null || candidates.isEmpty())
		{
			return null;
		}
		String only = null;
		for (Map<String, Object> c : candidates)
		{
			Object d = c.get("dist");
			if (!(d instanceof Number) || ((Number) d).intValue() != 0)
			{
				continue;
			}
			if (only != null)
			{
				return null;		// two on the tile — ambiguous, and never a coin toss
			}
			Object rsn = c.get("rsn");
			if (!(rsn instanceof String) || ((String) rsn).isEmpty())
			{
				return null;
			}
			only = (String) rsn;
		}
		return only;
	}

	/**
	 * The status that goes on the row.
	 *
	 * AMBIGUOUS is reserved for the case where somebody WAS on the tile and we still cannot name
	 * them. An empty tile is UNKNOWN, not ambiguous: there is no competing explanation to choose
	 * between, only an absence of evidence, and conflating the two would make "we saw two people"
	 * indistinguishable from "we saw nobody".
	 */
	public static String statusFor(List<Map<String, Object>> candidates, String resolved)
	{
		if (resolved != null)
		{
			return STATUS_RESOLVED;
		}
		if (candidates != null)
		{
			for (Map<String, Object> c : candidates)
			{
				Object d = c.get("dist");
				if (d instanceof Number && ((Number) d).intValue() == 0)
				{
					return STATUS_AMBIGUOUS;
				}
			}
		}
		return STATUS_UNKNOWN;
	}
}

/*
 * Which frames of a general-store visit are uploaded: the visit start, every buy / sell / taken
 * moment, and a low-rate baseline between them, inside one fixed per-visit frame budget.
 *
 * WHY, measured. The store path used to keep only the NEWEST 12 seconds (360 frames at 30fps) in a
 * ring. A delivery visit is longer than that. Arengees, 2026-09-25: sells from 16:37:59 to 16:39:51,
 * uploaded frames 16:39:55 to 16:40:06, every frame static. The clip was intact and showed no sale.
 * The sales are the evidence, so the budget now follows the sales instead of the clock.
 *
 * WHAT IS KEPT
 *   * the first START_MILLIS of the visit at the full sample rate;
 *   * for every moment (a buy/sell click, a store_taken): PRE_ROLL_MILLIS before it and
 *     POST_ROLL_MILLIS after it at the full sample rate. The frames before a click cannot be chosen
 *     after it, so frames that are not kept are HELD in a short pre-roll until they expire;
 *   * one frame every BASELINE_PERIOD_MILLIS in between, so the gaps are not blank.
 *
 * THE BUDGET. maxFrames (360) and maxBytes (16 MiB since PIO-014; the ring had 12MB) for the WHOLE
 * visit. That keeps a visit at the same number of 40-frame chunks, so it spends the same share of
 * the server's per-token burst rate limit as before. When a new frame would exceed the budget, one
 * frame is evicted from the LARGEST group (start, each moment, baseline). Groups therefore shrink
 * toward equal size, and no moment can be pushed out by later ones. Inside a group the frame
 * farthest from its moment goes first, until only the core span around the moment is left; after
 * that the core is thinned evenly. So a visit with many sales still shows every click and the
 * inventory change after it, at a lower rate, rather than losing whole sales.
 *
 * Why not DropCaptureRate: it drops the capture time of pre-roll frames (the upload needs it for
 * each chunk's captured_at) and it has no whole-visit budget, because a drop session streams its
 * segments. Changing it would touch the drop-proof path, which is reviewed separately.
 *
 * Pure: JDK only, the clock is a parameter, thread-safe (encode thread offers, client thread marks
 * moments, the uploader snapshots).
 */
package com.osrsbestinslot.export;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class StoreVisitClip
{
	/** Full-rate footage at the start of the visit: the approach to the shop. */
	public static final long START_MILLIS = 2_000L;
	/** Full-rate footage kept BEFORE a moment. */
	public static final long PRE_ROLL_MILLIS = 2_000L;
	/** Full-rate footage kept AFTER a moment. A click resolves on the next game tick (0.6s). */
	public static final long POST_ROLL_MILLIS = 3_000L;
	/** One baseline frame per this many milliseconds between moments. */
	public static final long BASELINE_PERIOD_MILLIS = 1_000L;
	/**
	 * The core span of a moment: from just before the click to two game ticks after it, which is
	 * where the item leaves the inventory. Edges outside it are evicted first; the core is only
	 * ever thinned, never cut away.
	 */
	public static final long CORE_BEFORE_MILLIS = 500L;
	public static final long CORE_AFTER_MILLIS = 1_200L;

	/** Group id of baseline frames. The start is group 0; moments are 1, 2, 3 ... */
	static final int BASELINE = -1;
	static final int START = 0;

	private static final class Frame
	{
		final byte[] jpeg;
		final long at;
		final int group;

		Frame(byte[] jpeg, long at, int group)
		{
			this.jpeg = jpeg;
			this.at = at;
			this.group = group;
		}
	}

	/** A snapshot for the uploader: frames and their capture times, oldest first. */
	public static final class Snapshot
	{
		public final List<byte[]> frames;
		public final List<Long> capturedAtMillis;

		Snapshot(List<byte[]> frames, List<Long> capturedAtMillis)
		{
			this.frames = frames;
			this.capturedAtMillis = capturedAtMillis;
		}
	}

	private final int maxFrames;
	private final long maxBytes;
	private final int maxFrameBytes;

	private final List<Frame> kept = new ArrayList<>();
	private final Deque<Frame> preRoll = new ArrayDeque<>();
	/** Anchor time per group id: index 0 is the visit start, then one entry per moment. */
	private final List<Long> anchors = new ArrayList<>();
	private long keptBytes;
	private long lastBaselineMillis = Long.MIN_VALUE;

	public StoreVisitClip(int maxFrames, long maxBytes, int maxFrameBytes)
	{
		if (maxFrames < 1 || maxBytes < 1 || maxFrameBytes < 1)
		{
			throw new IllegalArgumentException("budget must be positive");
		}
		this.maxFrames = maxFrames;
		this.maxBytes = maxBytes;
		this.maxFrameBytes = maxFrameBytes;
	}

	/** One sampled, encoded frame. The visit starts at the first frame offered. */
	public synchronized void offer(byte[] jpeg, long atMillis)
	{
		if (jpeg == null || jpeg.length == 0 || jpeg.length > maxFrameBytes)
		{
			return;
		}
		if (anchors.isEmpty())
		{
			anchors.add(atMillis);
		}
		expirePreRoll(atMillis);
		int latest = anchors.size() - 1;
		long latestAt = anchors.get(latest);
		int group;
		if (latest > START && atMillis >= latestAt - PRE_ROLL_MILLIS && atMillis <= latestAt + POST_ROLL_MILLIS)
		{
			group = latest;
		}
		else if (atMillis - anchors.get(START) < START_MILLIS)
		{
			group = START;
		}
		else if (lastBaselineMillis == Long.MIN_VALUE || atMillis - lastBaselineMillis >= BASELINE_PERIOD_MILLIS)
		{
			group = BASELINE;
			lastBaselineMillis = atMillis;
		}
		else
		{
			preRoll.addLast(new Frame(jpeg, atMillis, BASELINE));
			return;
		}
		keep(new Frame(jpeg, atMillis, group));
	}

	/**
	 * A buy, sell or taken moment happened now. Claims the held pre-roll and opens a full-rate window.
	 * A moment before the first frame is anchored at its own time and still gets its window.
	 */
	public synchronized void onMoment(long atMillis)
	{
		if (anchors.isEmpty())
		{
			anchors.add(atMillis);
		}
		anchors.add(atMillis);
		int group = anchors.size() - 1;
		expirePreRoll(atMillis);
		List<Frame> held = new ArrayList<>(preRoll);
		preRoll.clear();
		for (Frame f : held)
		{
			if (f.at >= atMillis - PRE_ROLL_MILLIS)
			{
				keep(new Frame(f.jpeg, f.at, group));
			}
		}
	}

	/** Kept frames and their capture times, oldest first. */
	public synchronized Snapshot snapshot()
	{
		List<Frame> sorted = new ArrayList<>(kept);
		sorted.sort((a, b) -> Long.compare(a.at, b.at));
		List<byte[]> frames = new ArrayList<>(sorted.size());
		List<Long> times = new ArrayList<>(sorted.size());
		for (Frame f : sorted)
		{
			frames.add(f.jpeg);
			times.add(f.at);
		}
		return new Snapshot(frames, times);
	}

	public synchronized int size()
	{
		return kept.size();
	}

	public synchronized long byteSize()
	{
		return keptBytes;
	}

	/** Frames held for the lookbehind. Bounded by PRE_ROLL_MILLIS at the sample rate. */
	public synchronized int preRollSize()
	{
		return preRoll.size();
	}

	/** Number of buy / sell / taken moments marked this visit. */
	public synchronized int momentCount()
	{
		return Math.max(0, anchors.size() - 1);
	}

	public synchronized void clear()
	{
		kept.clear();
		preRoll.clear();
		anchors.clear();
		keptBytes = 0;
		lastBaselineMillis = Long.MIN_VALUE;
	}

	private void expirePreRoll(long nowMillis)
	{
		while (!preRoll.isEmpty() && nowMillis - preRoll.peekFirst().at > PRE_ROLL_MILLIS)
		{
			preRoll.pollFirst();
		}
	}

	private void keep(Frame f)
	{
		kept.add(f);
		keptBytes += f.jpeg.length;
		while (!kept.isEmpty() && (kept.size() > maxFrames || keptBytes > maxBytes))
		{
			Frame victim = kept.remove(victimIndex());
			keptBytes -= victim.jpeg.length;
		}
	}

	/** The frame to evict: from the largest group, its farthest edge, else its densest spot. */
	private int victimIndex()
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (Frame f : kept)
		{
			counts.merge(f.group, 1, Integer::sum);
		}
		int group = BASELINE;
		int best = -1;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			int g = e.getKey();
			int n = e.getValue();
			// Ties go to the baseline, then to the OLDEST moment: a moment still filling keeps its frames.
			if (n > best || (n == best && group != BASELINE && (g == BASELINE || g < group)))
			{
				best = n;
				group = g;
			}
		}
		if (group != BASELINE)
		{
			long anchor = anchors.get(group);
			int far = -1;
			long farDist = -1;
			for (int i = 0; i < kept.size(); i++)
			{
				Frame f = kept.get(i);
				if (f.group != group)
				{
					continue;
				}
				// Before the anchor counts double: the outcome after a click matters more than the approach.
				long dist = f.at < anchor ? 2 * (anchor - f.at) : f.at - anchor;
				boolean inCore = f.at >= anchor - CORE_BEFORE_MILLIS && f.at <= anchor + CORE_AFTER_MILLIS;
				if (!inCore && dist > farDist)
				{
					farDist = dist;
					far = i;
				}
			}
			if (far >= 0)
			{
				return far;
			}
		}
		return densestIndex(group);
	}

	/** The frame of this group closest in time to the previous one: removing it thins evenly. */
	private int densestIndex(int group)
	{
		int prev = -1;
		int pick = -1;
		long pickGap = Long.MAX_VALUE;
		List<Integer> idx = new ArrayList<>();
		for (int i = 0; i < kept.size(); i++)
		{
			if (kept.get(i).group == group)
			{
				idx.add(i);
			}
		}
		idx.sort((a, b) -> Long.compare(kept.get(a).at, kept.get(b).at));
		for (int i : idx)
		{
			if (prev >= 0)
			{
				long gap = kept.get(i).at - kept.get(prev).at;
				if (gap < pickGap)
				{
					pickGap = gap;
					pick = i;
				}
			}
			prev = i;
		}
		return pick >= 0 ? pick : idx.get(0);
	}
}

/*
 * Buffers the last N rendered frames for the store delivery-proof burst (frames uploaded raw; the server stitches — no encoder in the plugin).
 *
 * A bounded ring buffer of ALREADY-ENCODED JPEG frames. The recorder pushes the last few
 * seconds of frames in; when the shop closes, the buffer is snapshotted and uploaded off the
 * client thread. Oldest frames are evicted once the capacity is reached, so memory stays
 * bounded regardless of how long a shop stays open.
 *
 * ⚠ The ring holds byte[], NOT BufferedImage, and that is load-bearing (fixed 2026-09-02).
 * It used to hold raw BufferedImages, which at 30fps x 12s x 704px is ~1.1MB per frame and
 * ~400MB retained for the length of a shop visit — past RuneLite's 512MB default max heap, so
 * the client froze in continuous GC and the burst never uploaded. Encoded, the same 360 frames
 * are ~30KB each, about 11MB. Never store decoded images here.
 *
 * Standalone + unit-testable: it depends only on the JDK (no RuneLite, no AWT), so the
 * frame -> buffer path can be driven with synthetic byte arrays under test.
 */
package com.osrsbestinslot.export;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/** Fixed-capacity FIFO of the most recent ENCODED frames. Thread-safe (encode thread adds, upload thread snapshots). */
public class ClipRingBuffer
{
	private final int capacity;
	private final Deque<byte[]> frames;

	/**
	 * @param capacity max frames retained (= fps * seconds). Must be &gt;= 1.
	 */
	public ClipRingBuffer(int capacity)
	{
		if (capacity < 1)
		{
			throw new IllegalArgumentException("capacity must be >= 1");
		}
		this.capacity = capacity;
		this.frames = new ArrayDeque<>(capacity);
	}

	/** Append an encoded frame, evicting the oldest if at capacity. Null / empty frames are ignored. */
	public synchronized void add(byte[] frame)
	{
		if (frame == null || frame.length == 0)
		{
			return;
		}
		if (frames.size() >= capacity)
		{
			frames.pollFirst();
		}
		frames.addLast(frame);
	}

	/** Ordered copy (oldest -&gt; newest) for the uploader. */
	public synchronized List<byte[]> snapshot()
	{
		return new ArrayList<>(frames);
	}

	/** Total retained bytes — the number this class exists to bound. */
	public synchronized long byteSize()
	{
		long total = 0;
		for (byte[] f : frames)
		{
			total += f.length;
		}
		return total;
	}

	public synchronized int size()
	{
		return frames.size();
	}

	public int capacity()
	{
		return capacity;
	}

	public synchronized void clear()
	{
		frames.clear();
	}
}
